-- WoWUkraine: переклади Журналу підземель (боси: ім'я + лорний опис).
-- Автоген pipeline/generate_db.py. Ключ — journalEncounterID (C_EncounterJournal).
-- Значення: n = укр. ім'я боса, d = укр. опис (може бути відсутній).
local ns = _G.WoWUkraineNS
if not ns then return end
ns.journal = {
    [89] = {n="Глубток", d="У нападі люті Ґлубток вивільнив свої могутні магічні здібності й обернув рідне оґряче кубло на попіл. Прочувши про його руйнівні таланти, дефаї найняли велетенського оґра-мага наглядати за робітниками — головним наглядачем Мертвих Копалень."},
    [90] = {n="Гелікс Шестернелам", d="Колишній ремісник картелю Білджвотер, Гелікс отримав від Братства Дефаїв пропозицію з такою сумою, якої й не снилося безіменному інженерові Орди, аби він трудився на них. Він хутко погодився на роботу й зрікся колишньої відданості... як учинив би будь-який кмітливий ґоблін."},
    [91] = {n="Жнець ворогів 5000", d="Інженери дефаїв провели багато довгих днів, удосконалюючи нову модель жнеця на основі вузла «Жнець Ворогів 4000». Щойно його буде завершено, братство вірить, що цей механічний жах краятиме броньованих солдатів Стормвінда, мов коса — пшеницю."},
    [92] = {n="Адмірал Рипснарл", d="Коли Джеймса Гаррінгтона вразило прокляття ворґенів, він знищив свою люблячу родину й моряцьку кар'єру за одну моторошну ніч кровожерності. Узявши собі ім'я Рипснарл, він утік до Західного Краю, а згодом погодився очолити грізний колос Братства Дефаїв."},
    [93] = {n="«Капітан» Печивко", d="Печивко проголосив себе капітаном колоса Братства Дефаїв після загибелі його попереднього командира. Хоч він і досі виконує свій офіційний обов'язок головного кухаря, кожен, хто сумнівався в правдивості його капітанського титулу, чомусь зазнавав тяжкого харчового отруєння."},
    [95] = {n="Ванесса ВанКліф", d="Ще малою дівчинкою Ванесса стала свідком жахливої смерті свого батька, колишнього очільника Братства Дефаїв, Едвіна ВанКліфа. Відтоді вона перебрала на себе провід братства й плете задуми помсти Стормвінду з темних коридорів твердині дефаїв у Мертвих Копальнях."},
    [96] = {n="Барон Ешбері", d="Убитий ворґенами й піднятий до нежиття Відступниками, зрадник барон Ешбері грається зі своїми ворогами, тримаючи їх живими, щоб завдати їм якнайбільше болю й страждань."},
    [97] = {n="Барон Сільверлейн", d="Барон Сільверлейн був господарем замку, перш ніж той упав під натиском ворґенів Аруґала. Тепер його проклятий дух прикликає тих самих вовкозвірів, що його роздерли, аби карати нових порушників, які вдираються до його оселі."},
    [98] = {n="Командир Спрінґвейл", d="Вірний воїн, привид командира Спрінґвейла блукає залою ради, завдаючи нечестивих ударів, щоб помститися за свого володаря, барона Сільверлейна."},
    [99] = {n="Лорд Волден", d="Права рука Ґодфрі, пихатий лорд Волден поклявся заплатити будь-яку ціну, навіть смерть, аби служити своєму спільникові. Нині, ставши одним із нежиті, Волден має намір дотримати слова, нападаючи на супротивників кригою та отрутою."},
    [100] = {n="Лорд Ґодфрі", d="Спираючись на своє минуле гілнеаського вельможі та агента Відступників, підступний і винахідливий Лорд Ґодфрі орудує двома пістолями й командує невпинними плотожерними упирями."},
    [101] = {n="Леді Наз'джар", d="Леді Наз'джар відіграла ключову роль у відвоюванні Вашж'іру в жорстоких квалдірів, чим заслужила прихильність своєї королеви Азшари. Нещодавно Наз'джар очолила напад на Нептулона й зуміла загнати могутнього володаря елементалів у його тронну залу."},
    [102] = {n="Командир Улток, Гнійний Принц", d="Улток — неймовірно древня істота, яку його повелителі, Прадавні Боги, послали допомогти Леді Наз'джар у вторгненні до Трону Припливів. Сповнений лиховісної сили, Улток командує легіонами своїх побратимів-безликих у найглибших ущелинах довкола Вашж'іру."},
    [103] = {n="Згинач Розуму Ґур'ша", d="Після своїх звитяжних зусиль біля Безодняної Тріщини шаман Земляного Кільця Ерунак Кам'яномовець був викрадений силами наг і поневолений Згиначем Розуму Ґур'шою. Існує побоювання, що ця паразитична аберація захопила цілковитий контроль над розумом, тілом і нищівними шаманськими здібностями Ерунака."},
    [104] = {n="Озумат", d="Оповіді про жахливого кракена, що тероризує відкриті моря Азероту, колись вважали лише міфом... але вже ні. Якимось лихим робом наги підкорили Озумата — патріарха всіх кракенів — своїй волі й нацькували його на Нептулона та його прибічників."},
    [105] = {n="Ром'оґґ Костолом", d="Один із рідкісних оґрів-«проміжних ланок» на Запределлі, Ром'оґґ Костолом привернув увагу культу Сутінкового Молота своїм безжальним поводженням з оґрами. Тепер він панує над Камерою Спалення, тамуючи свою спрагу завдавати мук іншим."},
    [106] = {n="Корла, Вісниця Сутінків", d="Колись досвідчена чарівниця Кірін Тор, Корла нині служить Сутінковому Молоту з непохитною відданістю. Вона благословляє побратимів-фанатиків, скеровуючи есенції нетер-драконів, щоб перетворити цих вірян на грізних сутінкових драконідів."},
    [107] = {n="Карш Сталегин", d="Велетенський драконід Карш Сталегин трудиться в Сутінковій Кузні, викуючи зброю війни з рідкісної ртуті. Хоча витвори Карша за звичайних умов майже незламні, за високих температур вони стають крихкими, мов іржаве залізо."},
    [108] = {n="Краса", d="Минуле Краси — оповідь стара, як світ, пісня давня, як саме слово. Після того, як супутника Краси, Звіра, убили герої на Шпилі Чорноскеля, ця гончиця разом із чотирма вцілілими цуценятами приєдналася до Сутінкового Молота, прагнучи покарати створінь, що вбили її пару."},
    [109] = {n="Піднесений Лорд Обсидіус", d="За свою непохитну відданість і схильність до жорстокості могутній шаман Дессірік Розпусний був удостоєний піднесення: темного ритуалу, що влив у нього сили елементалів і перетворив його на потвору, відому як Піднесений Лорд Обсидіус."},
    [110] = {n="Корборус", d="Дезвінг поневолив величезного хробака-свердлуна Корборуса й змусив його викопувати незліченні поклади елементію, потрібного, щоб викувати нову луску Аспекта Драконів. Та коли Дезвінг полетів геть, Корборус вирвався на волю й тепер у сліпій люті несамовито трощить усе в Кам'яному Серці."},
    [111] = {n="Слабгайд", d="Силою Аспекта Землі, яку посилили Прадавні Боги, Дезвінг легко схилив кам'яних вірмів Діпгольму служити культу Сутінкового Молота. Один із найзапекліших серед цих створінь, Слабгайд, сподівається заслужити прихильність Дезвінга, винищуючи всіх зухвальців, що насмілюються ступити в Кам'яне Серце."},
    [112] = {n="Озрук", d="Озрук вартує Кам'яне Серце ще від часів створення Діпгольму. Невідомо, чому Озрук лишився тут, та нині очевидно: страж вважає кожного, хто протистоїть Дезвінгові, загрозою для Діпгольму, а отже, його треба знищити."},
    [113] = {n="Верховна жриця Азіл", d="Верховна жриця Азіл — одна з небагатьох, хто пережив спілкування з моторошними володарями культу Сутінкового Молота, хоча розсудку в неї лишилося обмаль. Вона сіє жах серед нижчих сектантів, аби ті без вагань жертвували собою, щойно накажуть їхні володарі."},
    [114] = {n="Великий візир Ертан", d="Ертан за наказом свого володаря Асаада боронить Вершину Вихору від усіх земних створінь, що насмілюються вдертися до цих володінь. Щоб виконувати свій обов'язок, ця елементальна шляхтянка дістала владу над первісними силами блискавки й вітру."},
    [115] = {n="Альтаїрус", d="Велетенський штормовий вірм Альтаїрус незмінно стереже летючі помости Вершини Вихору. Сама енергія штормів пульсує в цій істоті, і подейкують, ніби він керує вітряними течіями, що шмагають елементальну фортецю."},
    [116] = {n="Асаад, Каліф Зефірів", d="Грізного елементаля Асаада призначив стражем Вершини Вихору сам Аль'Акір. Тепер, коли Сіамата, Володаря Південного Вітру, ув'язнили тол'віри Неферсету, Асаад вірить, що зможе піднестися до Конклаву Вітру, якщо сумлінно виконуватиме свій обов'язок."},
    [117] = {n="Генерал Гусам", d="Самі титани призначили генерала Гусама одним із найголовніших стражів Улдуму. Після того як Сіамат, Володар Південного Вітру, зцілив тол'вірів Неферсету від прокляття плоті, Гусам очолив повстання, що скінчилося ув'язненням повітряного елементаля."},
    [118] = {n="Локмо", d="Серед хаосу повстання Неферсету проти Сіамата пігмей Ауг тягнув усі скарби, які тільки міг, зі стародавнього міста тол'вірів. Серед своїх Ауг шанований не лише за хитрість, а й за лютого улюбленця-кролокіска на ім'я Локмо."},
    [119] = {n="Верховний пророк Барім", d="Верховний пророк Барім — освячений духовний провідник Неферсету. Разом із генералом Гусамом він підняв своїх одноплемінців проти Сіамата й ув'язнив повітряного елементаля. Та попри все якась темна сила досі жене Баріма та його послідовників тероризувати Улдум."},
    [122] = {n="Сіамат", d="Очищення тол'вірів Неферсету від прокляття плоті вкрай виснажило грізного елементаля Сіамата. Саме в цю мить слабкості тол'віри завдали удару й магією ув'язнили Сіамата в самому серці свого прадавнього, обвіяного пісками міста."},
    [124] = {n="Храмовий Вартовий Ангуур", d="В останні дні, коли Зали Першопочатку ще слугували титанічним силам, Храмовий Вартовий Ангуур був наділений силою волі, потрібною, щоб володіти Світлом. Отримавши таку міць, він дістав і обов'язок судити про чистоту кожного, хто входить до цього комплексу."},
    [125] = {n="Землелют Птах", d="Перед гробницею Землелюта Птаха пісок усіяний кістками створінь, очищених Ангууром. Кажуть, ніби Птах здатен підкоряти ці рештки своїй волі й насилати їх на тих, кому вдалося оминути першу лінію оборони комплексу."},
    [126] = {n="Анрафет", d="Ремонтну одиницю Анрафет було створено, щоб порядкувати внутрішніми механізмами Залів Першопочатку. Якщо комплекс буде осквернений сторонніми сутностями, Анрафет задіє програми, покликані знищити порушників будь-якою ціною."},
    [127] = {n="Ісісет, Конструкт Магії", d="Ісісет слугує для впорядкування арканних енергій, що містяться в Залах Першопочатку та породжуються ними. Переказ мовить, що цей конструкт упав у захват від власної арканної майстерності й тієї досконалості, якою вона начебто його наділяє."},
    [128] = {n="Аммунае, Конструкт Життя", d="Хоч систему перевпорядкування в Залах Першопочатку й створено, щоб розкласти Азерот на первинні елементи, вона ж дарує і нове життя. Задля цього конструкт Аммунае керує природними енергіями, що течуть крізь комплекс, аби життя існувало й у перекованому Азероті."},
    [129] = {n="Сетеш, Конструкт Руйнування", d="Зважаючи на призначення Залів Першопочатку, титани визнали за потрібне створити Сетеша — конструкт, що владарює над силами руйнування. Якби Сетеш колись піддався псуванню, наслідки були б катастрофічні."},
    [130] = {n="Радж, Конструкт Сонця", d="Радж наглядає за енергіями, які в незліченної кількості його родичів і запалювали іскру життя, і гасили її. Уважаний за наймогутнішого з-поміж побратимів-конструктів, Радж володіє силою обрушити на Азерот лють тисячі сонць."},
    [139] = {n="Арґалот", d="Не маючи змоги втримати велетенського володаря ям Арґалота в камерах могутньої Фіолетової Фортеці Даларану, маги Кірін-Тору не мали іншого вибору, як ув'язнити цього потужного демона під Тол-Барадом."},
    [140] = {n="Окку'тар", d="Цей ненажерливий демон вирвався зі своєї клітки й прорвався до західного крила в'язниці, пожерши всіх ув'язнених, яких там тримали. Через ненажерливість тіло Окку'тара так роздулося, що він уже не може вибратися назовні, і це крило в'язниці фактично стало його новою камерою."},
    [154] = {n="Конклав Вітру", d="Відколи Сіамат, Володар Південного Вітру, ув'язнений тол'вірами Неферсета, лейтенанти Аль'Акіра змагаються за владу, що звільнилася в Конклаві Вітру. Інші члени конклаву — це Аншал, Володар Західного Вітру, чиї пориви здатні зцілювати союзників або труїти ворогів; Рогаш, Володар Східного Вітру, чиї бурі можуть стерти на порох найвеличніші гори; і Незір, Володар Північного Вітру, чиї крижані шторми забрали більше життів, ніж усі інші володарі вітрів разом узяті."},
    [155] = {n="Аль'Акір", d="Наділений неабияким розумом і хитрістю, Аль'Акір Володар Вітрів колись був головним тактиком у жахливих арміях Прадавніх Богів. Після Катаклізму він став на бік Дезвінга й обернув свою божественну могутність проти тол'вірів — давніх ворогів повітряних елементалів."},
    [156] = {n="Галфус Вірмолом", d="Наділений неприродною силою та витривалістю від Чо'ґалла, еттін Галфус Вірмолом ловить драконів, щоб використати їх як паливо для ритуалів культу Сутінкового Молота. Задля цього він поневолив величезного протодракона, аби той допомагав йому полювати на крилату здобич."},
    [157] = {n="Тераліон і Валіона", d="Чарами прискорені до дорослого віку, Валіона й Тераліон мали стати взірцем для нового виводка сутінкових драконів і повести свою зграю винищувати все живе в Азероті. Натомість вони марнують свою неймовірну могутність на безкінечні чвари й бійки одне з одним."},
    [158] = {n="Рада Піднесених", d="Найпотужніші культисти Сутінкового Молота, скривлені магією в елементарних істот, члени Ради Піднесених давно забули про своє існування простими смертними. Зі свого мерзенного святилища вони наглядають за добором нових кандидатів на піднесення."},
    [167] = {n="Чо'ґалл", d="Під владою Чо'ґалла орчий клан Сутінкового Молота перетворився на смертоносний культ, одержимий Прадавніми Богами та їхнім вісником Дезвінгом. Тривалий зв'язок із темними володарями огидно спотворив і розум, і тіло Чо'ґалла."},
    [168] = {n="Сінестра", d="Колишня перша супутниця Дезвінга, Сінестра створила перших сутінкових драконів, але згодом була знищена одним зі своїх жахливих витворів. Тепер, обернена на понівечену оболонку, оживлену підступною магією, Сінестра наглядає за створенням нових сутінкових виводків."},
    [169] = {n="Оборонна система Омнотрон", d="Оборонну систему Омнотрон колись прославляли як найбільше технологічне диво дворфів Темного Заліза. Коли Нефаріан прибув до Спуску Чорнокрила, він пристосував занедбану систему, щоб знищувати кожного, хто вдереться до його лабораторій."},
    [170] = {n="Маґмав", d="Маґмав — це колосальний лавовий черв, прикликаний із Вогняних Просторів багато століть тому слугами Раґнароса з Темного Заліза. Нефаріан здебільшого вважає Маґмава докучливою паразитом, та полюбив згодовувати звірюці свої невдалі експерименти... і слуг."},
    [171] = {n="Атрамедес", d="Атрамедес, або Експеримент 25463-D, — це невдала спроба наділити чорне драконеня загостреними чуттями. Токсична мазь, нанесена на драконя, позбавила його зору, змусивши покладатися на слух і нюх задля виживання. Трагічна історія... якби Атрамедес не був таким лихим."},
    [172] = {n="Чимаерон", d="Жахливий. Бридкий. Лихий. Убий його."},
    [173] = {n="Малоріак", d="Людина на ім'я Малорі був обдарованим молодим алхіміком, доки його не викрав Нефаріан і не зрощив із трупом драконнародженого. Наслідок — Малоріак — незграбний прислужник, у якому лишилася тьмяна іскра колишнього розуму."},
    [174] = {n="Кінець Нефаріана", d="Син Дезвінга, Нефаріан, здобув лиху славу жахливими спробами створити хроматичних драконів із есенцій різних драконячих зграй Азероту. Після своєї смерті в Лігві Чорнокрилих він був оживлений і за наказом Дезвінга мав продовжити свої підступні задуми."},
    [175] = {n="Верховний жрець Веноксіс", d="Спершу посланий убити Гаккара, Веноксіс став рабом цієї вбивчої істоти, а згодом загинув від рук героїв Азероту. Зусиллями посіпак Душосдирача Веноксіса вирвали зі світу духів і змусили боронити Зул'Ґуруб разом із його отруйними зміїними прислужниками."},
    [176] = {n="Кривавий володар Мандокір", d="Сумнозвісний Кривавий володар Мандокір помер у муках, а потім, багато років тому, тролі Кривавоскальпи спаплюжили його тіло. Нині ширяться чутки, що Мандокір знову блукає джунглями Тернової долини, використовуючи труп могутнього вождя Кривавоскальпів Ґан'зули як вмістилище для свого злостивого духу."},
    [177] = {n="Сховище Безумства — Ґрі'лек", d="Серед сповнених ненависті духів у Сховищі Безумства є Ґрі'лек, жахливий троль, якого лоа позбавили здатності зцілюватися; Ренатакі, сумнозвісний і садистський воїн; Газза'ра, провидець, замучений лиховісними видіннями майбутнього; та Вушулай, могутній боєць, що нуртує силою бур."},
    [178] = {n="Сховище Безумства — Газза'ра", d="Серед сповнених ненависті духів у Сховищі Безумства є Ґрі'лек, жахливий троль, якого лоа позбавили здатності зцілюватися; Ренатакі, сумнозвісний і садистський воїн; Газза'ра, провидець, замучений лиховісними видіннями майбутнього; та Вушулай, могутній боєць, що нуртує силою бур."},
    [179] = {n="Сховище Безумства — Ренатакі", d="Серед сповнених ненависті духів у Сховищі Безумства є Ґрі'лек, жахливий троль, якого лоа позбавили здатності зцілюватися; Ренатакі, сумнозвісний і садистський воїн; Газза'ра, провидець, замучений лиховісними видіннями майбутнього; та Вушулай, могутній боєць, що нуртує силою бур."},
    [180] = {n="Сховище Безумства — Вушулай", d="Серед сповнених ненависті духів у Сховищі Безумства є Ґрі'лек, жахливий троль, якого лоа позбавили здатності зцілюватися; Ренатакі, сумнозвісний і садистський воїн; Газза'ра, провидець, замучений лиховісними видіннями майбутнього; та Вушулай, могутній боєць, що нуртує силою бур."},
    [181] = {n="Верховна жриця Кілнара", d="Коли Верховну жрицю Арлокк убили, лоа-пантера Бетекк обрала її сестру, Кілнару, своїм новим смертним обранцем. Підтримуючи нещодавній союз між племенами Ґурубаші та Зандалар, Кілнара нацькувала своїх лютих прислужників-пантер на нічого не підозрюваних мешканців краю."},
    [184] = {n="Занзіл", d="Вигнаний з племені Черепокрадів за те, що перетворював своїх побратимів-тролів на безвольних рабів, Занзіл нещодавно отримав місце серед Ґурубаші від Джин'до Богоборця в обмін на зміцнення сил Зул'Ґурубу. Добре відомо, що його отруйні елексири здатні підняти навіть мерців з могил."},
    [185] = {n="Джин'до Богоборець", d="Після поразки в Зул'Ґурубі дух Джин'до мучився від того, що не зумів виконати волю Гаккара. Нещодавно Джин'до знайшов шлях назад у світ і поневолив Душолупа. Сповнений жахливої сили грізного бога, Джин'до прагне повернути імперії Ґурубаші її колишню славу."},
    [186] = {n="Акіл'зон", d="Колишній шаман племені амані, Акіл'зон мав надприродний хист у поводженні зі стихією повітря. Цей талант привернув увагу Лорда Маледикцій Малакрасса й зробив пошук вмістилища для орлиного бога тролів легкою справою."},
    [187] = {n="Налоракк", d="Лорд Маледикцій Малакрасс вважав Налоракка — уславленого і своєю страхітливою люттю, і дикою силою на полі бою — ідеальною посудиною для сутності ведмежого бога."},
    [188] = {n="Джан'алай", d="Драконояструби — спритні хижаки, що шматують ворогів гострими, як бритва, кігтями. Такий норов і манеру нападу полюбляв і один з найвправніших розбійників племені амані, Джан'алай."},
    [189] = {n="Галаззі", d="Рисі Азероту — люті мисливці, що роздирають здобич іклами й кігтями. Лорд Маледикцій Малакрасс розважив, що буде цілком справедливо запечатати сутність бога-рисі в одному з найкращих мисливців племені."},
    [190] = {n="Лорд Маледикцій Малакрасс", d="Подейкують, що Лорд Маледикцій Малакрасс — найстрашніший знахар племені амані за останні десятиліття. Він учинив немислиме й запечатав сутності кількох могутніх тваринних богів тролів у їхніх найсильніших захисниках... залишивши найтемнішу з них собі."},
    [191] = {n="Даакара", d="Щоб заповнити порожнечу влади, що лишилася по смерті їхнього колишнього воєначальника Зул'джина, уцілілі тролі племені амані обрали свого улюбленого захисника, Даакару Непереможного, аби повернути втрачену славу."},
    [192] = {n="Бет'тілак", d="Матріарх виводка Жаротканів, Бет'тілак та її безжальні нащадки тамують голод, висмоктуючи магму й вогонь із тіл елементалів. Щоб дати своїм виводкам більше поживи, Бет'тілак виткала по всьому лігву мережу вогненного павутиння, аби ловити необачну здобич."},
    [193] = {n="Лорд Ріоліт", d="Ріоліт — один з найдревніших елементалів, що існують, народжений з первісного вогню, який викував сам Азерот. Він відповідає за створення нових елементалів у Вогняних землях і досі плекає палку ненависть до титанів за те, що вважає величезним зухвальством — за своє переселення."},
    [194] = {n="Алісразор", d="Коли війська Рагнароса ринули на гору Гіджал, зелена дракониха Алісра зрадила своїх союзників і допомогла визволити підступного верховного друїда Фандрала Стаґгельма. У нагороду її очистили вогнем, і вона відродилася грізним вогняним яструбом."},
    [195] = {n="Шаннокс", d="Полум'яні ходаки належать до найстрашніших вартових стихій у Вогняних Просторах. Шаннокс не виняток. Як головний ловчий і псар пекельних гончаків Рагнароса, Шаннокс никає елементним царством зі своїми двома найлютішими бестіями: Ріплімбом і Рейджфейсом."},
    [196] = {n="Балерок, Воротар", d="Балерок здобув славу нещадного бійця ще під час воєн стихій прадавнього Азероту. Тепер, ув'язнений у Вогняних Просторах, він майже втратив розум. Мало хто з елементалів наважується турбувати його, боячись стати жертвою його жаги до битви."},
    [197] = {n="Мажордом Стаґгельм", d="Втрата сина Валстанна у Війні Сипучих Пісків остаточно зламала дух Фандрала Стаґгельма. Тепер, наділений Рагнаросом владою нового Мажордома Вогняних Просторів (на місце загиблого Мажордома Екзекутуса) і як ватажок зрадливих Друїдів Полум'я, Фандрал прагне накликати загибель на Азерот, аби не жити у світі без свого улюбленого дитяти."},
    [198] = {n="Рагнарос", d="Рагнарос, володар Вогняних Просторів, утілює лють і руйнацію первісного пекельного вогню, що викував сам Азерот. Маючи обіцянку спопелити Азерот без втручання Нептулона й Теразан, Рагнарос прагне вгамувати Прадавніх Богів, спаливши Світове Дерево Нордрассіл."},
    [283] = {n="Відлуння Тіранди", d="Колишня провідниця нічних ельфів і верховна жриця Елуни, цей скручений часом уламок Тіранди Віспервінд нині блукає пустками спустошеного майбутнього Азероту. Огорнута вічною північчю, вона майже втратила з очей утішне світло Елуни."},
    [285] = {n="Відлуння Джайни", d="Змучений уламок Джайни Праудмур було розщеплено й влито в розбиті частини її посоха. Щоб відновити рівновагу шляхів часу, це відлуння треба здолати. Та нищівна магічна сила колись гордовитої володарки Терамору навряд чи покинула її понівечений часом привид. У цьому майбутньому Азероті вона лише розділена й чекає..."},
    [289] = {n="Мурозонд", d="Нині живучи поза часом, Мурозонд колись був великим Аспектом Драконів Ноздорму Позачасовим. Після того як титани показали йому власну смерть, змученого Ноздорму Прадавні Боги хитрістю схилили спробувати побороти свою смертність. Унаслідок цього Ноздорму розтрощив шляхи часу й створив Нескінченна зграя драконів... поставивши під загрозу саме майбутнє Азероту."},
    [290] = {n="Перот'арн", d="Як і багато його побратимів-високорідних, Перот'арн присягнув на вірність зіпсутому Ксавію в обмін на дари демонічної сили.\n\nЯк володар демонічної магії і носій прокляття сатира, Перот'арн стоїть біля палацу Азшари на захист Палаючого Легіону, готовий знищити всіх, хто сподівається завадити входженню Темного Титана Саргераса в Азерот."},
    [291] = {n="Королева Азшара", d="Пісень про красу, велич і могутність королеви Азшари не злічити, та саме її марнославство підштовхнуло високорідних прикликати Палаючий Легіон. Тепер вона спостерігає, як її найвірніші магістри живлять портал, крізь який Саргераса введуть в Азерот, і не вагаючись дозволяє безлічі своїх слуг загинути перед приходом Темного Титана."},
    [292] = {n="Маннорот і Варо'тен", d="Варо'тен, очільник особистої варти королеви Азшари, і Маннорот, повелитель ями, чия кров зіпсує весь народ орків, стоять останнім рубежем оборони проти тих, хто сподівається завадити Саргерасу ввійти в Азерот. Хоч і Тіранда, і Іллідан билися досі звитяжно, доля Азероту вирішиться на самому краю Колодязя Вічності."},
    [311] = {n="Морчок", d="Найпотужніший елементаль, що досі під владою Дезвінга, Морчок — колись пасивний охоронець — нині переконаний, що спокій настане для нього лише зі згубою Азероту. Морчок шаленіє проти підмурків Храму Драконового Спокою, останнього промінчика надії Азероту в Годину Сутінків."},
    [317] = {n="Гаґара Скувальниця Бур", d="Гаґара, одна з перших учениць арканної магії серед Покинутих, виявила несподіваний хист для того, хто взявся вчитися так пізно. Та в недисциплінованих спробах закувати елементалів у служіння вона й сама потрапила в пастку й була спотворена Володарем Вітру Ал'Акіром. Тепер, люто віддана культу Сутінкового Молота, Гаґара кує інших на поталу своїм елементальним господарям."},
    [318] = {n="Хребет Дезвінга", d="Коли Дезвінг уперше спрямував силу Душі Дракона проти інших зграй, вивільнені могутні енергії загрожували розірвати саме його тіло. Замість того щоб зректися цієї зброї, він велів сплавити зі своєю лускою адамантитові пластини, щоб утримати тіло вкупі. Згодом підсилені елементієм, ці пластини нині є його слабкістю — єдиним вразливим місцем у смертоносній постаті Дезвінга."},
    [322] = {n="Аркуріон", d="Напади Орди й Альянсу на культ Сутінкового Молота винищили багатьох грізних елементальних піднесених. Виняток — Аркуріон, могутній крижаний піднесений, якому доручено вбити Тралла й повернути Душу Дракона. Якщо ця спотворена елементальна істота досягне успіху, ніщо вже не завадить Дезвінгу настати Годині Сутінків."},
    [323] = {n="Відлуння Сильвани", d="Породжене розбитими шляхами часу й замкнене в Рубіновому Драконячому Святилищі, збожеволіле уламкове відлуння очільниці Покинутих, Сильвани Віндраннер, неспокійно вичікує. Втративши все й не здатне віднайти спокій, це змучене відлуння прагне нагоди вивільнити свою темну лють на все живе, що ще лишилося в цих спустошених, скривлених часом пустках."},
    [324] = {n="Воєначальник Зон'озз", d="Незліченні віки тому Воєначальник Зон'озз і його воїни вели нескінченну війну проти сил Ктуна та Йоґґ-Сарона. Минули тисячоліття, та воєначальник досі служить хаотичній могутності Прадавнього бога Н'Зота. Тепер Дезвінг вивільнив цього легендарного безликого, щоб розчавити захисників Храму Драконового Спокою."},
    [325] = {n="Йор'садж Невсипущий", d="Відколи впав Бастіон Сутінків, Йор'садж Невсипущий запопадливо допомагав Дезвінгу, даючи Руйнівнику засоби вивільнити ще більше безликих з їхніх в'язниць глибоко під землею. Їхнє число незліченне, а їхня сила — поза будь-якою мірою, і Йор'садж розраховує пожати похмуру винагороду за свою віддану службу."},
    [331] = {n="Ультраксіон", d="Радше потвора з темної енергії, ніж дракон, Ультраксіон провів своє коротке життя, поглинаючи есенцію полонених драконів Порожнечі. Ультраксіон — єдиний сутінковий дракон, якого Дезвінг похвалив, і його пиху затьмарюють хіба що тріскотливі енергії, що струмують крізь його спотворену подобу. Вірний своєму господареві, Ультраксіон клянеться спричинити падіння Храму Драконового Спокою."},
    [332] = {n="Воєвода Чорноріг", d="Хоч колись їх було безліч, нині лишилося тільки кілька десятків сутінкових драконів. На цих загартованих уцілілих сидять останні рештки армії культу Сутінкового Молота: добірні вершники драків з особистого ескорту Дезвінга. Очолювані підступним Воєводою Чорнорогом, вони рухаються з нечестивою метою, гнані бажанням захистити свого темного господаря."},
    [333] = {n="Безумство Дезвінга", d="Спотворена маса розплавленої ненависті й незбагненної могутності — цей безформний, позбавлений розуму жах неможливо спинити. Те, що колись лишалося від Нельтаріона Землевартового, давно зникло: його розум і душу зіпсували та поглинули його володарі, Прадавні Боги. Усе, чого прагне ця потворна істота, — це руйнування, знищення і кінець усього сущого."},
    [335] = {n="Ша Сумніву", d="Тілесне втілення підозри було ув'язнене в Нефритовому лісі після того, як імператор Шаохао здолав цю істоту десять тисяч років тому. Згодом Ша Сумніву одержимо зосередився на Нефритовому Змії — Ю'лон, Духові Мудрості й Передбачення, — і тепер тішиться думкою про те, щоб осквернити її домівку."},
    [339] = {n="Алізабал, Володарка Ненависті", d="Кірін Тор ув'язнили Алізабал у своїй грізній Фіолетовій Фортеці невдовзі по тому, як зіпсовані маги прикликали шиварру до Азероту. Попри арканні обереги, що стримували її сили, сам лише злобний вплив демониці змушував її варту в раптових нападах люті вбивати одне одного. Її переведення до Фортеці Барадін напередодні Катаклізму тільки погіршило і без того жахливі умови зруйнованої в'язниці."},
    [340] = {n="Відлуння Бейна", d="Розлючена власною неспроможністю захистити світ і, головне, Орду, ця спотворена часом тінь Бейна Бладгуфа блукає серед руїн Обсидіанової святині драконів. Хоч він і досі такий само могутній, як верховний вождь тауренів із теперішнього часу, у цьому розбитому майбутньому Азероті змучене провиною відлуння — не більше ніж розладнана посудина невгамовної злоби й гніву."},
    [341] = {n="Архієпископ Бенедикт", d="Архієпископ Бенедикт — шанований очільник Церкви Святого Світла. Роками його мудре керівництво допомагало людству пройти крізь похмурі часи. Та під його видимою доброчесністю криється приголомшлива правда: Бенедикт присягнувся знищити все живе в Азероті, ставши знаряддям свого темного володаря... Дезвінга."},
    [342] = {n="Асіра Світанкова Згуба", d="Колишня найманка Асіра Сонцесвітла спершу остерігалася працювати на культ Сутінкового Молота, але щедра плата культистів швидко її переконала. З часом вона піддалася згубному впливу своїх темних роботодавців і навіть зайшла так далеко, що взяла собі ім'я Світанкова Згуба. Як одну з найсмертоносніших убивць культу, Асіру послали винищити Тралла та його товаришів."},
    [368] = {n="Ґаму-Ра", d="Коли прибув культ Сутінкового Молота, його послідовники пробудили й ув'язнили одне з останніх мирних створінь, що жили в храмі Елуни. Роками культ тішився, мордуючи велетенську черепаху, шматуючи її розум і тіло, доки вона не піддалася божевіллю. Назвавши звіра Ґаму-Ра, культисти намагаються опанувати його лють, щоб захищати своє лігво."},
    [369] = {n="Верховна Дізнавачка Ґерстан", d="Культистка Сутінкового Молота Ґерстан завжди потурала розкошам життя: вишуканим стравам, гарному вбранню та оздобленим самоцвітами знаряддям тортур. Удень і вночі моторошні крики її в'язнів лунають крізь горезвісний Блок Ув'язнення клану Чорного Заліза. Ґерстан гордо називає цей жахливий галас своєю симфонією зойків і завжди радо додає до хору ще один голос."},
    [370] = {n="Лорд Роккор", d="Лорд Роккор зневажає підступи й зрадництво інших вогняних елементалів. Аби не служити поруч зі своїм родом у Розплавленому Ядрі, ця могутня істота навмисне розгнівала Володаря Вогню. Ризикована гра Роккора окупилася: його вигнали з ядра й змусили в самоті стерегти Глибини Чорної Скелі."},
    [371] = {n="Псар Ґребмар", d="Пси Ґребмара Блохобородого — єдина родина, яку він коли-небудь знав. Давним-давно осиротілий дворф почав розводити собак, щоб ті служили йому супутниками й сторожами. Коли псар не патрулює Глибини Чорної Скелі зі своїми відданими звірами, він часто частує їх найкращим елем Чорного Заліза з «Похмурого Пияка»."},
    [372] = {n="Кільце Закону", d="За злочини проти дворфів Темного Заліза кара лише одна: смерть. Прадавня традиція велить винним сплатити криваву ціну на Кільці Закону, б'ючись із дикими створіннями, зібраними з усього Азероту. Донині невідомо, чи бодай хтось пережив це жорстоке горнило."},
    [373] = {n="Піромант Лорґрейн", d="Колись шанований член Земляного Кільця, Лорґрейн пристав до культу Сутінкового Молота з причин, що й досі лишаються загадкою для його колишніх союзників. Зрештою він дістався Глибин Чорної Скелі, де раптом зацікавився славетним архітектором Темного Заліза Франклорном Форджрайтом. Мета його теперішньої одержимості незрозуміла, та Лорґрейн лишається вірним своєму культові й ворогом усіх, хто йому протистоїть."},
    [374] = {n="Лорд Інцендіус", d="Барон Ґеддон навчив Інцендіуса опановувати свою руйнівну силу, та барон ніяк не сподівався, що його вихованець стане таким смертоносно вправним. Дедалі дужче остерігаючись, що Інцендіус може його повалити, Ґеддон вислав полум'яного елементаля з Вогняної Серцевини, аби той охороняв легендарне Чорне Ковадло дворфів Темного Заліза."},
    [375] = {n="Вартовий Стілґісс", d="Після років відданості імператорові Тауріссану хитрому магові Стілґіссу довірили охорону скарбниці його клану в Чорному Сховищі. Близький друг вірного дворфа, псар Ґребмар, відзначив цю подію, подарувавши Стілґіссу одного зі своїх лютих псів — Верека. Маг знайшов звірюзі добрий ужиток, тримаючи її при собі, щоб відлякувати охочих обікрасти сховище."},
    [376] = {n="Файнеус Дарквайр", d="Головний архітектор Файнеус Дарквайр здобув свій титул, видаючи ідеї обдарованіших каменярів за власні. Його пиха й підступи накликали гнів його попередника, Франклорна Форджрайта, навіть із-за могили. Привид покійного головного архітектора прагне відібрати в Дарквайра свій неймовірно могутній молот — Айронфел — перш ніж його встигнуть ужити на зле."},
    [377] = {n="Баель'Ґар", d="Жахливий розплавлений велетень Баель'Ґар важко крокує Дорогою Темного Заліза — приголомшливим витвором дворфської інженерії, висіченим у Глибинах Чорної Скелі. Раґнарос видобув велетня із серця Вогняних земель, щоб той стеріг величезні запечатані двері в одному кінці дороги. За легендою, лише Володар Вогню та найвищі за рангом члени клану Темного Заліза знають, що лежить за цими таємничими вратами."},
    [378] = {n="Генерал Анґерфордж", d="За життя, сповнене студій, генерал Анґерфордж став знавцем дворфської військової історії й тактики. Нещодавно він накликав на себе лють імператора Даґрана Тауріссана, написавши нищівний трактат про поразки свого клану в минулих війнах. Та попри цей політичний промах, Анґерфордж — дворф Темного Заліза до самих кісток. Він проллє кров — і загине, якщо доведеться, — заради свого народу й свого імператора."},
    [379] = {n="Володар Големів Арґельмах", d="Довічна одержимість Арґельмаха безсмертям спонукала його кувати зачаровані конструкти за власною подобою. Подейкують, що він також устиг зануритися в якусь чорну магію, що дала б змогу новим витворам володаря големів правити за вмістилища для його духу, якщо його тіло з плоті й крові буде знищено."},
    [380] = {n="Герлі Блекбрет", d="Сказати, що Блекбрет — завсідник «Похмурого Бражника», було б неабияким применшенням. За понад десять років цей капосний п'яниця залишив таверну лише раз — аби викрасти цілком таємний рецепт лаґеру Громоварів. Часом Блекбрет тверезів настільки, щоб зварити це питво самотужки, і запевняє, що воно дарує незбагненну силу й відвагу."},
    [381] = {n="Фаланкс", d="Донедавна п'яні бійки спалахували в «Похмурому Бражнику» мало не щодня. Шинкар Плаґер Спаззрінг зменшив частоту цих сутичок за допомогою Фаланкса — могутнього голема-вибивайла, запрограмованого підтримувати лад у таверні й усувати буйних відвідувачів із крайньою силою."},
    [383] = {n="Корок Дзумкокільце", d="Кажуть, що в \"Похмурому Хлептії\" кожен знає твоє ім'я. Цією атмосферою товариства завсідники завдячують наполегливій праці Дзумкокільце, прокаженого ґнома, який після падіння Ґномреґана шукав нового життя в Чорноскельних Глибинах. Попри минуле, коли він бавився зі злом як чорнокнижник, він пишається своєю роботою шинкаря таверни й пильнує, щоб кухлі його гостей ніколи не порожніли."},
    [384] = {n="Посол Полум'яний Батіг", d="За свою непохитну службу Раґнаросу Полум'яний Батіг піднявся до рангу посла при клані Темного Заліза. Спершу ця ница істота зневажала своїх ґномів-союзників, та згодом стала шанувати їхній потяг до руйнування. На знак солідарності Полум'яний Батіг стереже Палату Зачарування — священне місце, де ґноми наснажують свою зброю."},
    [385] = {n="Семеро", d="Століття тому чаклун-тан Тауріссан і семеро його найпотужніших союзників із Темного Заліза випадково прикликали Раґнароса до Азероту й прирекли весь свій клан на рабство. Хоча Семеро загинули під час ритуалу, їхні неспокійні духи досі блукають Чорноскельними Глибинами, прокляті служити своєму володареві-елементалю та нинішньому правителю Темного Заліза."},
    [386] = {n="Маґмус", d="Посол Полум'яний Батіг доручив розплавленому велетню Маґмусу стерегти тронну залу імператора Даґрана Тауріссана, та навіть це не вгамувало тривог правителя Темного Заліза. У вічному страху перед убивцями імператор також віддав Маґмусу владу над низкою вогнедишних статуй біля своїх королівських покоїв."},
    [387] = {n="Імператор Даґран Тауріссан", d="Імператор Даґран Тауріссан править разом із принцесою Мойрою із ворожого клану Бронзобородів. Точаться суперечки, чи зачарував імператор свою наречену, чи вона приєдналася до нього з власної волі. Хай там як, незмінна присутність Тауріссана віщує лихо для майбутнього його клану. Доки він живий, Темне Залізо лишатиметься пішаками Раґнароса й грізною загрозою для королівств усього Азероту."},
    [388] = {n="Верховний Лорд Омокк", d="Омокк править оґрами шпиля залізною рукою. Чимало підлеглих кидали йому виклик на двобій, сподіваючись захопити титул верховного лорда, та всі полягли, не завдавши й одного удару. Це загадкове явище породило чутки, що Омокка боронить темна магія."},
    [389] = {n="Тіньова Мисливиця Вош'ґаджин", d="Вош'ґаджин уславилася серед тролів своєю вродою — і психопатичними нахилами. Майстриня мистецтва тіньових мисливців, вона володіє грізними вроками, прокляттями та цілющою магією."},
    [390] = {n="Майстер Війни Вун", d="Під час Другої війни Вун водив невеликі загони на зухвалі вилазки в самісіньке серце території високорідних ельфів. Хитрий троль приєднався до фальшивої Орди, бо хотів стати її головним стратегом, а не тому, що вірив в ідеологію Блекгенда. Вун убачає у своєму відколотому угрупованні відчайдушних аутсайдерів і насолоджується тим, щоб долати непереборні труднощі."},
    [391] = {n="Матір Тліюче Павутиння", d="Століття тому ґноми Темного Заліза прокопалися до лігва Тліюче Павутиння й випустили велетенську павучиху до зал шпиля. Її виводок відтоді тільки розростався — настільки, що навіть війська Блекгенда бояться мандрувати володіннями Тліюче Павутиння."},
    [392] = {n="Урок Думгаул", d="Думгаул — справжній проводир оґрів шпиля. Ця зловісна постать обплутала свого довіреного помічника, Верховного Лорда Омокка, підступною магією, щоб той замість нього керував поплічниками Думгаула. Він докладає чималих зусиль, аби підтримувати цю облуду, безжально вбиваючи будь-яких оґрів, що кидають виклик владі верховного лорда."},
    [393] = {n="Інтендант Зіґріс", d="Після Першої війни орк-мисливець Зіґріс зажив лихої слави тим, що вистежував біженців зі Стормвінда й винищував їх, наче дичину. Він ненавидить тісні, задушливі зали Пік Чорної Скелі, та певен: настане день, коли він знову полюватиме просто неба."},
    [394] = {n="Галікон", d="Галікон походить із давнього роду великих воргів, виведених за свою лють і відданість. За багато років матір лігва привела на світ безліч диких нащадків. Подейкують, що насправді вона — демонічна гончиха, яку Ренду Блекхенду подарував володар ям Палаючого Легіону."},
    [395] = {n="Ґізрул Слинявий", d="Дуже мало хто з Темної Орди бачив відлюдькуватого й непередбачуваного Ґізрула. Звір виходить зі свого темного лігва лише тоді, коли його кличе подруга, Галікон. Ці дві жахливі істоти привели на світ одних із найбільших — і найлютіших — воргів в історії орків."},
    [396] = {n="Володар Вірмталак", d="Чорний драконід Вірмталак керує військами нижнього шпиля, поки ті готуються до нападу на дворфів. Він не плекає любові до фальшивої Орди чи її грубих посіпак і пожертвує скільки завгодно слуг Блекхенда, аби захистити свого володаря, Нефаріана."},
    [402] = {n="Зеврім Тернокопит", d="Прагнучи будь-що довести свою цінність Палаючому Легіону, Зеврім Тернокопит запевнив своїх володарів, що зможе поневолити могутніх прадавніх, які досі блукали Дайр-Маулом. Коли власної сили виявилося замало, Тернокопит звернувся до інших живих істот по додаткову енергію: він шматував їх на своєму жертовному вівтарі й висмоктував їхню сутність в останні, болісні миті їхнього життя."},
    [403] = {n="Гідропороддя", d="Коли сатир Зеврім Тернокопит спробував підкорити елементалів Дайр-Маула, він зосередився на Гідропородді, що спокійно мешкало у водоймі під його вівтарем. Поки сатир чинив свої блюзнірські жертовні ритуали, елементаль дедалі дужче непокоївся й шаленів, накидаючись на демонічних поплічників Тернокопита. Минали роки, і Тернокопит енергією своїх жертв розпалював у Гідропородді нестримну лють, потроху скоряючи його волю своїм наказам."},
    [404] = {n="Летендріс", d="Спотворена енергія Дайр-Маула привабила Леттендріс здалеку, даючи їй надію вгамувати нестерпну спрагу до арканної магії. Із жил і зв'язок жертовних бранців вона сплела павутину, щоб витягувати зіпсуту силу зі східного крила. На свою втіху вона виявила, що цей пристрій здатен накопичувати величезні запаси нездоланної потуги — досить, щоб знищити всіх її ворогів."},
    [405] = {n="Алззін Дикоформ", d="Алззін Дикоформ прагне не менш ніж цілковитого зіпсуття Фераласа, та доки він не знайшов Святилище Ельдретарра в Дайр-Маулі, успіхів мав небагато. Маючи у своєму розпорядженні силу поневолених прадавніх, Алззін зосередив життєву снагу довколишнього лісу у своєму лігві, що дало йому змогу керувати нею за власним бажанням."},
    [406] = {n="Тендріс Викрутодрев", d="Тендріс Викрутодрев був незламним захисником Ельдре'Таласа, його серце нерозривно сплелося з долею міста. Коли Великий Розкол розтрощив землю, його рішучість не похитнулася, та як упродовж наступних десяти тисяч років зіпсуття просочувалося в руїни, так само воно вразило й дух прадавнього."},
    [407] = {n="Ілліанна Воронодуб", d="Ілліанна Воронодуб разом зі своєю вірною супутницею Феррою колись була найціннішою мисливицею принца Тортельдріна — доки не відмовилася виконати наказ свого володаря стратити її друзів. На кару він убив Ілліанну та її ведмедицю, але демонічною силою прив'язав їхні душі до тіл, прирікши їх лишатися в Дайр-Маулі як мертві оборонці."},
    [408] = {n="Магістр Календріс", d="Коли принц Тортельдрін зажадав винищення більшості своїх підданих, виконати його волю доручили найвідданішим прибічникам. Магістр Календріс без вагань убив багатьох необачних Шен'дралар, але один з приречених ельфів завдав йому смертельної рани під час нищівної битви. Попри свою загибель, дух Календріса досі блукає Лютим Бором, обороняючи владу Тортельдріна."},
    [409] = {n="Іммол'тар", d="У відчайдушній спробі повернути могутність і безсмертя, втрачені після руйнування Колодязя Вічності, Шен'дралар прикликали демона до західного крила Лютого Бору й ув'язнили його в силовому полі, щоб живити власні закляття енергією цього жаху Порожнечі. Майже 10 000 років Іммол'тар не міг ні чинити опір, ні навіть поворухнутися — лишалося тільки спостерігати й чекати дня, коли він вирветься на волю й роздере плоть своїх поневолювачів."},
    [410] = {n="Принц Тортельдрін", d="Після руйнування Колодязя Вічності принц Тортельдрін утримував владу над уцілілими Шен'дралар, ув'язнивши демона в руїнах Ельдре'Таласа й дозволивши підданим черпати його силу. Дотик демонічної могутності спотворив розум Тортельдріна, і коли істота почала слабнути, принц наказав убити багатьох своїх васалів, щоб насолоджуватися зіпсутою енергією лишилися тільки він і його найфанатичніші прибічники."},
    [411] = {n="Вартовий Мол'дар", d="Мол'дар — ревно відданий вартовий з-поміж оґрів Ґордока. Він певен, що король Ґордок подарував йому пару зачарованих рукавиць, завдяки яким він шостий рік поспіль лишається чемпіоном свого народу з боротьби на руках. Насправді ж король Ґордок просто викинув цю могутню броню, а Мол'дар лише першим її знайшов."},
    [412] = {n="Кріг Топтун", d="Не раз і не двічі підступні вбивці знаходили свою погибель, ненароком зачепивши Крігів кухоль елю. Хоч на варті він часто валяється п'яний без тями, ніщо не доводить цього оґра до шаленої люті швидше, ніж звук його дорогоцінного питва, що розхлюпується на кам'яну підлогу."},
    [413] = {n="Вартовий Фенґус", d="Відколи Чо'Раш Спостерігач сказав йому, що йому судилося зустріти кохану на службі, Фенґус майже кожну хвилину проводить, патрулюючи володіння Ґордока."},
    [414] = {n="Вартовий Сліп'кік", d="Дехто може подумати, що Сліп'кік просто обережний, але насправді він ще й лінивий. Замість того щоб кинути виклик королю Ґордоку відкрито, Сліп'кік порпається в пастках і старих зламаних магічних пристроях, сподіваючись урешті завдати смертельного удару без краплі ризику чи поту."},
    [415] = {n="Капітан Кромкраш", d="Навіть серед оґрів капітан Кромкраш сумно прославився своєю спалахливою люттю до кожного, хто посміє образити його чи короля Ґордока. Незгоду він придушує безжально, та ще менше терпить тих, хто й досі розносить чутки про його давній палкий роман із ґнолом."},
    [416] = {n="Чо'Раш Спостерігач", d="Зазвичай Чо'Раш не пристає на жоден бік, але коли Улрок здобував владу, було ясно, що кинути йому виклик нікому. Король хутко призначив Чо'Раша своїм головним радником, гадаючи, що дві голови зроблять його вдвічі винахідливішим за пересічного оґра."},
    [417] = {n="Король Ґордок", d="Щоб правити оґрами Ґордока, треба лише проголосити себе королем... а тоді знищити всіх, хто міг би заперечити. Король Ґордок — тоді ще відомий просто як Улрок — зміцнив свою владу, переконавши з десяток найдужчих воїнів свого народу водночас кинути виклик королю. Шалена сутичка лишила більшість суперників мертвими чи пораненими, і клинок Улрока легко стяв уцілілих разом із виснаженим боєм королем. І донині оґри Ґордока стишеним голосом згадують «День Крові»."},
    [418] = {n="Натовпотовкач 9-60", d="За часів розквіту Ґномреґана винахідники змагалися за визнання, зіштовхуючи свої творіння одне з одним. Мехінженер Оґлторп Обнотікус збудував непереможного робота, і це здобуло йому повагу при дворі верховного майстра. Сікко Термаплаґ викрав креслення Обнотікуса й створив за ними гігантську версію машини. Він випустив свою підробку на волю, і жахливі наслідки змусили правлячу раду вигнати невинного Обнотікуса. Натовпотовкач 9-60 і досі лишається одним з улюблених (украдених) винаходів Термаплаґа."},
    [419] = {n="Ґраббіс", d="Радіоактивний газ, що затопив місто, мав розлютити троґів і повбивати ґномів, і брутальний задум Термаплаґа спрацював бездоганно. Та один троґ зреагував на речовину незвично: Ґраббіс почав рости. І рости. Цього побічного ефекту Сікко не передбачив, але він ніколи не марнував цінних (і небезпечних) ресурсів. Тепер цей велетенський троґ патрулює тунелі Ґномреґана. Його вірний улюбленець-василіск Хрумкало допомагає Ґраббісу винюхувати витоки газу, смачні гриби й ще смачніших зайд."},
    [420] = {n="В'язкий Осад", d="Колись міцні та елегантно складні водогони Ґномреґана нині перетворилися на опромінене місиво, повне токсичного слизу. Самотній водяний елементаль, що мешкав у ґномському водоносному шарі, потрапив у пастку забруднення, і зараза спотворила його чисту подобу. Тепер він блукає залами Ґномреґана в гніві й муках — рідке втілення мерзенної отрути зради Термаплаґа."},
    [421] = {n="Електрокутор 6000", d="Мехінженер Термаплаґ — нетерплячий ґном. Замість того щоб піддавати свої винаходи низці випробувань на безпеку та дієвість, він поспіхом виводить їх у поле й береться за наступний проєкт. Електрокутор 6000 був його першою спробою приборкати електрику як зброю за допомогою перевантаженого механотанка. Лейтенант Том «Шкварконоги» Кренкл, єдиний солдат, який вижив за кермом Електрокутора, став тепер мало не героєм серед прокажених ґномів."},
    [422] = {n="Мехінженер Термаплаґ", d="Убивця, зрадник і самопроголошений король ґномів, мехінженер Сікко Термаплаґ править радіоактивними залами Ґномреґана несправною залізною рукою. Його підданці численні, лихі та божевільні настільки, щоб боронити свого схибленого короля від будь-якого вторгнення з горішнього світу. Саме безум Термаплаґа й робить його таким небезпечним: він має досить хитрості, щоб знищити все довкола, не дбаючи про власне життя. Недарма навіть чудовиська Ґномреґана бояться його."},
    [423] = {n="Ноксіон", d="Ноксіон — живе втілення скверни. Терадрас наказала своєму союзникові, лорду Лихоязику, створити цього гнилісного елементаля, щоб той став могутнім слугою та вірним улюбленцем і розраяв самотність принцеси. Ноксіон розносить свою токсичну есенцію в ті частини Мародона, які ще не зів'яли під лиховісним впливом Терадрас."},
    [424] = {n="Гострохльост", d="Гострохльоста створили, щоб супроводжувати Ноксіона по Мародону. З часом це нове творіння стало одним з найдорожчих слуг принцеси. Гострохльост невпинно блукає печерами поряд з Ноксіоном, шматуючи колючими лозами будь-яку незіпсовану рослинність, яку лиш знайде."},
    [425] = {n="Винахідник Ґізлок", d="Винахідник Ґізлок і ще п'ятеро мисливців за самоцвітами прокралися до Мародона, щоб видобути його надзвичайно цінні кристали. Їхній задум обернувся справжнім лихом, коли сатири перебили всіх у загоні, окрім Ґізлока. Цей ґоблін, замкнений у печерах і доведений до межі божевілля, тепер вважає себе новим володарем підземних теренів."},
    [426] = {n="Поневолювач Кор'ул", d="Культ Сутінкового Молота наказав своєму могутньому каральнику, Поневолювачу Кор'улу, очистити печери від усього, що їм не підкоряється. Гелігаст першим упав під нищівною силою Кор'ула, який потім захопив владу над печерними мурлоками. Кор'ул лишив понівечене тіло Гелігаста на видноті як доказ свого панування, а тепер змушує мурлоків зносити докупи пожитки всіх, хто гине в цих печерах."},
    [427] = {n="Лорд Лихоязик", d="Сатир-лорд Лихоязик подався в глибини Мародона, прочувши про скверну, що там запанувала. Спершу Терадрас остерігалася підступного демона, та Лихоязик довів свою цінність, створивши для принцеси цілу низку мерзенних поплічників, як-от Ноксіон і Гострохльост."},
    [428] = {n="Целебрас Проклятий", d="Дізнавшись про трагічну долю свого дядька, шляхетний Целебрас присягнувся звільнити дух Заетара. Та хранитель гаю не був готовий до жахіть, що чигали на нього в тінистих коридорах Мараудона. Темні енергії, які просякали ці місця, швидко здолали Целебраса, наповнивши його серце нестримною люттю."},
    [429] = {n="Зсув", d="Багато років прадавній гірський велетень на ім'я Зсув плекав осяйні кришталеві сади в Мараудоні, але Терадрас зачарувала громадину, коли оселилася там. Цей колись незворушний велетень тепер живе лише для того, щоб служити своїй тиранічній новій володарці."},
    [430] = {n="Гнилохват", d="Подейкують, що Гнилохват мешкає в підземних водах Мараудона вже тисячоліттями. Уславлений дворф-мисливець Гемет Несінґварі колись проголосив, що цю звірину знайти неможливо, і чимало мисливців-аматорів прийняли виклик відшукати легендарне створіння. Жоден із них так і не повернувся."},
    [431] = {n="Принцеса Терадрас", d="Земляна елементаль Терадрас, єдина донька Теразани Кам'яної Матері, мешкає у внутрішньому святилищі Мараудона. Під впливом Прадавніх Богів принцеса перетворила свою домівку на лігво псування і страждань. Дехто вважає, що її лиха сила пов'язана з духом її померлого коханого, Заетара. Якщо так, то звільнення полеглого хранителя гаю може бути єдиною надією очистити Мараудон."},
    [433] = {n="Мордреш Вогняне Око", d="За допомогою некромантської магії Мовець Смерті Блекторн зумів знову розпалити полум'я душі Мордреша Вогняного Ока, повернувши його до нежиття.\n\nЯк колишній шаман, Мордреш накинув свою спотворену волю на стихії. Він спалює і випікає на попіл усіх, хто наважиться загрожувати справі Мовця Смерті."},
    [436] = {n="Доміна", d="Коли леді Саревесс не змогла забезпечити магічний захист, Доміна принесла наг у жертву, щоб наснажити власний темний ритуал. На відміну від своєї попередниці, Доміна, Володарка Темряви, не боїться Аку'мая і власноруч згодовує звірові незліченних невинних, аби здобути ласку Прадавніх Богів."},
    [437] = {n="Сутінковий Лорд Батіель", d="Культ Сутінкового Молота не терпить невдач, тож першим наказом Сутінкового Лорда Батіеля, щойно він перебрав владу над Чорнолиманними Глибинами, було кинути лорда Келріса в голодну пащу Аку'мая. Тепер цей піднесений стихійник кидає всю глибину своєї незбагненної сили на те, щоб підняти звіра Прадавніх Богів і вкрити світ темрявою."},
    [443] = {n="Вогнищеспівець Форрестен", d="Очищення Стратгольма забрало життя незліченних людей, чиєю єдиною провиною було те, що вони опинились у приреченому місті. Мандрівний співець і флейтист на ім'я Форрестен став однією з таких жертв. По смерті він і досі блукає містом, не годен прийняти своєї трагічної долі."},
    [444] = {n="Аку'май", d="Аку'май, прадавнє зло, несе в собі дрібку могутності Прадавніх Богів. Цієї триголової гідри вкрай бояться за її бездумну дикість і невситиму жагу до живої плоті, але культ Сутінкового Молота шанує її як божественний знак того, що Прадавні Боги невдовзі повернуться."},
    [445] = {n="Тіммі Жорстокий", d="Тіммісон зажив лихої слави за свою лютість на полі бою. Дехто припускає, що його садизм виріс із безперервних знущань, яких він зазнавав у дитинстві. Тепер, відроджений як потвора Погибелі, з розтрощеним розумом, він катується тими спогадами, і через них відгукується на ім'я, яке колись ненавидів: Тіммі."},
    [446] = {n="Віллі Гоупбрейкер", d="Балназзар з насолодою скористався руйнівними здібностями гарматного майстра Віллі в нежитті, давши своєму цінному прислужнику ім'я Гоупбрейкер. Жахолорд тішиться з того, що зумів перекрутити Віллі та інших багряних хрестоносців — котрі за життя так зневажали нежить — на своїх несвідомих пішаків."},
    [447] = {n="Вартовий глибин", d="Під проклятими Руїнами Місячної Святині прадавні створіння б'ються за володіння. Старого Серра'кіса вигнав із руїн Вартовий глибин, що шукав нового місця для нересту. Тепер Вартовий пильнує тисячі яєць, доки з них не вилупляться нащадки й не розповзуться водними шляхами Азероту."},
    [448] = {n="Інструктор Ґалфорд", d="Колись Ґалфорд неабияк пишався тим, що опікувався найцінніших документів Хрестового походу. Та коли він лежав при смерті, то з жахом дивився, як його дорогоцінні фоліанти палають довкола. Балназзар скористався цим болісним спогадом і наповнив свого слугу вогненною силою, що згубила Ґалфорда за життя."},
    [449] = {n="Балназзар", d="Балназзар ніколи не зазнав справжньої смерті, проте звідав гірку поразку. Після того як Катаклізм сколихнув світ, він вирізав багряних хрестоносців у Стратхольмі й перетворив їх на нежить, яку вони колись так ненавиділи. Тепер жахолорд снує свої підступні задуми, прагнучи помсти Азероту."},
    [450] = {n="Непрощенна", d="Лілія була клинком праведності серед свого народу. Коли Артас наказав своїм військам очистити місто, її розум розколовся від того, що незліченні безвинні гинули від її руки. Вона кинулася на власний меч, аби втекти від божевілля довкола, і тепер існує як примарна істота, навіки позбавлена прощення за свої жахливі вчинки."},
    [451] = {n="Баронеса Анастарі", d="За життя Анастарі брала все, що бажала, хай якою була ціна. Смерть мало що змінила. Коли її душу вирвали з тіла, Анастарі стала баншу й полишила любов до матеріальних дрібничок заради здобутків куди зловіснішого штибу."},
    [452] = {n="Неруб'енкан", d="Неруб'енкан була грізною воїтелькою під час Війни Павука. Зрештою вона померла від ран і повстала в нежитті покірною прислужницею Погибелі. Тепер нерубійка стереже зикурат у Стратхольмі так само люто, як за життя боронила свій дім."},
    [453] = {n="Малекі Блідий", d="Малекі був серед перших, хто приєднався до Культу проклятих, виявивши надзвичайний хист до приборкання могильного холоду. Гнаний невгамовною жагою влади, маг ревно відточує свою майстерність у темній магії, щоб підготуватися до дня, коли його переродять на ліча."},
    [454] = {n="Магістрат Бартілас", d="Бартілас був серед тих безвинних, кого Артас і його війська очистили під час Винищення Стратхольма. Зрештою Король-Ліч підняв колишнього магістрата з могили й наказав велетенській нежиті-потворі стерегти його зруйнований дім."},
    [455] = {n="Рамштайн Пожирач", d="Рамштайн — одна з найсумнозвісніших мерзот Погибелі, жахіття, зшите з безлічі трупів і живлене безперервним голодом. Ця почвара скоїла невимовні звірства над незліченними безвинними душами, коли війська Погибелі заполонили Стратхольм."},
    [456] = {n="Лорд Авріус Рівендер", d="Падіння Авріуса було стрімким. Не зумівши покарати свого зіпсутого батька, барона Рівендера, колишній паладин не зазнав спокою і в смерті. Його трагічно перекували на знаряддя Погибелі — того самого зла, яке він колись присягнувся подолати."},
    [457] = {n="Аватар Гаккара", d="Гаккар уславився тим, що вимагав жертв від своїх послідовників. Багато тисячоліть тому він звелів атал'ай породити його аватара, живлячи його кров'ю, ритуально пролитою з живих жертв. Нині жерці атал'ай прагнуть піднести аватара Гаккара за допомогою зміненої версії цього ритуалу — тієї, що передбачає принесення в жертву зелених драконів. Якщо атал'ай досягнуть свого, повернення аватара Гаккара може віщувати загибель Азероту."},
    [458] = {n="Джаммал'ан Пророк", d="Джаммал'ан — нинішній очільник атал'ай, секти жерців-фанатиків, які несамовито шанують Гаккара. У глибокій медитації Джаммал'ан отримав настанови, як воскресити Гаккара, скориставшись кров'ю його драконячих ворогів — зеленого драконячої зграї. Джаммал'ан і його охоронець-нежить, Оґом Жалюгідний, готові стати проти всякого, хто захоче завадити поверненню Гаккара, хоча дії пророка можуть випустити на Азерот ще страшнішу силу — Смарагдовий Кошмар."},
    [459] = {n="Вартові Сну", d="Четверо багатообіцяльних молодих драконів супроводжували Еранікуса до Храму Атал'Гаккар, прагнучи довести свою вартість, служачи великому й могутньому вирму. Одного за одним їх захопив і споганив Смарагдовий Кошмар, і тепер вони блукають залами Затонулого храму, накидаючись на всякого, хто вдирається в їхній сон наяву."},
    [463] = {n="Тінь Еранікуса", d="Еранікуса, колишнього супутника Ісери Сновиди, послали стерегти руїни Атал'Гаккара й не дати Гаккару постати. Щойно опинившись у храмі, він і його почет були споганені темними силами цього місця, і він став тінню, розірваною між світами Смарагдового Сну та фізичної площини. Попри свою зіпсутість, Еранікус і досі може закликати свою силу зеленого дракона, щоб плювати в'їдливою кислотою у ворогів або занурювати їх у глибокий сон."},
    [464] = {n="Хоґґер", d="Засуджений №SC55: Гоґґер\n\nЗвинувачення: Надто багато, щоб тут перелічити\n\nУв'язнення ватажка Річколапів обійшлося дорого — наглядач частково втратив зір. Боячись, що Гоґґер може втекти, Телвотер дозволив скарати ґнола з особливою суворістю."},
    [465] = {n="Лорд Перегрів", d="Засуджений №NA: Лорд Перегрів\n\nЗвинувачення: Убивство (кілька випадків)\n\nПриродні катастрофи, спричинені Катаклізмом, прорвали елементалів до тюремного комплексу, і ті ще на порозі винищили половину в'язнів. Усунення цих розлючених загроз украй необхідне, щоб відновити лад у в'язниці."},
    [466] = {n="Рандольф Молох", d="Засуджений №AC317: Рандольф Молох\n\nЗвинувачення: Розтрата, шахрайство, крадіжка та вбивство\n\nМолоха визначено як призвідника тюремного бунту. Утім, з огляду на його зв'язки з Палатою вельмож, застосування смертельної сили для приборкання цього засудженого не дозволяється."},
    [467] = {n="Ревелош", d="Деякі світила знаної Ліги дослідників Айронфорджа висунули теорію про прадавній зв'язок між їхнім народом і троґґами, вказуючи на те, що троґґи збирають артефакти титанів так само, як самі дворфи шанують подібні дивовижні витвори. Якщо це правда, троґґа на ім'я Ревелош можна вважати троґґським відповідником археолога, хоча будь-який досвідчений в історії шукач пригод, зустрівши його, радше назвав би його злодієм."},
    [468] = {n="Загублені Дворфи", d="У пошуках слави, а ще важливіше — багатства, троє братів, Ерік, Олаф і Бейлоґ, узяли підряд від Ліги дослідників: заглибитися в зали Улдамана й розчистити шлях для гурту дослідників. Однак для цих трьох дворфів «розчистити шлях» обернулося, на жаль, на «безнадійно заблукати в прадавньому лабіринті». Горді дворфи до останку, вони б'ються, аби не дати таємницям Улдамана й Ліги дослідників потрапити до рук Орди."},
    [469] = {n="Айроная", d="Титани не зводили комплекс Ульдаману власноруч, а використали різноманітних слуг, щоб створити його велетенські зали. Пантеон доручив вартовій Айранаї наглядати за будівництвом і доглядом Ульдаману, та з плином часу колись величне склепіння занепало. У залі мап Айраная провела тисячоліття у своєрідному застиглому сні, аналізуючи первісний задум, накреслений Каз'ґоротом, і шукаючи спосіб повернути комплексу його початкову справність."},
    [470] = {n="Стародавній Кам'яний Вартовий", d="Один із багатьох ґолемів, що обслуговували й підтримували велике сховище титанів, Стародавній Кам'яний Вартовий належав до невеликої групи, яка слугувала посередником між вартовими, залишеними керувати спорудою, та їхніми численними слугами. Після осквернення Обсидіанового Стража Стародавній Кам'яний Вартовий лишився останнім зі свого роду й виконує свій обов'язок, оберігаючи таємниці титанів якнайкраще, доки не настане його неминуче вимкнення."},
    [471] = {n="Ґалґанн Вогнемолот", d="Дізнавшись про відкриття Ульдаману дворфами Бронзборід, клан Темного Заліза вдерся до сховища, щоб не дати своїм одвічним ворогам дістатися могутніх артефактів усередині. Ґалґанна Вогнемолота, сенатора з міста Тінькузня, відрядили наглядати за подальшими розкопками Ульдаману, щоб імператор міг скерувати руйнівну силу артефактів проти ворогів Темного Заліза."},
    [472] = {n="Ґрімлок", d="У спільноті троґґів найбільший, найдужчий і найлютіший троґґ часто стає вождем через демонстрацію сили. Ґрімлок — справжній геній на їхньому тлі, адже втримує владу над троґґами Кам'яного Склепу залякуванням і чимось на кшталт грубої психологічної війни. Виховавши смертоносного василіска, Ґрімлок погрозою скам'яніння від своєї тварюки тримає в покорі всіх можливих загарбників влади."},
    [473] = {n="Архедас", d="Глибоко в надрах Ульдаману є зала з одним із найбільших скарбів титанів, створеним самим Норґанноном. Та досі жодному дослідникові не вдалося дістатися до реліквії, бо будь-яка спроба пробуджує великого вартового Архедаса — велетенського охоронця, який легко знищує шукачів скарбів своїми могутніми ударами та цілим військом слуг. Викуваний із найдавнішого, найміцнішого каменю з глибин Ульдаману, Архедас — ворог настільки ж грізний, як і прадавній."},
    [474] = {n="Леді Анакондра", d="Скарлетліф першою зголосилася до місії, яку Наралекс сам собі визначив, у Степи. Коли жахіття її наставника розтрощило їй розум, юна послушниця відкинула своє ім'я й тепер уособлює лиховісне зміїне майбутнє для Азероту."},
    [475] = {n="Лорд Кобран", d="Хист Джарлаксли до опанування звіриних форм здобув йому шану серед друїдів Кола Кенарія. Проте осквернення Скорботних Печер спотворило його неповторні здібності. Тепер Джарлаксла довів до досконалості смертоносну зміїну подобу й перейменував себе на Кобрана, щоб відобразити свою жорстоку новопосталу силу."},
    [476] = {n="Лорд Пайтас", d="Друг дитинства Наралекса, воїн Арін швидко опанував друїдизм. Та попри вишкіл, послушник був беззахисним перед оскверненням, що позбавило його глузду. Арін узяв собі ім'я Пайтас і поєднує свою вражаючу майстерність ближнього бою з друїдським арсеналом, щоб нищити чужинців."},
    [477] = {n="Креш", d="Прадавній мешканець Скорботних Печер, ця велетенська черепаха блукає підземними печерами, і її стійкий розум не зачепили невпинні жахіття Наралекса. Та не давайте йому ввести себе в оману своєю добродушністю: Креш дав відсіч багатьом шукачам пригод, які прагнули викрасти його величезний панцир."},
    [478] = {n="Скам", d="Уперше Скам подався до Скорботних Печер, щоб сховатися від ворожого довкілля Степів. Як і багато інших мешканців печер, він швидко піддався оскверненню. Тепер його жилами пульсує темна енергія, що перетворила його на могутню й безжальну тварюку, для якої вже немає спасіння."},
    [479] = {n="Лорд Серпентіс", d="Ватажок Друїдів Ікла колись був найкращим учнем Наралекса. Його трагічне падіння почалося з прагнення стати шан'до, тобто «шанованим учителем», як Наралекс. Коли в нього вкоренилося безумство, Серпентіс згуртував своїх побратимів і заснував Друїдів Ікла."},
    [480] = {n="Вердан Вічноживий", d="Про цю істоту мало що відомо з часів до прибуття Наралекса до Лементливих Печер. Вважають, що Вердан Вічноживий був первісним вартовим печер, проте він не зміг утекти від скверни, яка охопила його дім. Вердан уклав союз із божевільними друїдами й невпинно стереже свої володіння від тих, хто наважиться в них вдертися."},
    [481] = {n="Мутанус Пожирач", d="З найтемніших закутків спотвореного розуму Наралекса скверна, що отруює Смарагдовий Сон, постала в подобі найлютішого ворога друїда: мурлоків. Аберація на ім'я Мутанус прийшла у світ живих, щоб пожерти кожного, хто прагне визволити Наралекса з лабет Жахіття."},
    [482] = {n="Гідромантка Велрата", d="На відміну від більшості тролів Піщаної Люті, гідромантка Велрата мандрувала світом, збираючи знання й артефакти, щоб опанувати священні води Зул'Фаррака. Хоча своїми вчинками гідромантка нажила собі чимало ворогів на чужині, неймовірну силу, яка тепер у її розпорядженні, вона вважає виправданням усіх своїх минулих лиходійств."},
    [483] = {n="Ґаз'рілла", d="Легенда каже, що Ґаз'рілла була улюбленицею Прадавніх Богів, а то й сама напівбогинею. Хай там як, троли Піщаної Люті вшановують цю жахливу гідру вже тисячі років. Завжди остерігаючись крижаної люті звіра, троли будять Ґаз'ріллу лише тоді, коли мають удосталь жертв, щоб втамувати ненаситний апетит цього створіння."},
    [484] = {n="Анту'сул", d="Анту'сул хоче, щоб його василіски сул'літуз були сильними й нещадними. Цих лускатих звірів він має за рідну родину й, як відомо, убиває кожного — навіть побратимів-тролів, — хто завдасть шкоди його любим дітям. Замість гідного поховання Анту'сул дозволяє василіскам бенкетувати на тих, хто насмілиться перейти йому дорогу."},
    [485] = {n="Тека Мученик", d="Давним-давно мученик Тека загинув у жорстокій війні між кіраджі й тролами. Зул'Фаррак досі стоїть завдяки його відважній жертві. Навіть у смерті він стереже своє улюблене місто, і кажуть, що десятки воїнів-комах, які його вбили, були прокляті жити безтямними скарабеями, що снують поряд із мучеником."},
    [486] = {n="Знахар Зум'ра", d="Могутній лоа Бвонсамді оберігає духів тролів Темного Списа, але багатьом полеглим членам племені Піщаної Люті після смерті такого захисту не дано. Ці змучені духи коряться Зум'ра, жорстокому знахареві, який своєю темною магією змушує мертвих міста служити безкінечно."},
    [487] = {n="Некрум і Сезз'зіз", d="Некрум Кишкожуй загадковим чином прожив набагато довше за відведений йому природою вік, але його тіло, що розкладається, лишається досить сильним, щоб допомагати Сезз'зізу. Удвох ці троли зібрали жертви для міфічного звіра Ґаз'рілли, яка дрімає в серці міста. Багато тролів-послідовників нетерпляче чекають пробудження жахливого створіння й зроблять усе, щоб довести ритуал до кінця."},
    [489] = {n="Вождь Укорз Піскоскальп", d="Вождь Укорз Піскоскальп одержимий бажанням повернути своєму племені колишню славу. Він виріс на оповідях про часи, коли троли владарювали над своїми прадавніми землями без втручання ґоблінів, ґномів, піратів, оґрів та інших чужинців-зайд. Піскоскальп закликав свого вірного товариша Руузлу допомогти йому розпочати новий розділ в історії Піщаної Люті в єдиний спосіб, який знає їхнє плем'я: швидким і сліпучим насильством."},
    [523] = {n="Ширрак Вартовий Мертвих", d="Ширрака створив екзарх Маладаар, щоб стерегти душі полеглих дренеїв, які блукають Аученайськими криптами. Цей мертвий витвір — некротична маса з очей, зубів і щупалець — жадібно й нестримно поглинає арканну енергію та не пропускає повз себе жодну живу істоту."},
    [524] = {n="Екзарх Маладаар", d="Маладаар — єдиний живий залишок колишньої величі, що ступала залами Аученаю. Утрата всіх і всього, що він колись любив, звела його з розуму. Божевільна відданість збереженню їхньої пам'яті привела його до опанування темних мистецтв."},
    [527] = {n="Хранитель вартових Ґарґолмар", d="Зневажений мешканцями Позамежжя, Ґарґолмар відомий тим, що пожирає серця всіх, кого впіймає поблизу Цитаделі Пекельного Вогню, — байдуже, намагалися ті проникнути всередину чи ні. Сам Карґат Лезорукий доручив йому оборону валів, і хранитель вартових Ґарґолмар несе свою службу непохитно."},
    [528] = {n="Омор Безшрамний", d="Омор Безшрамний був учнем Гаккара Псаря і прийняв під опіку вцілілих сквернопсів легендарного воїна після поразки свого наставника у Війні Прадавніх. Відтоді Омор жодного разу не зазнав поразки в поєдинку. Цей шанований демон — посланець Іллідана до орків Скверни Цитаделі Пекельного Вогню."},
    [529] = {n="Вазруден Герольд", d="Вазруден стереже життєво важливий потік припасів, послань і військ, що рухається між Цитаделлю Пекельного Вогню та Чорним Храмом. Верхи на своєму чудовому нетердраконі Назані Вазруден являє собою нестримну повітряну силу вогню, пазурів і пронизливого жаху."},
    [530] = {n="Селін Вогнесердий", d="Колись шанований капітан особистої варти Кель'таса Сонстрайдера, Селін Вогнесердий зберіг непохитну запеклу відданість своєму володареві, але втратив розум. Селіна звабили демонічні енергії кристалів, що оточують його палату, і він не може спинитися, упиваючись їхньою мерзенною силою. Він уб'є кожного, хто посміє наблизитися до Тераси магістрів, і вип'є магію, життя та кров з їхніх мертвих тіл."},
    [531] = {n="Вексаллус", d="Арканний елементаль немислимої сили, Вексаллус був прикликаний на Терасу магістрів трьома ельфами крові, які загинули від потуги його прибуття. Магічна енергія в довколишніх кристалах відлунює всередині Вексаллуса, і вся його сутність перебуває в постійному стані вибухового хаотичного коловороту."},
    [532] = {n="Жриця Делрісса", d="Делрісса — жриця-шиварра, що діє на службі владики демонів Кіл'джедена. Саме Делрісса оживила Кель'таса Сонстрайдера після того, як він зазнав тяжких ран під час нападу на Фортецю Бур, і відтоді не покидала володаря ельфів крові. Жриця має войовниче коло вірних послушників, які служать їй і захищатимуть її будь-якою ціною."},
    [533] = {n="Кель'тас Сонстрайдер", d="Колись справжній захисник народу ельфів крові й оборонець прадавньої спадщини своєї раси, Кель'тас Сонстрайдер під час перебування в Позамежжі піддався темному впливу демона Кіл'джедена. За велінням свого нового володаря заблудлий принц повернувся до Азероту і захопив Сонячний Колодязь, сподіваючись використати це джерело, щоб відчинити демонові двері до цього нового квітучого світу. Кель'тас — блискучий тактик, могутній воїн, і в його жилах палає безмежна магія Скверни."},
    [534] = {n="Пандемоніус", d="Цей сумнозвісний владика Порожнечі відомий також як Герцог Хаосу, Пожирач Народів і Світовбивця. Пандемоніус був одним із полководців на службі Дименсіуса, коли загинув К'ареш — рідний світ ефіріалів. Згодом його скував принц-нексус Шаффар і змусив і далі вгамовувати свій нескінченний голод на службі ефіріалам."},
    [535] = {n="Таварок", d="За наказом Кель'таса Сонстрайдера Паталеон Калькулятор прикликав могутнього колоса, щоб збирати арканні енергії, які струмують з-під Мана-Гробниць. Несподівано Таварок змінився під впливом цих незвичайних випромінювань і скинув з себе червонувату скверну Паталеонового впливу. Білий колос здобув власну волю і тепер жадібно пожирає всіх, хто стане йому на шляху."},
    [536] = {n="Йор", d="Йор — пес Порожнечі безмежної люті й сили — був «подарунком» від Іллідана Стормрейджа, щоб супроводжувати нексус-принца Шаффара. Радники застерігали принца, що демонічний дарунок Іллідана найпевніше є підступом, який обернеться проти Шаффара, щойно той досягне своїх цілей. Принц згодував тих радників Йорові… та відтоді про всяк випадок тримає пса замкненим у камері застою."},
    [537] = {n="Нексус-принц Шаффар", d="Переконаний, що в глибинах Мана-Гробниць криються незліченні багатства, нексус-принц Шаффар витратив незмірні суми зі свого чималого статку, щоб перекинути армію в затінені зали цих руїн, що осипаються, і не пустити сюди суперників-ефіріалів. Зажерливість принца не знає меж, і він заприсягся розкрити таємниці Мана-Гробниць або загинути, намагаючись це зробити."},
    [538] = {n="Лейтенант Дрейк", d="Лейтенант Дрейк був честолюбним воякою, що під час Другої війни прагнув слави командування. Його честолюбство дорівнювало хіба що ненависті до зеленошкірих орків, які вбили стількох його товаришів, — ненависті, що втілилася в жорстокому поводженні з полоненими в таборах для в'язнів фортеці Дернголд."},
    [539] = {n="Капітан Скарлок", d="Палко відданий Еделасу Блекмору, капітан Скарлок підіймався в лавах війська Дернголду пліч-о-пліч зі своїм другом Аліденом Перенольдом. Коли Алиден вирішив очолити операції в горах Альтераку, Скарлок лишився при своєму володарі й наставнику. Він став найдовіренішим побратимом і радником Еделаса, заслуживши титул «Спис Блекмора»."},
    [540] = {n="Ловець Епох", d="Той, хто має загадкове ім'я Ловець Епох, — це вбивця з нескінченного драконячого рою, посланий змінити плин історії, убивши Тралла, перш ніж той зуміє втекти з Дернголду. Цей тіньовий дракон убив безліч істот заради своєї справи, та це вбивство буде найважливішим. Він збере всю свою силу, могутність, витонченість і хитрість, щоб покласти край цій лінії часу."},
    [541] = {n="Темноткач Сит", d="Король-кіготь Ікісс доручив Темноткачу Ситу боронити Зали Сетекк, доки відступники-араккоа шукають свого загадкового бога. Майстер тіньової магії, цей зморщений штукар навчився підкоряти своїй волі самі стихії."},
    [542] = {n="Анзу", d="Загадкове крилате божество, якому поклоняються найдикіші з араккоа, Анзу — істота, чиї походження й сили не схожі на жодного іншого члена занепалого пантеону Позамежжя. Наару мовчать про цю лиху істоту, бо шляхи Анзу приховані навіть від них."},
    [543] = {n="Король-кіготь Ікісс", d="Король-кіготь Ікісс був харизматичним духовним провідником зухвалого гурту араккоа, які покинули свій дім у лісі Терокар у пошуках «обіцяного бога». Уві сні йому являлися видіння цього бога, і він знав, що одкровення чекає на нього в напівзруйнованих залах Аучиндона. Видіння позбавили Ікісса глузду, і тепер він проголошує себе відродженим Терокком, божественним героєм з міфів араккоа."},
    [544] = {n="Посол Геллмо", d="Могутній демонічний слуга й послушник болю, Посол Пащека Пекла відданий мистецтву смерті. Він не любить нічого більше, ніж смак життєвої крові смертного, приправленої жахом і відчаєм. Пащеку Пекла зв'язали орки Скверни Тіньового Лабіринту й годують нескінченним потоком полонених, щоб демон ревніше служив чорній волі своїх господарів."},
    [545] = {n="Чорносерд Підбурювач", d="Коли орківська Орда вперше вторглася в Азерот крізь Темний Портал, двоє членів Ради Тіні натомість звернули свою увагу на стародавнє місце поховань дренеїв в Аучіндоуні. Неспокійні духи цієї місцевості виявилися чудовим матеріалом для чорнокнижника Чорносерда, щоб удосконалити його здібності контролю розуму."},
    [546] = {n="Великий Магістр Ворпіл", d="У перші дні Орди Великий Магістр Ворпіл переконав орка-чорнокнижника Ґул'дана дозволити йому дослідити таємниці Аучіндоуна, потай прагнучи опанувати енергію жахливо могутніх космічних есенцій, що просякали цю місцевість."},
    [547] = {n="Мурмур", d="\"На початку\"... \"Так далеко\"... такі слова не здатні навіть наблизитися до опису походження цього елементаля. Його існування провіщає чисту руйнацію. Світи розколюються, і уламки розлітаються за його примхою. Лише справді божевільний задумав би його викликати. Можливо, ще є час вигнати Мармура, перш ніж він повністю увійде в Запределля."},
    [548] = {n="Зерекет Звільнений", d="Більшість створінь із Викривленої Порожнечі потребують постійних вказівок від своїх володарів, та небагатьом примарам Порожнечі такі накази не потрібні. Зерекет стоїть біля входу до Аркатразу, готовий убити кожного, хто наважиться кинути йому виклик."},
    [549] = {n="Даллія Провісниця Загибелі", d="Перш ніж її ув'язнили наару, Даллія була однією з найлютіших і найагресивніших воїтельок Палаючого Легіону. Тривалий час, проведений у спільній камері з Прозорцем Гніву Соккотратесом, теж не покращив її вдачі."},
    [550] = {n="Прозорець Гніву Соккотратес", d="Тисячоліття тому Соккотратес обіймав почесну посаду серед вартових гніву, стоячи пліч-о-пліч із найвищими командувачами Палаючого Легіону. Ув'язнення не пасувало його неабиякому самолюбству. Як і його сусідка по камері."},
    [551] = {n="Передвісник Скайрісс", d="Наару вірили, що переконливий голос Передвісника Скайрісса змовк, коли вони стримали його й змусили поринути в довгий сон без сновидінь. Бідолашний наглядач Аркатразу дізнався, що наару помилялися. Скайріссу вистачило енергії, щоб тихим, ледь чутним голосом промовляти до Наглядача Мелліхара. Решту довершив час."},
    [552] = {n="Володар Часу Дежа", d="Нескінченний Зграй Драконів спокушав багатьох драконідів обіцянками влади, та більшість знайшла лише поневолення й відчай. Один із небагатьох винятків — Володар Часу Дежа, який здобув вплив усередині зграю завдяки своїй неприборканій силі та хитрості."},
    [553] = {n="Темпорус", d="Хоч і відносно молодий, Темпорус відіграв вирішальну роль у виявленні багатьох головних цілей Нескінченного Зграю Драконів. У нагороду йому доручили знищувати кожного, хто спробує завадити планам зграю."},
    [554] = {n="Еонус", d="Могутній і дикий, Еонус отримав від Володаря Нескінченного Зграю Драконів завдання особисто наглядати за зривом ключових моментів справжнього плину часу."},
    [555] = {n="Творець", d="Усі істоти, що користуються силою магії Скверни, з власної волі чи ні, поступово набувають демонічної подоби. Творець пришвидшує їхнє осквернення і ставить жорстокі досліди над кожним, хто намагається опиратися."},
    [556] = {n="Броґґок", d="Деякі істоти час від часу переосмислюють свою відданість новим, оскверненим господарям. Броґґок дбає про те, щоб будь-які бунтівні думки серед орків Скверни були викоренені назавжди."},
    [557] = {n="Келі'дан Руйнівник", d="Коли Іллідан скинув володаря ям Маґтерідона і захопив владу над Запределлям, він наказав ув'язнити демонічного ватажка під цитаделлю Пекельного Вогню. Лише найстійкіший серед воїнів Іллідана міг сподіватися втримати його в полоні; безжальний орк Келі'дан був єдиним можливим вибором."},
    [558] = {n="Командир Сараніс", d="Коли занепалий ватажок ельфів крові Кель'тас захопив владу над Фортецею Бур, він одразу ж наказав командиру Сараніс готувати оборону проти будь-кого, кого наару можуть надіслати, щоб відбити фортецю."},
    [559] = {n="Верховний ботанік Фрейвінн", d="Лише за кілька хвилин після того, як він увійшов до Ботаніки, Фрейвінн узявся за необачні досліди, щоб вивільнити силу, приховану в рослинному житті Запределля."},
    [560] = {n="Торнґрін Доглядач", d="Досліди потребують ресурсів. Торнґрін Доглядач дбає про те, щоб ботаніки Кель'таса мали силу й есенцію, потрібні для розкриття таємниць наару, навіть якщо задля цього доводиться жертвувати незліченними живими істотами."},
    [561] = {n="Лай", d="Наару зібрали зразки незвичайної фауни з усього Запределля. Коли Ботаніку захопили, їхні запобіжники було знищено, і деякі з найнебезпечніших створінь дістали волю."},
    [562] = {n="Варп-Скалка", d="Нічні ельфи Дарнасуса попросили допомоги у визволенні Прадавнього арканної магії, що опинився в пастці у Фортеці Бур. Наляканий нещодавнім нападом військ Кель'таса Сонстрайдера, Варп-Скалка не здатен відрізнити друга від ворога і ладен напасти на кожного, хто його потурбує."},
    [563] = {n="Механолорд Капацитус", d="Потрібні неабияка вправність і точність, щоб видобути силу з манакомірок наару. Ці таланти легко можна обернути проти будь-яких зайд."},
    [564] = {n="Нетеромантка Сепетрея", d="Завдяки вмінню швидко прикликати створінь, щоб нищити ворогів, Сепетрею обрали ученицею Патальона Лічильника, ельфа крові, який керував Механаром."},
    [565] = {n="Паталеон Калькулятор", d="Після осквернення Сонячного Колодязя пихатий арканіст Паталеон побачив нагоду здобути славу, допомігши Кель'Тасові знайти ліки від залежності його народу від магії. Ця одержима мета привела його до того, що він приєднався до принца ельфів крові в Аутленді й наглядав за його згубними експериментами. Останнім часом Паталеон узявся використовувати потойбічні технології Фортеці Бур задля слави та могутності."},
    [566] = {n="Великий Чорнокнижник Нетекурс", d="Нетекурс, колись шаман клану Тіньового Місяця, зрікся своєї шани до стихій, щоб опанувати мистецтво володіння магією Скверни. Демонічні енергії, що йому підвладні, лишили з нього порожню оболонку, яка знаходить утіху лише в катуванні молодих орків Скверни, випробовуючи межі їхньої душевної та тілесної сили."},
    [568] = {n="Войовник О'мроґґ", d="Безжальний і хитрий оґр О'мроґґ вважається одним із найсмертоносніших бійців Орди Скверни. Та в цього грізного здорованя є проблема. Дві голови оґра завжди насилу доходили згоди навіть у найпростіших справах. Два роки тому О'мроґґ розпочав дванадцятиступеневий план, щоб налагодити співпрацю між своїми ворогуючими особистостями. Його голови досі не вирішили, з якого кроку почати."},
    [569] = {n="Вождь Карґат Блейдфіст", d="Вождь клану Розбитої Длані та воєначальник Орди Скверни, Карґат Блейдфіст — один із найвидатніших орочих героїв нещодавнього минулого. З роками він відтяв обидві свої руки й замінив їх бойовою зброєю — кривавий ритуал, властивий лише його кланові. Утіха, яку він дістає, завдаючи болю іншим і собі, легендарна серед орків. Як тиранічний правитель Орди Скверни, він спрямував свою безжальність і лютість на те, щоб викувати нездоланну армію за залізними мурами Цитаделі Пекельного Вогню."},
    [570] = {n="Менну Зрадник", d="Менну — один із Понівечених, дренеїв, спотворених і знівечених демонічними енергіями, що їх вивільнили орки. Коли наги вдерлися до Зангарського багновища, багато цих нещасних істот у відчаї намагалися втекти з краю. Менну ж обрав інший шлях до свободи. В обмін на власне життя він зрадив своїх побратимів-Понівечених зміїним загарбникам і погодився панувати над своїми родичами як наглядач рабів."},
    [571] = {n="Рокмар Тріскотун", d="Після знищення Дренору Рокмар утік у глибини Зангарського багновища. Енергії, що роздерли світ на частини, огорнули велетня, посиливши його міць і розмір ціною невпинної муки. Наги були вражені лютістю Рокмара, коли вперше прибули до краю. Замість того щоб убити звіра, вони поневолили його й використовували, аби підкорити більшість місцевого життя Зангарського багновища."},
    [572] = {n="Кваґмірран", d="Кваґмірран колись був володарем велетенських грибних гігантів Зангарського багновища. Його захопили наги, коли він блукав зміїними печерами краю, і піддали нестерпним тортурам. Тепер ця зламана істота безмовно служить своїм повелителям, змушуючи замовкнути всіх, хто противиться волі леді Вашж."},
    [573] = {n="Гідромантка Теспія", d="На вершині розквіту імперії нічних ельфів високорідна Теспія тішилася мистецтвом і музикою. Її любов до цього зникла під час Великого Розколу, коли її та багатьох її родичів затягнуло в глибини Азероту й перетворило на сповнених ненависті наг. У тисячоліття, що настали потому, Теспія лишалася близькою повірницею своєї подруги дитинства, леді Вашж. Без вагань вона вирушила зі своєю товаришкою до Зангарського багновища й заприсяглася наглядати за справою наг — осушити край від його водних запасів."},
    [574] = {n="Мекґенієр Парогон", d="Опромінення Ґномреґану перетворило багатьох уцілілих містян на прокажених ґномів. Серед цих жертв був і блискучий мекґенієр Парогон. Хоч він утік із Ґномреґану й зберіг свій розум, та хай яку етику й співчуття він колись мав — усе зникло. Він блукав Азеротом, продаючи свої знання різним безпринципним угрупованням, як-от Кривавим Вітрилам. Нещодавно наги найняли Парогона, щоб той керував складними механізмами в Паросховищі Зангарського багновища."},
    [575] = {n="Воєначальник Калітреш", d="Глибоко в Паросховищі наги взялися експериментувати з таємничою речовиною, аби зміцнити своїх воїнів і позбавити їх страху. Калітреш був одним із перших слуг леді Вашж, хто зголосився стати піддослідним для цього темного еліксиру. У нагороду йому доручили охороняти просторе Паросховище й стежити, щоб арканні механізми краю працювали без перебоїв."},
    [576] = {n="Гунґарфен", d="На відміну від свого союзника Кваґмірана, велетенський грибний гігант Гунґарфен досі уник поневолення нагами. Та попри це він лютий до всіх чужинців, що ступають у найглибші печери Зангарських боліт. Не помічаючи підступів наг в інших куточках краю, Гунґарфен здебільшого порається коло Глибинної спори - прадавньої рослини, яку, кажуть, він цінує понад усе."},
    [577] = {n="Ґаз'ан", d="Історики довго сперечалися, чи мають велетенські гідри Азероту й Позамежжя спільного предка. Та безсумнівне одне: ці безжальні створіння здавна живуть в обох світах. Ґаз'ан - одна з найстрашніших і найвідоміших гідр Позамежжя. Підкорена леді Вашж, ця ненажерлива потвора вдерлася в низини Зангарських боліт, щоб тероризувати мешканців краю."},
    [578] = {n="Болотний володар Мусел'ек", d="Бути одним зі Зламаних означає бути вигнанцем. Ця правда тяжко гнітить болотного володаря Мусел'ека. Хоч він і належить до Зламаних Мутнокровів, та воліє блукати печерами під Зангарськими болотами на самоті. Під час однієї з нещодавніх мандрівок він застосував свою владу над звірами, щоб поневолити Вітрозванця Кіготь - друїда, який досліджував ці місця в подобі лютого ведмедя. Мусел'ек змусив Кіготь стати вірним супутником, що не судитиме його за спотворену істоту, на яку він перетворився."},
    [579] = {n="Чорний скрадач", d="Болотні блукачі Позамежжя - височезні створіння, що никають дикими нетрями й пожирають усіх дрібніших істот, які трапляються їм на шляху. Спорлінги Зангарських боліт оповідають про одного з цих хижаків - надзвичайно безжальну потвору, відому як Чорний скрадач. Кажуть, ця прародителька всіх болотних блукачів виходить зі свого лігва в глибинах Нижньої твані лише для того, щоб утамувати голод смачними спорлінгами."},
    [580] = {n="Старійшина Надокс", d="Колись Надокс був шанованим вождем нерубіанців, який покоління за поколінням навчав свій народ прадавніх звичаїв. Коли Війна Павука спустошила Азжол-Неруб, його здолали легіони нежиті. Король-Ліч оживив його труп і висотав із Надокса все мудре й шляхетне, змусивши вбивати власних учнів, друзів і всіх інших нерубіанців, що чинили опір могутності Погибелі."},
    [581] = {n="Принц Талдарам", d="Після невдалого нападу Кель'таса на Короля-Ліча декого з його найзнатніших послідовників-ельфів крові було вбито й піднято з мертвих як темнопалих. Принц Талдарам - одна з цих підступних і кровожерливих вампірських істот. Завжди прагнучи догодити Королю-Лічу, він зійшов у понівечені війною глибини Ан'кагету в пошуках утрачених нерубських реліквій, здатних зміцнити вбивчі лави Погибелі."},
    [582] = {n="Джедоґа Шукачка Тіней", d="Джедоґа марить апокаліпсисом. Подейкують, що вона одна з найфанатичніших послідовниць культу Сутінкового Молота. Під проводом безжального оґра-мага Чо'ґалла вона навчилася спотворювати свою шаманську силу, щоб служити Прадавнім богам. Не так давно Джедоґа подалася в нутрощі Ан'кагету, щоб приготуватися до славетного дня, коли Йоґґ-Сарон постане й огорне землі Азероту темрявою."},
    [583] = {n="Аманітар", d="Споконвіку гриби та інші безпечні форми життя буяли у вологих, позбавлених сонця печерах Ан'кагету. Лише нещодавно Йоґґ-Сарон поширив свою гнітючу волю на цю відлюдну екосистему. Прадавній бог скористався своєю величезною руйнівною силою, щоб перекрутити одного з місцевих звірів Ан'кагету на жахливу потвору, відому як Аманітар, - бездумний жах, що аж пашить нищівною енергією свого володаря."},
    [584] = {n="Герольд Волазж", d="Під час вторгнення Погибелі в Азжол-Неруб багато мешканців королівства рили тунелі під землю, тікаючи від поплічників Короля-Ліча. Та дехто закопався надто глибоко й оголив паростки Йоґґ-Сарона. Розбуджена цим неспокоєм, сутність послала одного зі своїх найдавніших воїнів - Герольда Волазжа, - щоб винищити обложених нерубіанців і знищити всіх, хто був достатньо нерозумний, аби загрожувати Прадавньому богу."},
    [585] = {n="Крік'тір Вартовий Брами", d="Брами Азжол-Неруба століттями стояли непохитно - аж до приходу Короля-Ліча. На глум із нездатності Крік'тіра захистити свій дім нерубіанецьа підняли з мертвих і змусили вартувати ті самі брами, які він не зумів устерегти за життя."},
    [586] = {n="Гадронокс", d="Під час падіння Азжол-Неруба нерубіанські візири випустили на волю одну-єдину павучиху, якій судилося колись вирости й кинути виклик невблаганним силам Короля-Ліча. Гадронокс пройнялася жагою помститися за загиблих і відвоювати свій дім у всіх, хто посміє йому загрожувати."},
    [587] = {n="Ануб'арак", d="Долі Азжол-Неруба й Ануб'арака вже давно нерозривно переплетені. За життя він був королем імперії. По смерті — її завойовником. Король-зрадник, якому Король-Ліч доручив знову захищати свою колишню імперію, пильно стоїть на варті проти всіх, хто загрожує його королівству."},
    [588] = {n="Тролґор", d="Драккарі були серед найлютіших тролських племен, а Тролґор був взірцем дикунства свого племені. Ця громіздка потвора виявила, що його хвалена жорстокість блякне поряд із жорстокістю Короля-Ліча, і тепер він слугує моторошним застереженням усім, хто наважиться кинути виклик владі Артаса."},
    [589] = {n="Новос Закликач", d="Новос завжди був пристосуванцем і шукав способу піднестися над своїми приземленими товаришами. Цей культист вирізав собі серце з грудей і подарував іще тремтливий орган своєму володареві за мить до власної смерті. Його рішучість вразила володаря, який за це перетворив його на ліча."},
    [590] = {n="Король Дред", d="Серед драккарі Король Дред — справжня легенда. Розповідають про загін тролів-мисливців, який вистежив могутню звірину, що зросла в краю, просякнутому чумою Погибелі. Тролі приборкали диявозавра, вірячи, що лише він має протиотруту від лютої хвороби, яка винищувала їхній народ."},
    [591] = {n="Пророк Тарон'я", d="Навіть викрадена сила лоа не змогла стримати руку смерті, коли Погибель рушила на Фортецю Драк'Тарон. Тепер, коли легіони тролів гинуть під ножем перед Королем-Лічем, Тарон'я провіщає своєму новому володареві лише тріумф."},
    [592] = {n="Слад'ран", d="Слад'ранові не приносило радості приносити в жертву лоа, якому він служив усе своє життя. Коли сила його бога ринула в нього, верховний пророк присягнувся, що Погибель поплатиться за звірства, які змусили чинити тролів-драккарі."},
    [593] = {n="Колос Драккарі", d="Те, що тролі використовують моджо у своїй магії вуду, відомо вже давно, але злиття цих магій у големі стало революційним проривом. Їхній перший успіх привів до створення численних вартових, усі з яких походять від найпершого творіння — колоса."},
    [594] = {n="Моорабі", d="Драккарі прагнули принести в жертву Мам'тота заради його сили, та натомість лоа знищив сам себе. Попри це, Моорабі не збирався полишати свою богоподібну силу. Верховний пророк випив крові лоа й тепер не зупиниться ні перед чим, аби втримати Зул'Драк міцно в руках тролів."},
    [595] = {n="Ек Лютий", d="Після численних спроб перетворити невдалі досліди над ґорлоками на зброю драккарі позамикали їх. Поки тролі криги билися з Погибеллю, що вдиралася в їхню улюблену батьківщину, Ек і його посіпаки чекали миті, коли свобода буде поряд."},
    [596] = {n="Ґал'дара", d="Коли Погибель вторглася в державу Зул'Драк, дракарі звернулися до своїх лоа. Та морозні тролі прийшли до лоа не з благаннями — вони прийшли з клинками. Поки кров текла з їхнього вбитого бога Акалі, верховний пророк Ґал'дара та його зрадники привласнили силу лоа собі."},
    [597] = {n="Генерал Б'ярнґрім", d="Залізні війська Локена незліченні, і їхній генерал, Б'ярнґрім, стоїть над усіма. Як передовий загін Залів Блискавок Локена, залізний командир дбає про те, щоб кожен, хто вторгається у володіння його господаря, був знищений без жодного жалю."},
    [598] = {n="Волкан", d="Могутні легіони Локена — це свідчення майстерності його коваля, Волкана. Його праця не має кінця: він невпинно створює воїнів, що б'ються за полеглого хранителя. Лише тоді, коли витвори коваля стоятимуть над понівеченими тілами своїх ворогів, його роботу буде завершено."},
    [599] = {n="Іонар", d="Локен не покладається на своїх залізних слуг як на особистих захисників. Полеглий хранитель довіряє самій блискавці. Іонар та його посіпаки дістали прихисток у Залах Блискавок в обмін на безумовну відданість і готовність убивати кожного, хто наважиться кинути виклик їхньому новому господареві."},
    [600] = {n="Локен", d="Головному наглядачеві Азерота було доручено втримувати Йоґґ-Сарона в його в'язниці. Ніхто не міг передбачити, що саме той хранитель, якому довірили захищати світ від лиходійства Прадавнього бога, стане винуватцем його звільнення."},
    [601] = {n="Фалрік", d="Цей поборник Погибелі був серед перших лицарів смерті, створених Артасом після того, як той заволодів Морозною Скорботою. Фалрік віддано пішов за своїм принцом у приречений похід на Нортренд лише для того, щоб дістати в нагороду зраду від принца, якому вірно служив усе своє життя."},
    [602] = {n="Марвін", d="Марвін знав Артаса все своє життя і бачив у ньому не лише свого принца, а й справжнього друга. Коли Артас вирушив до Нортренду, лицар без вагань рушив за ним. Хоч друг згодом і простромив його серце проклятим рунічним клинком, Марвін усе одно відчув, як воно розбивається, коли побачив, на що перетворився принц."},
    [603] = {n="Втеча від Артаса", d="Дві очільниці прагнули здолати Короля-Ліча у двобої, та швидко зрозуміли, що їм не зрівнятися з могутністю єдиного справжнього короля. Прагнучи уникнути своєї долі, вони спробували втекти з його святилища. Артас смакував кожну мить їхніх марних зусиль. Від неминучого втечі немає."},
    [604] = {n="Кристаллус", d="Війну виборюють не самою лише силою — її виборюють армії. Ця проста істина надихнула Локена наказати створити вірних кам'яних істот, аби зміцнити свої легіони. Кристаллуса обрали наглядати за цією справою і розчавлювати кожного зайду, який загрожує її поступу."},
    [605] = {n="Діва Скорботи", d="Локен командує військами Ульдуара, та не всі служать йому з власної волі. Діві Скорботи наказано знищувати кожного, хто намагається відвоювати Зали Каменю. Вона тужить, що обертається проти колишніх союзників, але виконує накази з лютою рішучістю. Навіть її печаль перекували на зброю."},
    [606] = {n="Трибунал Епох", d="Абеднеум, Каддрак і Марнак складають Трибунал Епох — бібліотекарів титанічних дисків, що зберігають прадавню історію Азероту. Нерухомі конструкти неохоче розкривають таємниці титанів, але шукачі пригод на кшталт безстрашного Бранна Бронзобородого вважають, що нагорода варта ризику."},
    [607] = {n="Сьоннір Залізороб", d="Поки одні опиралися згубному впливу Локена, Сьоннір Залізороб залюбки взявся обернути Кузню Волі на темніший лад. Він вважає свої нові творіння значно досконалішими за земнароджених і нацькує їх на кожного, хто посміє кинути виклик волі Локена."},
    [608] = {n="Майстер-коваль Ґарфрост", d="Майстер-коваль Ґарфрост викував із сароніту чи не найсмертоносніші зброї Погибелі. Він наповнює повітря лиховісним холодом, і немає для нього більшої втіхи, ніж розчавлювати ворогів брилою руди, яку носить на спині."},
    [609] = {n="Ік і Крік", d="Крихітний некромант Крік наглядає за створенням жахливих потвор у Ямі Сарона. Крік виснажує ворогів темною магією, а тоді наказує моторошному Іку роздерти їх на шматки."},
    [610] = {n="Володар Кари Тираннус", d="Лицар смерті Тираннус був піднесений до Володаря Кари після того, як убив велетня Ґарфроста. Його міць і безжальність укупі з його морозним вирмом Раймфанґом роблять його ідеальним вартовим Ями Сарона та входу до Зал Відображення."},
    [611] = {n="М'ясний Гак", d="Відколи принц Артас уперше зустрів мерзоти Погибелі, вони стали ще загрозливішими. М'ясний Гак виріс сильнішим, отруйнішим і спритнішим за інших. Розум ніколи не був метою некромантів, що його створили, та для того, що він уміє найкраще, вистачає й простої хитрості."},
    [612] = {n="Салрамм Плоторіз", d="Салрамм Плоторіз був одним із перших некромантів, навчених у залах попід Сколомансом. Піддослідних, а часом і товаришів-студентів, він бачив лише як набір цікавих частин для своєї праці. Тепер для його дослідів є все населення Стратголма... разом із будь-якими чужинцями, що спробують його спинити."},
    [613] = {n="Хроноволодар Епох", d="Нескінченна зграя драконів часто вдається до витончених способів, щоб маніпулювати плином часу, та якщо це не вдається, вони можуть надіслати вбивцю, щоб розправитися з Артасом напряму. Хоч про агентів безкінечного рою відомо мало, Епох виявляє небезпечне володіння часом, що робить його смертельною перешкодою для майбутнього Артаса."},
    [614] = {n="Мал'Ганіс", d="Доля Мал'Ганіса вже написана. Ненависть Артаса до жахолорда змусить принца вирушити до Нортренду й узяти до рук Фростморн. Та станеться це лише тоді, коли Мал'Ганіс визнає його гідним. Щоб довести свою гідність і ступити на шлях до перетворення на Лихого Короля, Артас мусить пережити натиск Мал'Ганіса."},
    [615] = {n="Бронджам", d="Бронджам служив Культу Проклятих від найперших днів. Сам Кел'Тузад навчив Бронджама цінувати душі й перемелювати їх на паливо для машин Погибелі. Він здатен спаплюжити душі своїх ворогів і виривати їх клапоть за клаптем, що робить його ідеальним вартовим Кузні Душ Лихого Короля."},
    [616] = {n="Пожирач Душ", d="Темне ремесло, яким Бронджам займається в Кузні Душ, породжує понівечені, розколоті духи. Щоб не дати їм утекти й використати кожен клапоть проклятих, Король-Ліч створив Пожирача Душ. Пожирач Душ полює на заблукалі духи й поглинає їх, повільно перемелюючи у своєму жахливому нутрі. Поглинуті душі божеволіють від муки й страждань, та голод Пожирача годі вгамувати."},
    [617] = {n="Командир Стаутбірд", d="Командир Стаутбірд вів свої війська проти одних із найнебезпечніших ворогів Альянсу. Зали Застою, можливо, і сповільнили його, але вигляд шукачів пригод Орди миттю зведе його на ноги."},
    [618] = {n="Велика Магиня Телестра", d="Подейкують, що Велика Магиня Телестра була наставницею принца Кель'таса. Хоч вона й вважала союз принца з наґами безумством, вона не могла підтримати ув'язнення свого народу Далараном. Малігосу досить було нагадати їй про цю зраду, щоб здобути її як наставницю для своїх мисливців на магів."},
    [619] = {n="Аномалус", d="Спрямування такої величезної кількості арканної енергії Азероту через Нексус породило розриви в реальності. Поки сили Малігоса намагаються відкинути створінь, що вдираються, хаотична арканна міць набула форми Аномалуса. Якщо цю істоту не спинити, вона знищить усе, чого здатна торкнутися."},
    [620] = {n="Орморок Древотворець", d="Неймовірні арканні енергії Нексуса змінили Співучі Сади та їхніх вартових. Простий розум Орморока охопила одержимість енергіями, що його перетворюють. Для тих, хто перерве його роздуми, у нього мало слів, зате ціла гора люті."},
    [621] = {n="Керістраза", d="Чи були тортури, завдані Керістразі, помстою за смерть Сараґоси, чи хибною спробою навернути її в союзницю — відомо лише Малігосу. Та хай яким був його намір, її союзники чули її зойки муки й тривожний шепіт її згасаючого розуму."},
    [622] = {n="Дракос Допитувач", d="Ті, хто порушив закон Малігоса, можуть опинитися в пазурах Дракоса. Надійно замкнувши Керістразу в Нексусі, Дракос повернувся до Окулуса, щоб забрати нових в'язнів — інших драконів, які зчепилися з Малігосом. Він не обіцяє виправлення й не вдається до метафор. Його в'язні тут, щоб бути покараними, і втечі немає."},
    [623] = {n="Варос Клаудстрайдер", d="Варос Клаудстрайдер керував жорстокими нападами на Пакт Спочину Дракона від самого початку Війни Нексуса. Його відкликали, щоб вартувати Окулус, і він уже підготував своїх капітанів та драконів. Ба більше, Варос зачерпнув міці, що струмує крізь сам Окулус, аби зміцнити свою оборону."},
    [624] = {n="Лорд-Маг Уром", d="Уром покинув Кірін-Тор і присягнув на вірність Малігосу, який радо його прийняв. Маг-перебіжчик — безцінне надбання для синіх драконів. Він знає сильні та слабкі сторони Кірін-Тору. Він знає, як вони мислять. І він використає це знання, щоб їх знищити."},
    [625] = {n="Тельурний Вартовий Ереґос", d="Навіть герої здригнуться перед Ереґосом — захисником Окулуса, оборонцем провідника тельурних ліній і катом непроханих гостей. Він виконає ці завдання з переконаністю пророка, забезпечивши цілковите панування Плетільника Чарів над усім арканним."},
    [626] = {n="Ерекем", d="Серед в'язнів Фіолетової Фортеці зібралися найвідоміші злочинці Позамежжя, і Ерекем — не виняток. Кірін-Тор зірвали його змову з убивства Ради Шести, та нині сині дракони завербували цього підступного араккоа задля ще честолюбнішого діяння: винищити всіх магів Даларана до останнього."},
    [627] = {n="Мораґґ", d="Сіанігоса завербувала Мораґґа, щоб той допоміг їй знищити магів-відступників Даларана. Цей жахітливий демон колись служив Палаючому Легіону, потрошачи ворогів Саргераса під лиховісним поглядом своїх сімох очей. Тепер він покаже героям Азероту, що до Фіолетової Фортеці так просто не ввійдеш..."},
    [628] = {n="Іхорон", d="Дурноверхий учень прикликав цю примару зі стихійного плану — лише щоб з'ясувати, що невдоволені вояки Прадавніх Богів кепські улюбленці. Іхорон убила свого недомайстра й відтоді гниє у Фіолетовій Фортеці, прагнучи помститися своїм наглядачам."},
    [629] = {n="Ксевозз", d="Ксевозз був торговцем арканної зброї... доки Кірін-Тор не дізналися, що він озброює Палаючий Легіон. Тепер цей безкомпромісний ефіріал виконує діловий план із трьох пунктів: знищити ворогів, утекти з ув'язнення й повернутися до обслуговування свого найбільшого клієнта."},
    [630] = {n="Лавантор", d="Сіанігоса у своїй холодній хитрості випустила на волю пекельне полум'я магмового пса. Маги ув'язнили Лавантора, щоб приборкати кровожерливість двоголового жахіття, та роки самоти аж ніяк не вгамували його норов."},
    [631] = {n="Зурамат Знищувач", d="Знадобилася сотня найкращих воїнів Даларана, щоб подолати Зурамата; удвічі більше пішло на те, щоб прибрати побоїще з поля бою. Злоба Знищувача змушує замислитися навіть навіженого Малігоса, якому огидний потяг володаря Порожнечі до магії. Та геноцид породжує дивні союзи."},
    [632] = {n="Сіанігоса", d="Малігос обрав Сіанігосу для втілення своїх задумів через її беззаперечну відданість. Вона не здригнулася, коли її володар поринув у безумство; вона не завагалася, коли він захопив лей-лінії Азероту; і вона неодмінно винищить усіх, хто йому опирається."},
    [634] = {n="Великі Чемпіони", d="Король-Ліч невблаганний, його армії нежиті ринуть уперед, щоб задавити ворогів. Аби підготувати майбутніх чемпіонів до бою з ним, верховний лорд Тіріон Фордрінг влаштовує випробування мужності, витривалості та злагодженості. Його загартовані ветерани відсіють тих, кому бракує духу зустріти ненаситні юрми нежиті."},
    [635] = {n="Едрік Чистий", d="Перш ніж кинути виклик силам темряви, герої мусять подолати слуг Світла. Верховний лорд Тіріон Фордрінг обрав грізного паладина Багряного хрестового походу, щоб випробувати завзяття бійців. Едрік докладе всіх зусиль, аби відсіяти тих, кому бракує моральної стійкості ввійти в Цитадель Крижаної Корони."},
    [636] = {n="Багряна сповідниця Палетресс", d="Перш ніж кинути виклик силам темряви, герої мусять подолати слуг Світла. Верховний лорд Тіріон Фордрінг обрав грізну жрицю Багряного хрестового походу, щоб випробувати завзяття бійців. Палетресс зробить усе, що в її силах, аби лише ті, хто має міцну віру, постали проти Погибелі."},
    [637] = {n="Чорний Лицар", d="Король-Ліч підступний і не цурається віроломства, щоб здолати ворогів. Заради цього він підіслав Чорного Лицаря, аби той знищив найперспективніших бійців з армії верховного лорда Тіріона Фордрінга. Сама лише присутність цього мерця опоганює Колізей Хрестоносців, і ті, хто його здолає, доведуть свою гідність."},
    [638] = {n="Принц Келесет", d="Король-Ліч відправив Келесета до фортеці Утґарде, сподіваючись скористатися руйнівним потенціалом вікулів. Прибувши, посланець знайшов народ, що більш ніж охоче готовий служити Погибелі. Фортеця стала чудовим плацдармом, щоб тероризувати Завивний Фіорд, і Келесет аж ніяк не має наміру втрачати її через зухвалих чужинців."},
    [639] = {n="Скарвальд і Далронн", d="У вікулів є традиція змушувати працювати разом тих, від кого годі чекати співпраці. Одні кажуть, що так різні здібності доповнюють одна одну; інші — що це задля розваги короля Імірона. Хай там як, Скарвальд і Далронн — досконалий приклад цього звичаю. Поєднавши силу вікула й некромантське мистецтво людини, вони покарають усіх, хто стане на шляху Погибелі."},
    [640] = {n="Інґвар Грабіжник", d="Груба сила Інґвара легендарна навіть серед вікулів. Подейкують, що колись він здолав короля Імірона в бійці. Правди ніхто не знає, та оповідачі цієї історії зазвичай не доживають до того, щоб переказати її вдруге. Інґвар пообіцяв королю-личу, що вдасться до будь-якої жорстокості, аби втримати фортецю, — і цієї обіцянки він порушити не посміє."},
    [641] = {n="Свала Скорботна Могила", d="Свала прославилася як заступниця Інґвара Грабіжника, очолюючи небезпечні розвідувальні вилазки до застав Орди й Альянсу. Саме вона викрила ворожі плани вторгнення в Утґарде, давши королю-личу час підготуватися. За цю службу він перетворив її на вал'кіру — шановану діву-воїтельку Погибелі."},
    [642] = {n="Ґорток Блідокопит", d="Вікули зберігають у фортеці Утґарде безліч трофеїв, і Ґорток — один з найвражаючіших. Король Імірон виставляє напоказ жорстокий лик замороженого магнатавра як нагадування, що навіть найдикіші звірі — лише оздоба для зал вікулів. Якщо цю живу статую звільнити, вона сіятиме руйнування, виливаючи свою лють без розбору."},
    [643] = {n="Скаді Нещадний", d="Вікули дають прізвиська за діяння. Знищення роду Дракарі чи відрубування голів таунка можуть принести звання «сумлінний», та щоб тебе назвали «нещадним», потрібен справді ниций вчинок. Скаді здобув свій титул давно, безжально полюючи на вікулів, які прихищали потворних немовлят — попередників людства, засуджених Іміроном."},
    [644] = {n="Король Імірон", d="Гордий Імірон правив північними пустками, аж доки довгий сон вікулів не звів його нанівець. Отямившись, він виявив, що його дружину вбито, а землі обложено ворогами. Він зрікся своєї смертності й вимагає помсти, прагнучи показати страхітливу рішучість пробудженого велетня."},
    [649] = {n="Райґонн", d="Цей велетенський мантид очолює лобовий штурм воріт. Діючи як живий таран, Райґонн нещадно гамселить оборону пандаренів, прагнучи знищити будь-яку перешкоду на шляху безжального вторгнення мантидів у Пандарію."},
    [654] = {n="Зброяр Гарлан", d="Багряний хрестовий похід має чимало зброї, і новобранців належить навчити володіти клинком, молотом, стрілою та щитом — дієвими знаряддями проти нежиті. Зброяр Гарлан присвятив життя мистецтву володіння цими грубими інструментами й залюбки влаштує показову демонстрацію для блюзнірських ворогів походу."},
    [655] = {n="Саботажник Кіп'тілак", d="Мантиди добре обізнані з військовою справою й використовують технології, щоб переломити хід битви. Пандарени мають мало шансів проти таких знавців боєприпасів, як Кіп'тілак, котрий завдає ударів глибоко в тилу ворога й загрожує зруйнувати зсередини й без того ослаблені укріплення."},
    [656] = {n="Полум'яний ткач Кеґлер", d="Полум'яний ткач Кеґлер навчає найбільш схильних до магії адептів Багряного хрестового походу тонкощам арканного мистецтва. Його спеціальність — вогонь, і він застосував свої вміння, щоб спалити історичні фоліанти ордену, стерши минулі поразки хрестового походу. Окрім книжок, полум'я Кеґлера обернуло на купи димучого попелу багатьох — і нежить, і учнів, і випадкових порушників."},
    [657] = {n="Майстер Сноудріфт", d="Майстер Сноудріфт усвідомлює, що битви між Ордою та Альянсом спричинили жахливий стан монастиря. Герої, які прагнуть здобути вірність цього сторожкого пандарена, мусять спершу здолати його учнів. Лише ті, хто переможе, зможуть стати проти самого Сноудріфта — взірця бойових мистецтв, котрий присвятив життя досягненню досконалості тіла й духу."},
    [658] = {n="Лю Полум'яне Серце", d="Ще змалечку жриця Лю Полум'яне Серце вивчала цикл переродження Нефритового Змія Ю'лона. Коли напав Ша Сумніву, Лю першою стала на спротив, але вона ж першою піддалася псуванню. Тепер її пожирає непевність, і вона боїться, що їй може забракнути сил, аби забезпечити переродження Ю'лона."},
    [659] = {n="Наставниця Холодне Серце", d="Курс: Вступ до темних мистецтв\n\nНаставниця Холодне Серце прибула з Нортренду, щоб навчати дисципліни майбутніх некромантів, суворо караючи тих, хто її розчаровує. Вона повеліває крижаним холодом півночі й майстерно використовує бібліотеки Сколомансії зі смертоносним ефектом."},
    [660] = {n="Псар Браун", d="Найшвидший і найпевніший спосіб виявити нежить — це сморід гнилі, який вона несе, і навіть найдосвідченіший вояк не зрівняється з нюхом гончака. Псар Браун виростив і вишколив люту зграю псів, щоб допомагати хрестоносцям вистежувати ворогів — як живих, так і нежить."},
    [663] = {n="Джандіс Баров", d="Курс: Поглиблені ілюзії\n\nДух Баров роками блукав закутками Сколомансії, та нині вона взяла активнішу участь у навчанні нового покоління магів. Її величезні знання про ілюзії зробили її водночас цінною викладачкою й небезпечною супротивницею для кожного, хто буде досить дурним, щоб накликати її гнів."},
    [664] = {n="Хранитель знань Стоунстеп", d="Прислужники Ша Сумніву радо вдерлися до бібліотеки Храму Нефритового Змія, створюючи спотворені, руйнівні версії героїв та інших постатей пандаренських легенд. Попри всі свої зусилля, хранитель знань Стоунстеп так і не зміг повернути цим проявам минулого їхні незіпсовані подоби."},
    [665] = {n="Реттлґор", d="Курс: Реанімація 101\n\nВважалося, що Реттлґора знищили в Андоргалі, та Ґандлінґ одразу взявся готувати воскресіння цього торохкітливого жаху, щоб той охороняв від непроханих гостей. Темний майстер прагнув зробити Реттлґора лютішим, ніж будь-коли, наповнивши його невгамовним бажанням добувати сировину з тіл своїх ворогів."},
    [666] = {n="Ліліан Восс", d="Курс: Перевиховання\n\nНежить Ліліан Восс задушила свого батька — верховного жерця Багряного хрестового походу — за зраду, а потім влаштувала шал, який зрештою привів її до темних коридорів Сколомансії. Замість знищити порушницю, Темний майстер Ґандлінґ люб'язно вирішив показати Восс, як прийняти свою похмуру долю. Гнів і рунічні клинки, які вона колись скеровувала проти школи, тепер обернені на ворогів Ґандлінґа."},
    [668] = {n="Ук-Ук", d="Навіть як на гозена, Ук-Ук має славу грубіяна й буяна. Це жахливе створіння зі своїми посіпаками нещодавно вломилося до Броварні Штормостута й розпечатало її коштовні барила з пивом, щоб влаштувати найбільшу гулянку всіх часів: Укапалузу!"},
    [669] = {n="Гопталус", d="Гопталус — прокляття фермерів усієї Долини Чотирьох Вітрів. Це вірмен міфічних розмірів, здатний за одну ніч пожерти цілі лани врожаю. Подейкують, що велетенський шкідник зі своїм потомством оселився в броварні й заходився поглинати її запаси рису та ячменю."},
    [670] = {n="Ян-Жу Розкупорений", d="У відчайдушній спробі врятувати родинну броварню, дядько Ґао заходився готувати те, що мало стати найкращим елем — насичений еліксир бездонного смаку. Проте сміливий експеримент породив гірке й вкрай нестабійне пивне створіння, назване Ян-Жу Розкупореним."},
    [671] = {n="Брат Корлофф", d="Уперше про смертоносне мистецтво монахів брат Корлофф дізнався від послів пандаренів, коли ті мандрували Азеротом. Коли хрестоносець показав цей бойовий стиль своїм зверхникам, вони одностайно наказали Корлоффу навчити цілому поколінню послушників шляху монаха."},
    [672] = {n="Мудрий Марі", d="Шанований водомовець джинью Мудрий Марі незліченну кількість разів черпав знання та передбачення з Джерела Всевидця. Та коли Ша Сумніву спаплюжив звичні течії, Марі охопила безмежна недовіра й підозра."},
    [673] = {n="Ґу Хмарограй", d="До втечі ша Ґу Хмарограй відповідав за навчання елітних чаклунів Шадо-Пана. Тепер цей колись лагідний і стриманий пандарен з насолодою вивільняє свою вражаючу міць, сіючи спустошення. Він підкорив містичного Лазурового Змія, і його учні безпорадні перед смертоносними нападами Хмарограя."},
    [674] = {n="Верховна інквізиторка Вайтмейн", d="Ще зовсім юною Саллі Вайтмейн бачила, як її родина впала жертвою жахливої чуми немертя, коли вони мандрували північним Лордероном. Їй довелося знищити власних батьків, братів і сестер, коли ті повстали безмозкими слугами Погибелі, тож вона лишилася сама на сам із виною та люттю. Відтоді грізна жриця знаходить утіху й задоволення лише в одному: у винищенні немертвих."},
    [675] = {n="Бомбардувальник Ґа'док", d="Бомбардувальники — повітряна частина величезної армії імперії мантидів. Серед них є досвідчені аси, як-от Ґа'док. Здатний самотужки проливати вогняне спустошення на десятки ворогів, Ґа'док зі своїми посіпаками прагне принести оборонцям воріт смерть із небес."},
    [676] = {n="Командир Рі'мок", d="Командир Рі'мок керує наземними силами мантидів, які невпинно облягають височенні ворота. Не вражений оборонцями, Рі'мок прикликає незліченні підкріплення, щоб знищити кожного, хто наважиться стати йому на шляху."},
    [677] = {n="Воля Імператора", d="У серцевинній залі склепінь спочиває армія кам'яних воїнів, які століттями стоять непорушно. Ряди за рядами бійців — статуї, озброєні для битви, що так і не почалася. Які скарби вони стережуть? І що пов'язує їх із титанічною силою, похованою разом з ними тут, у пітьмі?"},
    [679] = {n="Кам'яна варта", d="Першою лінією оборони проти тих, хто наважиться ступити до сховищ, є непохитний ряд зачарованих звіриних статуй. Тверді, мов граніт, і невпинні у своїй варті, вартові Кам'яної варти постають нездоланною стіною полум'я, ікол і пазурів."},
    [682] = {n="Ґара'джал Зв'язувач духів", d="Очільник нападу зандаларських тролів на сховища, Ґара'джал Зв'язувач духів сповнений рішучості розкрити цю скарбницю прадавніх таємниць і винести звідти всю арканну силу й знання, які лише зможе знайти. Обдарований темними талантами й оточений вірним загоном зандаларських містиків, він пробив зовнішні мури й не спочине, доки сховища не належатимуть йому."},
    [683] = {n="Захисники Вічного", d="Коли Ша страху вдерся на Терасу Вічної Весни, троє шанованих захисників джинью були спотворені й зрадили решту смертних вартових, перебивши їх усіх. Тепер ці викривлені охоронці звернули увагу на будь-яких зайд, що могли б завадити нападу ша на останні рубежі оборони цих земель."},
    [684] = {n="Темний Майстер Ґандлінґ", d="Курс: Поглиблені студії\n\nНещодавня поразка в Андоргалі загнала Темного Майстра Ґандлінґа у найпохмуріший настрій. Дужче, ніж будь-коли, усім учням Сколомансу радять справляти на нього враження за кожної нагоди. Вихованців, що розчарують директора, видворять із класу на роботу в лабораторії... або зроблять із них самих об'єкт лабораторних дослідів."},
    [685] = {n="Ша насильства", d="Кровожерний, безжальний і дикий, Ша насильства лютує без упину в монастирі Шадо-Пан. Живлячись жорстокістю Орди й Альянсу, ця істота зловтішно нищить ченців, які щосили намагаються спинити жахливий натиск."},
    [686] = {n="Таран Жу", d="Ша ненависті спотворив Тарана Жу, прагматичного й могутнього очільника Шадо-Пан. Колись відданий захисту своєї любої домівки, тепер Жу палає клекітливою ненавистю до всього живого, що викривляє його сприйняття всього -- і всіх -- довкола."},
    [687] = {n="Королі духів", d="Прадавні літописи розповідають про цих легендарних правителів, могутніх моґу, що вирізьбили імперію з самої скелі Пандарії. Їхні імена й досі змушують землю тремтіти: Зіан Нескінченної Тіні, Менґ Божевільний, Чіанґ Нещадний і Субетай Стрімкий. Дехто каже, що їхні духи блукають сховищами, загублені в примарних спогадах про битви та славу."},
    [688] = {n="Талнос Душороздирач", d="Талнос здобув славу в Багряному хрестовому поході жорстокими тортурами, якими він \"очищував\" нових рекрутів. Зрештою цей садистичний маг підхопив чуму немертя й повстав жахливою кістяною істотою. Мстивий Талнос тепер никає цвинтарем монастиря, наказуючи привидам і зомбованим створінням нападати на кожного, хто вторгається в його нечестиві володіння."},
    [689] = {n="Фенґ Проклятий", d="Давним-давно Фенґ Шрі був доглядачем Сховищ Моґу'шан, якому доручили берегти скарби, складені в цих сутінкових залах. Після років вірної служби його спіймали на крадіжці з полиць (хоч дехто каже, що його підставив заздрісний підлеглий), і правитель моґу скарав його смертельним прокляттям. Відтоді приречений дух Фенґа Шрі блукає сховищами, спілкуючись із тінями колишніх героїв і воєначальників моґу."},
    [690] = {n="Ґеккан", d="Поки клани моґу б'ються за владу, хитрий Ґеккан веде свій грізний загін сауроків до славетних скарбниць палацу. Цим безжальним рептиліям зазвичай не властива відданість, але мужність і тактична геніальність Ґеккана пробуджують у його воїнах відчуття честі."},
    [691] = {n="Ша Гніву", d="Ша Гніву, фізичне втілення люті, вирвався з монастиря Шадо-Пан на вершині Кун-Лай. Серед жорстоких чвар, що охопили Пандарію, ця темна сутність дедалі дужчала. Останнім часом ша помічали, коли він блукав Кун-Лай, спотворюючи негативними енергіями все, що траплялося йому на шляху."},
    [692] = {n="Генерал Па'валак", d="Прагматичний генерал Па'валак не боїться ні пандаренів, ні їхніх союзників, і йому байдуже, чи долати ворогів власною могуттю, чи силою своїх армій мантидів. Перемога — єдина честь, якої він прагне, і Па'валак не терпітиме поразки, якщо його прислужники не досягнуть своєї мети."},
    [693] = {n="Візир Джин'бак", d="Візир Джин'бак нишпорить одразу за природним мостом мантидів, збираючи коштовний сік деревних коренів. Послуговуючись своїми великими алхімічними знаннями, ця грізна істота перетворює цю речовину на зброю та інші знаряддя, що допоможуть просунути облогу храму Ніузао."},
    [694] = {n="Адароґґ", d="Популяція троґґів у Прірві Лютого Полум'я за останні місяці стрімко скоротилася з однієї причини: Адароґґ. Цей зажерливий вогняний гончак був одним із перших свого роду, кого темні шамани вирвали з Вогняних Просторів. Наглядачі Адароґґа щодня згодовують норовливому звірові вдвічі більше троґґячої плоті, ніж важить він сам, щоб тримати його вгамованим."},
    [695] = {n="Темний шаман Корантал", d="Корантал завжди вважав, що груба сила — єдиний спосіб опанувати елементалів Азероту. Його крайні погляди привели його до лав лиховісного культу Сутінкового Молота. Коли культ занепав, цей орк та інші однодумці-шамани таємно проникли в Прірву Лютого Полум'я, щоб і далі вправлятися у своєму темному мистецтві."},
    [696] = {n="Слеґмо", d="На відміну від інших лавових червів, поневолених темними шаманами, Слеґмо виявився майже непідвладним контролю. Цей звір живе лише для того, щоб рити земні глибини, і йому байдуже до наслідків власних дій чи до шкоди, якої він завдає кожному, хто стане йому на шляху."},
    [697] = {n="Лавовий вартовий Ґордот", d="Зарозумілість штовхнула блискучого шамана Ґордота стати живим провідником для енергій, видобутих із Вогняних Просторів. Він і його союзники сподівалися повторити створення елементальних вознесенців культу Сутінкового Молота. Натомість вибуховий приплив сили звів Ґордота з розуму та спотворив його тіло до огидної подоби."},
    [698] = {n="Ксін Майстер Зброї", d="Титул майстра зброї має багато значень серед мешканців Азероту. Для Ксіна він означає, що зброя моґу кориться кожному його наказу. Король залюбки продемонструє свою смертоносну вправність кожному, хто засумнівається в його праві правити Пандарією."},
    [708] = {n="Випробування короля", d="Мінґ Підступний, Куай Брутальний і Гаян Незупинний прибули до палацу зі своїми кланами, змагаючись, щоб довести королеві свою гідність. Та ці угруповання моґу роздирають запеклі суперництва. Палацові землі ось-ось захлисне насильство, якщо ворогуючі клани не знайдуть способу випробувати свою силу, не зчепившись один з одним."},
    [709] = {n="Ша Страху", d="Ша Страху — фізичне втілення жаху в Пандарії. Колись давно ув'язнений легендарним імператором пандаренів Шаогао, ця сутність нещодавно набралася нової сили завдяки конфліктам, що наростають по всьому острову."},
    [713] = {n="Ґаралон", d="Можливо, настав час двічі подумати, перш ніж наступати на комах. Не глузуй із крихітних крил цього велетенського бегемота — це лише розлютить його."},
    [725] = {n="Бойова ватага Саліса", d="Безжальні сауроки никають Пандарією, крадуть усе, що можуть, і тероризують інших мешканців острова. Найзловіснішими серед цих рептилій-грабіжників є вождь Саліс і його бойова ватага. Роками сауроцький командир та його наскочники штурмували Долину Чотирьох Вітрів верхи на Ґалеоні — велетенському та добре озброєному мушані, що радше нагадує рухому фортецю, ніж звичайну їздову тварину."},
    [726] = {n="Елеґон", d="Прагнучи піднести свою імперію, моґу видобули й переробили технологію титанів, аби породити незмірну могутність у глибинах цього прадавнього комплексу. Чому ж ці енергії зосередили в холодній волі небесного дракона — таємниця, що криється в самісінькому серці сховищ."},
    [727] = {n="Командир ескадри Нер'онок", d="Рішучі удари командира ескадри Нер'онока вирішили сотні битв. Невеликі здобутки генерала Па'валака — ніщо порівняно з перемогою, якої, як вірить Нер'онок, він міг би сягнути, якби командував сам. Хоча його повітряні атаки вже спустошили захисників храму, цей крилатий жах і досі жадає нагоди довести свою вищість над генералом."},
    [728] = {n="Кривавий вартовий Порунґ", d="Під час кривавої облоги Шаттрата Порунґ штурмом узяв анклав дренейських паладинів, що забарикадувалися в одному з кутків міста. Він власноруч перебив захисників, але дістав тяжку рану, через яку не зміг піти за Ордою, коли та згодом рушила на Азерот. Тепер, оговтавшись, Порунґ служить Воєначальнику Карґату Блейдфісту в Цитаделі Пекельного Вогню, сподіваючись надолужити втрачені славетні битви й вписати своє ім'я в історію орків кров'ю ворогів."},
    [729] = {n="Лей Ши", d="Незліченні роки цей доброзичливий водяний дух пустував у Джерелах Безкінечної Весни з дитячим захватом і радістю. Коли в цьому мирному місці раптом спалахнули бої, Лей Ши побачила, як кришталево чиста вода каламутніє й мутніє, і жах огорнув її розум."},
    [737] = {n="Бурштинотворець Ун'сок", d="Прагнучи догодити своїй імператриці, Ун'сок створив кілька новаторських сумішей. Та близькість цього блискучого молодого алхіміка до королеви мантидів дала негативним енергіям ша вкоренитися в його розумі. Тепер всепоглинаючий страх невдачі штовхає Ун'сока творити дедалі смертоносніші зброї."},
    [738] = {n="Командир Во'джак", d="Те, чого командиру Во'джаку бракує у стратегічному хисті, він надолужує чистою лютістю. Його нищівні удари були вирішальними для того, щоб мантиди скористалися своїм підступним мостом і проникли на острів. Та складати плани битв — справа генерала мантидів; Во'джак прагне лише крові."},
    [741] = {n="Володар Вітру Мел'джарак", d="Володар Вітру Мел'джарак командує численними повітряними силами мантидів. Хоча від нього віє пихою, цей підступний комахоподібний запекло оберігає своїх вояків і полюбляє битися пліч-о-пліч із ними. Мел'джарак вважає мантидів вищими за всі інші раси й переконаний, що його народ непереможний."},
    [742] = {n="Цулон", d="Легенди розповідають про звивистого золотого змія, якого подеколи можна побачити високо в небі, як він ніжиться в сонячному світлі над хмарами. Ті небагато, хто стверджує, що бачив його на власні очі, кажуть, що ця істота запекло оберігає терасу."},
    [743] = {n="Велика імператриця Шек'зір", d="Стародавній орден Клаксі ухвалив скорботне рішення: зіпсуту велику імператрицю Шек'зір треба скинути. За звичаєм, постарілих володарів мантид заступає ретельно обраний спадкоємець. Однак та, кого визначили на заміну Шек'зір, ще надто молода й слабка, щоб усунути її, тож Клаксі не мають іншого вибору, окрім як убити теперішню імператрицю. Якщо проти неї не вжити заходів найближчим часом, уся Пандарія може впасти перед ненаситними роями мантид."},
    [744] = {n="Володар Клинків Та'як", d="Та'як відомий своїм терпінням і кмітливістю. У бою він майстерно виявляє слабкості супротивника й вичікує ідеальну мить для удару. Майстерність Та'яка з клинком неперевершена, і він залюбки передає своє воїнське знання молодим воїнам мантид."},
    [745] = {n="Імперський візир Зор'лок", d="Зор'лок викрикує свої проголошення так, щоб вони лунали по всьому розлогому палацу мантид. Він — Голос Імператриці, і самі його слова надихають воїнів комашиної раси без вагань віддавати життя. Незмінно відданий, Зор'лок ні перед чим не спиниться, щоб захистити свою улюблену матріарху, попри зіпсуття, що в ній зачаїлося."},
    [748] = {n="Обсидіановий вартовий", d="Обсидіановий вартовий охороняв таємниці Ульдамана, доки його не зіпсувала невідома сила. Спочатку цього хранителя витесали з того ж каменю, що й самі зали Ульдамана, та більшу частину його тіла замінили темним склом, здатним відбивати закляття. Хай би що спричинило перетворення Обсидіанового вартового, воно мусить бути неймовірно могутнім, адже змінити зачарований камінь титанічного витвору непросто."},
    [749] = {n="Командир Малор", d="Малор і жменька інших відважних воїнів ризикнули всім, щоб уберегти Багряний Бастіон від осквернення нежиттю. На жаль, вони зазнали поразки. Балназзар зіпсував безстрашного командира й зробив його одним зі своїх слуг, перетворивши затятого фанатика на жалюгідну подобу його колишнього себе."},
    [814] = {n="Налак, Володар Бурі", d="Коли Лей Шень виявив рідкісну кладку громових хмарозміїв, він сповнився благоговіння й узявся їх підкоряти. Найбільше з пташенят люто опиралося, і коли Лей Шень відвідав загони для приборкання, він гучно сміявся над обвугленими могу, що встеляли стіни. Він узяв пташеня собі, а за послух дарував йому владу над бурями й небом. Тисячі років після смерті Громового Короля Налак стеріг мури його прихованої цитаделі, чекаючи на його повернення."},
    [816] = {n="Рада Старійшин", d="Історія тролських племен — Драккарі, Фарракі, Амані та Ґурубаші — сповнена тисячоліть зради й чвар, але обіцянка Зандаларі про нову, нездоланну імперію нарешті об'єднала цих несхожих тролських вождів."},
    [817] = {n="Залізний Кон", d="Легенди оповідають про жорстокість Кона та його квіленів-чемпіонів. Безстрашного командира могу Громовий Король прозвав «Залізним Коном» за невгамовну рішучість здобувати для імперії перемогу за перемогою, хай би якою ціною."},
    [818] = {n="Дуруму Забутий", d="Лей Шень наказав своїм чаклунам виліпити аберацію, що могла б зазирати в серця його послідовників і викривати зраду. За цим велінням Дуруму отримав життя. Хитра істота вперто корилася своїм господарям аж до смерті Громового Короля, після чого зникла в лабіринтових коридорах цитаделі. Лише нещодавно Дуруму, майже забутий могу, вийшов зі свого сховку."},
    [819] = {n="Горрідон", d="Зандаларі привезли із собою на острів Громового Короля могутніх створінь, щоб використати їх як знаряддя війни. Очолювані Богом Війни Джалаком, дайномансери Звіриної варти Зандаларі застосовують стародавню племінну магію, щоб зміцнювати велетенських звірів і вимагати покори. Роги Горрідона, легендарної їздової тварини самого Джалака, можуть пробити кам'яні мури фортеці так само легко, як клинок розтинає шовк."},
    [820] = {n="Прімордіус", d="Глибоко в надрах острівної цитаделі Лей Шена ліпильники плоті могу створили саурок із магічної субстанції невідомого походження. Коли цитадель покинули, деякі експерименти надто довго томилися в темних водоймах..."},
    [821] = {n="Меґера", d="Навіть найжорсткіші з могу здригаються від думки про темні досліди, проведені за наказом Короля Грому. Давним-давно молодого хмарного змія спотворили на багатоголову гідру й покинули томитися під троном Лей Шена. Тепер ця викривлена істота чаїться глибоко в Забутих Глибинах, чекаючи миті, коли зможе нарешті завдати іншим своїх жахливих мук."},
    [824] = {n="Темний Анімус", d="За свого правління Лей Шен трудився над створенням механічного слуги, що боронив би його цитадель без страху. Коли перша спроба зазнала невдачі, Короля Грому охопила лють. Це негативне почуття він вклав у своє наступне й найуспішніше творіння — Темного Анімуса. І донині цей оздоблений конструкт виконує свій обов'язок, наснажений загадковою субстанцією, що лежить в основі всіх дослідів могу з ліплення плоті."},
    [825] = {n="Тортос", d="Упродовж тисячоліть невеликі краплі магії ліплення плоті могу просочувалися в печери під цитаделлю Короля Грому. Темні енергії викривили одну з місцевих драконових черепах і зрослили її з навколишніми кристалічними стінами. Цей сплав плоті й каменю, відомий як Тортос, відтоді живиться багатими покладами мінералів печери й виріс до колосальних розмірів."},
    [826] = {n="Ундаста", d="Коли почалася війна проти острівної цитаделі Лей Шена, розвідники Альянсу й Орди намагалися перехоплювати листи між головними таборами зандаларі. Один такий обмін посланнями, здавалося, обертався довкола незнайомого зандаларського слова, завжди оточеного словами про завоювання й могутність: Ундаста. Десь у Пандарії звіриний загін зандаларі вирощує своїх могутніх звірів як машини війни й завершує роботу над цією просякнутою лоа потворою. Та точне місцеперебування лишається невідомим..."},
    [827] = {n="Джин'рок Руйнівник", d="Коли Король Грому пробудився, він винагородив найвідданіших і найамбітніших тролів зандаларі могутністю, що перевершувала їхні найсміливіші мрії. Берсерк Джин'рок був одним із перших, хто отримав благословення Короля, і хоча дари Лей Шена ледь не розірвали його тіло, троль тепер здатен прикликати в бою лють бурі."},
    [828] = {n="Джі-Кун", d="Ліпильники плоті могу скидали свої невдалі творіння в бездонну шахту під фортецею Лей Шена. Сморід гниття вабив до сміттєвої ями багатьох стерв'ятників, зокрема й велику Джі-Кун. Безжальна й підступна, ця монструозна птаха пожирала суперників одного за одним, доки не запанувала одноосібно над тінистим тунелем."},
    [829] = {n="Емпірейні Близнючки", d="Емпірейні Близнючки — серед найгрізніших чемпіонів Короля Грому. Сповнений рішучості захистити своє правління, Лей Шен тримає вірних близько, а їхній спільний арсенал проти зайд — ще ближче."},
    [831] = {n="Ра-ден", d="Життя Лей Шена змінилося назавжди, коли він натрапив на темну палату під тим, що нині зветься Сховищами Моґу'шан. Легенда каже, що там він знайшов прадавнього хранителя титанів, який стеріг дивовижний пристрій, відомий як Машина Налак'ша. Ніхто не знає, що сталося між цими двома істотами, але згодом Лей Шен вийшов із того місця, переповнений силою, здатною викувати імперію. Доля хранителя — і його теперішнє місцеперебування — лишаються таємницею."},
    [832] = {n="Лей Шен", d="Тиран. Диктатор. Завойовник. Імператор. Ці титули Короля Грому здобуто стражданнями, які він приніс кожному народові Пандарії. Воскреслий у світі, де його народ уже не панує, Лей Шен налаштований покласти край цьому фарсу й знову підкорити цю землю своїй волі."},
    [833] = {n="Командир Колурґ", d="Командир Колурґ шукав небезпечні скарби, щоб поповнити збройні Орди. Його гнів через злощасну долю в Залах Застою аж ніяк не вщухне, коли він відтане й виявить, що шукачі пригод Альянсу перехопили його тріумф."},
    [834] = {n="Великі чемпіони", d="Король-Ліч невблаганний, його армії нежиті ринуть уперед, щоб зломити супротивників. Аби загартувати майбутніх чемпіонів проти нього, верховний лорд Тіріон Фордрінг влаштовує випробування мужності, витривалості й злагодженості. Його загартовані ветерани відсіють тих, кому бракує духу стати проти ненаситних полчищ нежиті."},
    [846] = {n="Малкорок", d="Малкорок був найвірнішим і найнадійнішим лейтенантом Ґарроша впродовж усієї пандарійської кампанії. Коли вождю знадобився доброволець, щоб наповнити його силою Й'Шаараджа, цілком природно, що Малкорок зголосився без жодного вагання."},
    [849] = {n="Полеглі захисники", d="Золотий Лотос і вартові Шадо-Пан із Долини Вічного Цвітіння опинилися в епіцентрі нищівного вибуху, що понівечив Долину, і темні енергії розірвали їх на шматки. Їхні духи лишилися в місці, яке вони колись охороняли, спантеличені й змучені власною поразкою."},
    [850] = {n="Генерал Назґрім", d="Колишній рядовий на службі тодішнього вождя Тралла, генерал Назґрім швидко піднявся в чинах після нищівних перемог у Ґризлі-Гіллз та затонулому місті Вашш'їр. Безмежно відданий Орді й зв'язаний суворим кодексом честі та обов'язку, Назґрім триматиме рубіж за свого вождя до останнього подиху."},
    [851] = {n="Ток Кровожерливий", d="Коли біля берегів Пандарії відкрили Острів Велетнів, що кишів первісними дияволозаврами, Ґаррош послав загони, щоб упіймати кількох найстрашніших особин, сподіваючись підкорити їх і використати як бойових звірів. Незліченні орочі приборкувачі звірів загинули в пащі Тока, намагаючись його приручити, та спрага крові цього створіння й досі невгамовна."},
    [852] = {n="Іммерсеус", d="Прадавні мешканці Пандарії розуміли життєву важливість живодайних Озер Сили й збудували підземну систему акведуків, щоб оберігати ці води й живити життя в Долині Вічного Цвітіння. Дотик скверни оживив і спотворив ці води, і Іммерсеус постав протиприродним утіленням скорботи Долини."},
    [853] = {n="Взірці Клаксі", d="Дев'ять уцілілих Взірців Клаксі'ва — прадавні чемпіони мантидів, що билися пліч-о-пліч із Пробудником проти безумства імператриці Шек'зір. Та Взірці, як і всі мантиди, плекають куди глибшу відданість. Коли Ґаррош видобув серце Й'Шаараджа, Взірці пішли за шепотінням свого прадавнього володаря до залізних залів під Оґриммаром."},
    [856] = {n="Темні шамани Кор'крон", d="Гаромм і Кардріс навчили тисячі шаманів шанобливо шепотіти до стихій, щоб просити їхньої допомоги. Та армія Ґарроша не просить — вона бере те, що бажає, в ім'я Справжньої Орди. Темне шаманство силоміць поневолює стихії, обертаючи їх на вигорілий попіл, отруєні води й токсичне повітря."},
    [857] = {n="Чі-Джі, Червоний Журавель", d="Випробування Чі-Джі — це випробування надії. Не певний майбутнього свого народу, імператор Шаохао вирушив на пошуки великого Червоного Журавля. Великий Журавель кинув Шаохао виклик: знайти надію в собі самому й відкинути сумніви. Щойно Ша Сумніву було подолано, імператор став для свого народу маяком надії. Щоб пройти випробування Журавля, воїни мусять вірити в надію навіть у найтемніші дні."},
    [858] = {n="Ю'лон, Нефритова Змія", d="Випробування Ю'лон — це перевірка мудрості й віри. Гнаний видіннями похмурого майбутнього, імператор Шаохао піднявся на вершину гори Невелика, щоб просити поради в Нефритової Змії. Ю'лон закликала Шаохао відкинути темні почуття, що його мучили, і через випробування імператор Шаохао мав злитися воєдино із землею. Щоб пройти випробування Змії, воїни мусять бути мудрими у своїх рішеннях."},
    [859] = {n="Нюзао, Чорний Віл", d="Випробування Нюзао — це перевірка хоробрості й мужності. Коли імператора Шаохао охопив страх, Чорний Віл порадив йому подивитися страхам прямо в очі. Після тривалої битви з Ша Страху імператор вийшов переможцем. Щоб пройти випробування Вола, воїни мусять бути незламними перед лицем нездоланної небезпеки."},
    [860] = {n="Сюень, Білий Тигр", d="Випробування Сюеня — це водночас перевірка сили й стриманості. Коли Сюень дав імператору Шаохао триметровий жердину й попросив ударити одного зі своїх воїнів, імператор не зміг завдати удару. Адже без стриманості гнів і ненависть виходять з-під контролю. Щоб пройти випробування Тигра, воїни мусять опанувати свою силу, поховавши думки про насильство."},
    [861] = {n="Ордос, Бог Вогню Яунґолів", d="Колись Ордос був шаманом яунґолів, який пожертвував себе полум'ю, дослухавшись до обіцянок Володарів Вогню, щоб стати напівбогом. Його плоть навіки обпалена вогнем, прирікаючи його на нескінченну муку. Вогнехранителі яунґолів ритуально підпалюють себе, щоб уподібнитися до сходження Ордоса, і творять чари та молитви, аби полегшити його біль."},
    [864] = {n="Залізний Велетень", d="Цей механічний жах, створений майже настільки ж для залякування, як і для руйнування, є осердям облогового арсеналу Ґарроша. Зроблений за подобою могутнього бойового скорпіона кор'кронів, Залізний Велетень охороняє ворота Оґриммара, трощачи всякого, хто наважиться кинути виклик Справжній Орді Ґарроша."},
    [865] = {n="Облоговик Чорнопал", d="Гелікс Чорнопал був єдиним ґобліном, у якому поєднання інженерної майстерності, професіоналізму й безжальності задовольнило Ґарроша в його пошуках інженера для Справжньої Орди. Найманець у душі, Чорнопал так любить свої творіння (і золото, що вони приносять), що навіки пов'язав свою долю з долею свого покровителя й Воєначальника."},
    [866] = {n="Норушен", d="Дехто каже, що раса моґу була створена за подобою цього титанічного конструкту, залишеного глибоко під Пандарією, щоб стерегти й охороняти найтемнішу й найнебезпечнішу таємницю континенту."},
    [867] = {n="Ша Гордині", d="Сьоме ша, Ша Гордині, було останнім тягарем, за який чіплявся імператор Шаохао; воно огорнуло землю туманом і чекало слушної миті тисячоліттями. Коли Ґаррош пробудив Серце Й'Шаараджа, сила його зарозумілості змусила цю темну енергію зібратися в залі, де було відкопано Серце."},
    [868] = {n="Ґалакрас", d="Воєначальниця Зейла зав'язала тісний зв'язок із Ґаррошем під час подій у Сутінковому Нагір'ї, і вона разом зі своїми орками клану Драконячої Пащі присяглася на вірність справі Ґарроша. Верхи на грізному Ґалакрасі, прямому нащадку катаклізмічного прабатька всіх драконів, Зейла керує морською обороною Оґриммара."},
    [869] = {n="Ґаррош Хеллскрім", d="Ґаррош, син Ґроммаша Хеллскріма, уперше дізнався про геройство свого батька, коли Тралл зустрів молодого орка в Запределлі. Так було посіяно зерна гордині. Ґаррош очолив перемоги Орди в Нортренді й, ставши Воєначальником, зміцнив могутність Орди серед хаосу Катаклізму. Та його марення про зверхність орків за будь-яку ціну привели армії світу до стін Оґриммара... остаточна розплата, на яку сам Ґаррош чекає з лютим завзяттям."},
    [870] = {n="Здобич Пандарії", d="Коли Ґаррош окинув поглядом Пандарію, він побачив незліченну приховану силу. Упродовж своєї кампанії Ґаррош награбував зброю, скарби й артефакти пандаренів, моґу і мантидів. Усе це зберігається на складі глибоко в його підземній базі, який стереже загадкова охоронна система, схоже, титанічного походження."},
    [881] = {n="Ґалакрас", d="Під час подій у Сутінковому нагір'ї між Воєначальницею Зейлою та Ґаррошем зав'язався міцний зв'язок, і вона разом зі своїми орками клану Драконячої Пащі присягнула на вірність справі Ґарроша. Верхи на грізному Ґалакрасі, прямому нащадку катаклізмічного прабатька всіх драконів, Зейла керує морською обороною Оґриммара."},
    [887] = {n="Ролталл", d="Ролталл — грізний елементаль, якого власноруч прикликав Ґуґ'рокк і прив'язав до порога своїх покоїв як останній засіб захисту на випадок повстання рабів. Вогняна істота вічно вартує на призначеному їй місці, скликаючи розплавлене каміння, щоб відбити будь-яких зайд."},
    [888] = {n="Наглядач рабів Крушто", d="Цей жорстокий оґр-наглядач керує видобутком у задушливих копальнях під Хребтом Льодяного Полум'я. Рабів з усього Дренору приводять під опіку Крушто, який вважає їх легко замінними і не вагаючись б'є їх до покори (чи й гірше), якщо вони порушать порядок."},
    [889] = {n="Ґуґ'рокк", d="Ґуґ'рокк народився в столиці Гаймолі й спершу зневажав своє призначення губернатором копалень Кривавого Молота глибоко під Хребтом Льодяного Полум'я. Та з часом він навчився цінувати переваги роботи на околицях Горіанської імперії, з абсолютною владою і мінімальним наглядом."},
    [893] = {n="Маґмолатус", d="Оґри-геоманти Льодяного Полум'я пишаються своїм умінням підкоряти стихії, та інколи перегинають палицю. Ґоґ'ду роздмухав полум'я своєї кузні до небаченого жару, чим довів Маґмолатуса до такої люті, що тепер йому потрібна вся зосередженість, аби тримати розлюченого шлакового елементаля під контролем."},
    [895] = {n="Рооґуґ", d="Суспільство кабанрилів вважає читання каменів і кристалів найвищою формою шаманства. Рооґуґ багато років служив народу кабанрилів, тихо вдосконалюючи своє віщунське мистецтво. Тепер він служить кабанрилам як наглядач усіх геомантів і зібрав потужний набір кристалів, щоб розправлятися зі слабшими ворогами. Лише питання часу, коли ці містики заполонять Південний Степ."},
    [896] = {n="Мисливець Кістоклик", d="Якщо досягнення мисливця вимірюються трофеями, з якими він повертається, то Кістоклика вважали б одним із найкращих. Його влучне око та звіриний інстинкт піднесли його вміння полювати й вистежувати на нову висоту, і лише найсильніші мають шанс вижити проти цього бувалого мисливця."},
    [899] = {n="Воєначальник Тараноклик", d="Командувач військ Гостроклика, Воєначальник Тараноклик — велетенський старіючий кабанрил, чия товста шкура вкрита шрамами незліченних битв з кентаврами, гарпіями, орками і навіть тауренами. На схилі літ Тараноклик прихилився до товариства духовних провідників кабанрилів; Аґґем Тернопрокляття та Речниця Смерті Джарґба скеровують його думки зі світу духів."},
    [900] = {n="Ґроят, сліпий мисливець", d="Після років усамітнення з глибин темного грота вийшла жахлива істота. Цей величезний кажан безперестанку живиться плоттю вепра, що колись звався Аґателос Несамовитий, чию темну силу свого часу живило безупинне пожирання кажанячого посліду."},
    [901] = {n="Чарлґа Різороздерка", d="Очільниця (або «стариця») племен Різорфену — Чарлґа Різороздерка, квілбоарка, чиї експериментальні й могутні мистецтва геомантії не мають собі рівних. Її стрімке піднесення до влади й насильство, що швидко наростає поміж квілбоарськими племенами, можуть привести лише до одного — до війни."},
    [959] = {n="Блекгенд", d="Безжальний тиран і лютий воїн, Блекгенд — Воєначальник клану Чорної Скелі, що поступається в Залізній Орді лише Ґроммашу. Огорнутий пекучим жаром, який витримали б небагато смертних, Блекгенд наглядає за роботою своєї Ливарні з висоти її Горнила, орудуючи тліючим шлаковим молотом, аби кувати зброю незрівнянної якості."},
    [965] = {n="Ранджит", d="Ранджит усе своє життя відточував майстерність володіння гострим чакрамом, і з ростом цієї майстерності у володінні традиційною зброєю аракоа він виявив, що може скеровувати сам вітер і обертати його проти ворогів. Тепер він стереже вхід до внутрішнього святилища Небосяга, готовий загинути, щоб захистити осідок влади аракоа на вершині Шпилів."},
    [966] = {n="Аракнат", d="Верховні аракоа Небосяга пильно спостерігали за цивілізацією дренеїв, виявляючи неабияку цікавість до величних Вартових, що охороняють їхні міста й храми. Аракоа поставили собі за мету створити власну, досконалішу версію, живлену сонячною енергією, — незмінно покірну машину руйнування."},
    [967] = {n="Рухран", d="Цей величний птах, якого мовлять, нібито нащадок сонячного божества аракоа Рухмара, ширяє в небесах над Шпилями Арака. Рухран має спорідненість із сонячною енергією й може вбирати силу сонця, а тоді вивільняти її, аби спопелити будь-яку здобич."},
    [968] = {n="Верховна мудриця Вірікс", d="Верховна мудриця Вірікс цілковито присвятила своє правління опануванню апексійських артефактів на службі волі Рухмара. Нарешті, завдяки завершенню велетенської кристалічної суперзброї, що фокусує енергію сонця, аби нищити ворогів, для аракоа настав час посісти своє законне місце володарів Дренору."},
    [971] = {n="М'ясник", d="Народжений у смердючому Череві Гаймолу, цей оґр, можливо, колись і мав справжнє ім'я, та воно давно забуте. Знущання й побої, які він терпів змалечку, лише загартували його тіло, навіть коли зламали його розум. Тепер у Гаймолі немає жодного оґра, який не обходив би його десятою дорогою, поки той дні безперервно рубає вбиті туші."},
    [1122] = {n="Володар Звірів Дармак", d="Замолоду Дармак, обдарований приборкувач звірів, швидко піднявся в лавах Громовержців. Там, де інші бачили лише тваринні інстинкти, він розпізнавав розум і пробуджував нерозкритий потенціал мозку, м'язів і кісток. Коли Залізна Орда зажадала його служби, Дармак не уявляв собі більшої честі, ніж споряджати й приборкувати найдикіших звірів, яких лиш міг запропонувати Дренор."},
    [1123] = {n="Приборкувачка Полум'я Ка'ґраз", d="Під прапором Залізної Орди Блекгенд найняв Приборкувачку Полум'я Ка'ґраз із Палаючого Клинка, аби та наповнювала викуване кланом Чорної Скелі озброєння есенцією полум'я. Разом зі своїм помічником Акнором Сталеносцем Ка'ґраз невтомно працює біля вічно палаючої кузні на підтримку завоювання Дренору Залізною Ордою."},
    [1128] = {n="Карґат Блейдфіст", d="Карґат Блейдфіст, Воєначальник Розтрощеної Длані, відточив свою жорстоку майстерність рабом на гладіаторських ігрищах оґрів. Він винищив незліченних супротивників заради обіцянки свободи, та після перемоги його замкнули разом з іншими «чемпіонами на спочинку». Палаючи люттю, Карґат відірвав власну руку, щоб утекти, і очолив повстання, що залило Дренор кров'ю оґрів. Тепер він повертається на арену, аби навчити тебе справжнього значення дикості."},
    [1133] = {n="Володарка небес Товра", d="До піднесення Залізної Орди Товра ніколи не виходила за межі морозної тундри Морозного Вогню, де очолювала загони слідопитів Володарів Грому, аби ловити й приборкувати найлютіших рилаків Дренора. Завдяки своїй владі над рилаками Товра стала безцінним надбанням, і тепер вона командує повітряними силами Залізної Орди."},
    [1138] = {n="Рокетспарк і Борка", d="Майстер рейок Паулі Рокетспарк, головний наглядач депо Ґрімрейл, був найнятий Ґаррошем Хеллскрімом, аби збудувати технології, потрібні для розбудови Залізної Орди. Отримавши недоумкуватого помічника Борку для важкої праці, Рокетспарк узявся будувати Ґрімрейл."},
    [1139] = {n="Садана Бладф'юрі", d="Садана Бладф'юрі — могутня послушниця клану Шедоумун, тісно пов'язана з місячними циклами. Коли шепіт темної зорі прокрався в серця Шедоумунів, Садана пішла за своїм вождем Нер'зулом у поховальні землі клану, де своєю силою принаджувала духів мертвих заради лиховісної мети."},
    [1140] = {n="Кістопаща", d="Глибоко в підземних печерах під Долиною Шедоумун трупоїдний черв Кістопаща живе у симбіозі з послідовниками Нер'зула: істота пожирає мертвих, що лишаються після темних ритуалів культу Шедоумун, а взамін слугує грізним вартовим внутрішнього святилища Нер'зула."},
    [1141] = {n="Амненнар Морозоносець", d="Колись лич Амненнар був грізною силою в лавах Погибелі й брав участь у нападі на гору Гіджал під час Третьої війни. Згодом Король-Ліч наказав своєму слузі лишитися в Калімдорі та поширювати вплив Погибелі. Однак ці зусилля зруйнували герої Орди й Альянсу. Тепер відносному спокою, що настав у Курганах Гострозубів, може настати кінець. Речник смерті Блекторн прагне воскресити цього могутнього лича й відновити напад на Степи."},
    [1142] = {n="Аарукс", d="Павукомани культу Мертвої Голови особливо пишаються своєю працею. Після багатьох невдалих спроб вони нарешті створили гідного вартового для Речника смерті Блекторна. Аарукс — велетенський павук, чиє тіло вкрите наповненими отрутою гнійниками, що лускають і сочаться згубною рідиною. Тепер павукомани чекають слушної миті, аби спустити своє творіння з прив'язі."},
    [1143] = {n="Грибогруд", d="Грибогруд — нещодавнє творіння Речника смерті Блекторна, гротескне нагромадження частин, зібраних з інших невдалих витворів. Сповнений жовчі, гною та інших згубних рідин, Грибогруд отруює зали, що ведуть до Речника смерті Блекторна."},
    [1144] = {n="Кат Ґор", d="Що дужче зростає міць Аку'май, то більше потрібно жертв. Тягти скривлених від крику невинних на смерть — це фах Ката Ґора, і культ Сутінкового Молота охоче користається його послугами."},
    [1145] = {n="Трук", d="Трук дає культу Сутінкового Молота чимало цінних рис, однак розум до них не належить. Переконаний, що вбивство Вартового Глибин відкриє йому величезні скарби золота, Трук своїм недалеким розумом не здатен зосередитися більше ні на чому й розшматує плоть кожного, хто перерве його зосередження."},
    [1146] = {n="Речник смерті Блекторн", d="Речник смерті Блекторн швидко піднявся в лавах культу Мертвої Голови після поразки Амненнара Морозоносця. Невдовзі після того, як він захопив владу над культом, Блекторн почав чути темний шепіт. Той шепіт обіцяв йому неймовірну могутність і багатство, якщо він зуміє повернути Амненнара до життя. Гнаний неприродними силами, Блекторн знайшов схованку філактерії Амненнара й повернувся до Курганів Гострозубів, аби довершити ритуал, що знову поверне його колишнього володаря до життя."},
    [1147] = {n="Машиніст Тоґар", d="Більше відомий жорстокістю та хитрістю, ніж грубою силою, Тоґар наглядає за роботою Похмурої колії. З депо Ливарні він керує наземною битвою проти дренеїв у Таладорі, маючи під рукою цілі батальйони військ та артилерії."},
    [1148] = {n="Оґрони-близнюки", d="Охороняючи вхід до Гортенону на вершині Гаймолу, Пол і Фемос є особистою вартою імператора Мар'ґока. Незрівнянні у силі та рішучості, ці брати-оґрони відшкодовують брак розуму своїми величезними розмірами та грубою силою."},
    [1153] = {n="Ко'раг", d="Ко'раг був єдиним оґром, що вижив після прямого зіткнення з таємничою реліквією, яку відкопали під час розкопок Гаймолу в Наґранді, і це лишило йому майже повну несприйнятливість до будь-якої магії. Чутки про його зв'язок з імператором не вщухають, і дехто дивується, чому ж Ко'раг лишається підлеглим чаклуна, попри свій унікальний дар."},
    [1154] = {n="Плавильна піч", d="Унікальна здатність клану Чорноскелих плавити чорну руду — речовину настільки щільну, що звичайне полум'я навіть не розм'якшує її — завжди була їхньою найпильніше оберігуваною таємницею. У глибинах Ливарні їхня піч містить первісну силу, давню, як сам Дренор, що шаленіє у межах своєї в'язниці, випромінюючи неприродний жар."},
    [1155] = {n="Ганс'ґар і Францок", d="Ганс'ґар і Францок — брати-близнюки, виховані й навчені як майстерні бійці свого клану. Обидва прокладали шлях слави як воїни, та доля мала інші плани. Жоден з братів не схотів убити іншого в обряді мак'ґора, тож їх вигнали з клану і покинули помирати. Вони вижили як ізгої в дикій глушині Дренору, а коли покликала Залізна Орда, ці могутні воїни знайшли новий дім у велетенській воєнній машині."},
    [1160] = {n="Нер'зул", d="Нер'зул, вождь і старійшина-шаман клану Тіньомісяця, пожертвував серцем і душею свого племені, намагаючись приєднатися до Залізної Орди. Тепер він відступив до давніх поховань свого клану, заглиблюючись усе далі темним шляхом, прийнявши силу Порожнечі та некромантські мистецтва."},
    [1161] = {n="Ґруул", d="Ґаррош знав, що найвірніший шлях зломити ґроннів лежить через підкорення їхнього великого батька, Ґруула. Відомий в інші часи як Драконовбивця, тут Ґруул зведений до ролі чорнороба. У жорстокому глумі над воїнською традицією Розбитої Длані, його руку замінили гаком, щоб він міг легше тягати піддони з паливом до печі."},
    [1162] = {n="Кромог", d="Магнарони таємничі у своїх звичаях, давні й незбагненні. Копачі, що розширювали Ливарню задля величезних виробничих потреб Залізної Орди, з жахом відкопали камеру, де містився живий магнарон. На їхній подив, Кромог почав допомагати їм у їхній справі, і тепер він своїми величезними кам'яними кулаками викльопує гігантські плити, потрібні для дредноутів та облогових машин Залізної Орди."},
    [1163] = {n="Нітроґґ Громовежа", d="З палкою любов'ю до вогню та вибухівки, Нітроґґ ідеально вписався в механізовану й озброєну армію, яку плани Ґарроша принесли до Дренору, і він швидко піднявся в лавах Залізної Орди. Він наглядає за артилерією на Похмурій колії і прагне прорвати оборону навколо Шаттрата та підкорити ворогів Залізної Орди всередині."},
    [1168] = {n="Налліш", d="Коли Нер'зул розірвав тканину реальності й дозволив Порожнечі ринути на ритуальні поховання клану Тіньомісяця, лиховісний дух Налліш пройшов крізь той розлом у пошуках душ, якими можна живитися. Давній і народжений з чистої темряви, Налліш прагне пожерти все живе."},
    [1185] = {n="Пильний Каатар", d="Найвеличніших воїнів дренеїв можуть прикликати на одну останню службу, коли вони стоять на порозі потойбіччя: оселитися в одному з броньованих конструктів, що слугують вічними захисниками Аучиндона й цивілізації дренеїв на Дренорі. Цьому Пильному доручено стерегти останній уцілілий кристал, що живить щит навколо Аучиндона."},
    [1186] = {n="Полонителька душ Ньямі", d="Ньямі — жриця дренеїв, якій довірено посаду берегині душ, тож вона має доступ до найсвятіших місць Аучиндона. Та насправді вона віддана Тіньовій Раді й замишляє знищити бар'єр, що захищає мавзолей від загарбників."},
    [1195] = {n="Тектус", d="Тектус — прадавнє втілення хаотичних сил, що сформували землі Дренора. Його спотворили й поневолили збожеволілі бліді орки, які самі ледве здатні втримати під владою цю грізну силу природи."},
    [1196] = {n="Папоротеспор", d="Велетенський корабель Залізної Орди, що став на якір у водах біля Хаймолу, привернув увагу Папоротеспора, прадавнього блукача глибин. Цей водяний гігант лишає за собою грибний наріст і мох, а первісний інстинкт жене його стерти будь-які сліди цивілізації на Дренорі."},
    [1197] = {n="Імператор Мар'ґок", d="Як великий Імператор Хаймолу, Мар'ґок походить із довгого роду чаклунів, що правили Ґоріанською імперією. Однаковою мірою хитрий і жорстокий, Мар'ґок розгледів зростання сили Залізної Орди й те, що означало б їй опиратися. Тож він пристав на союз із Ґроммашем, не полишаючи водночас пошуків способу знову схилити рівновагу влади на свою користь."},
    [1202] = {n="Рудожер", d="Склади Блекрокської ливарні, ущерть повні купами й піддонами необробленої блекрокської руди, — то справжній бенкет для ненажерливих, каменоїдних ґоренів, що прорилися до цієї зали. Рудожер — без сумніву, найбільший із загарбників: ненажерливість роздула його тіло далеко за межі будь-якого ґорена, бачених досі на Дренорі."},
    [1203] = {n="Залізні Діви", d="Маючи мало нагод виявити свій тактичний хист за давнім устроєм орочих кланів, Ґа'ран із захватом стала однією з перших воїтельок, які зголосилися на службу у флоті Залізної Орди. Здобувши перемогу одразу в першому ж бою, вона була названа Адміралом флоту Залізної Орди й обрала Марака та Сорку своїми лейтенантами. Разом їх звуть Залізними Дівами, і вони розчавили кожного, хто наважився стати їм на герць."},
    [1207] = {n="Прадавні Захисники", d="Ґола й Телу, двоє лісничих-ботані, поширюють повзучий наріст, спонукаючи ліс поглинути й повернути собі злощасний форпост у своїй гущавині. Поки вони виконують це завдання, їх стереже жахливий здоровань Дулху — колись член клану Блекрок, що давно забрів надто далеко в первісні хащі, а нині більше рослина, ніж орк."},
    [1208] = {n="Архімаг Сол", d="Архімаг Сол була серед останніх, хто тримався в експедиції Кірін Тор на Бузковій Кручі, та зрештою й вона піддалася спорам, що пустили коріння в її мозку. Можливо, десь глибоко в ній ще лишилася часточка людяності, але тепер вона живе бранкою у власному тілі."},
    [1209] = {n="Ксері'так", d="Ця отруйна павуча матріарх стереже свій виводок у печері глибоко в пагорбах Ґорґронда, ловлячи в тенета й пожираючи будь-яку здобич, що має нерозважливість підійти ближче."},
    [1210] = {n="Ялну", d="Прадавній і незбагненний генезавр Ялну прийшов до застави Кірін-Тору в Ґорґронді, приваблений дивною енергією, що променіла з кручі. Незліченні віки генезаври билися зі своїми одвічними ворогами — маґнаронами, ґроннами, дітьми каменю — і не могли здолати їх по всій Дренорській землі. Та в цих випромінюваннях Ялну відчув новий світ, де його рід міг би розквітнути й нестримно розростися."},
    [1211] = {n="Тарлна Безвічний", d="Кажуть, що до приходу Тарлни в Ґорґронд увесь цей край був безплідною пусткою. Кажуть, що буйне життя пробивається з кожного сліду прадавнього генезавра. Кажуть, що ця істота безсмертна й оновлюється, мов ліс після великої пожежі. Багато оповідають про Тарлну, та насправді про нього відомо й зрозуміло геть мало."},
    [1214] = {n="Зів'якора", d="У глибині пишних лісів Ґорґронда Зів'якора бачив незліченні цикли життя і смерті, тління та відродження. Вискочка «Залізна Орда» й дивні створіння, що з'явилися в її слід, — лише нова шкіра на старому змієві. Скоро їх не стане. А Зів'якора витримає."},
    [1216] = {n="Аззакель", d="На Аргусі — колишній рідній планеті дренеїв, що нині стала твердинею Палаючого Легіону, — Аззакель чекає, готовий до миті, коли слуга Легіону відкриє портал в один із незліченних світів, які вони прагнуть захопити. Поки душезв'язувачка Найямі послаблює оборону Аучіндуна, Аззакель відчуває, що його час близько."},
    [1225] = {n="Терон'ґор", d="Працюючи разом із сарґереями, Терон'ґор, агент Ґул'дана, замислив пожерти безліч душ, схованих за бар'єрами священного мавзолею Аучіндуна."},
    [1226] = {n="Рудоковаль Ґор'ашан", d="Могутній елементаліст із природним хистом надавати форми своїй силі та спрямовувати її крізь метал, Ґор'ашан був частиною авангарду Залізної Орди під час її першого вторгнення в Азерот. Чекаючи на подальші накази, він збавляє час, намагаючись розгадати таємниці рун Темного Заліза, що їх лишили творці Шпиля."},
    [1227] = {n="Кірак", d="Один з останніх уцілілих після збочених дослідів Нефаріана, Кірак був пощаджений Залізною Ордою й дістав завдання знайти способи зберегти та зміцнити кілька яєць чорної зграї драконів, що лишилися в гніздищі Шпиля. Посланці Залізної Орди швидко уклали угоду з хитрим драконом."},
    [1228] = {n="Командир Тарбек", d="Підступний воїн клану Бойової Пісні, Тарбек дістав завдання очолити похідний штурм Залізного Маршу крізь Темний Портал. Дотримуючись настанов Ґарроша, він рушив до домівки орків Чорної Скелі в Азероті, щоб зібрати сили для наступної фази операції."},
    [1229] = {n="Гнівокрил Неприборкана", d="Гнівокрил — велетенський протодракон, вирощений у Сутінковому нагір'ї кланом Драконячої Пащі. Її незламний дух уберіг її від того, щоб бути приборканою й використаною як їздова тварина, проте вона міцно зріднилася із самою полководицею Заелою й рушила за нею до Шпиля Чорної Скелі, оселившись у його печеристих залах."},
    [1234] = {n="Полководиця Заела", d="Коли Ґаррош давав авангарду Залізного Маршу настанови щодо їхньої місії в Азероті, він звелів їм зустрітися зі старою союзницею, яка, він знав, буде люта, віддана й спрагла помсти: із Заелою, полководицею клану Драконячої Пащі. Тепер, готуючи зброю судного дня в серці гори Блекрок, вона наближається до миті своєї відплати."},
    [1235] = {n="Плотероздирач Нок'ґар", d="Цей лютий воєначальник клану Бойової Пісні стрімко піднявся в лавах Залізної Орди й тепер командує батальйоном орків-вояків. Сидячи на спині свого вовка Жахоікла, він наглядає за їхніми навчаннями й приготуваннями, поки вони готуються очолити морський штурм Шаттрата."},
    [1236] = {n="Наглядачі Грімрейлу", d="Наглядачі Грімрейлу — елітні найманці на службі Компанії Блекф'юз, найняті захищати потяги, що ходять крізь Ґорґронд. Трійцю складають мечник Палючого Клинка, інженерка-ґоблінка та шаманка, обізнана в темній магії крові. Єдине, що їх поєднує, — це жадоба та запал до вбивства."},
    [1237] = {n="Ошир", d="Колись дикий хижак, що нишпорив Шпилями Арака, грізний і шанований у своєму прайді, саберон Ошир потрапив у пастку клану Володарів Грому й був приведений до Ґорґронду, щоб його зламали й вишколили як бійця Залізної Орди. Не минає й дня, щоб Ошир не мріяв скуштувати крові своїх поневолювачів."},
    [1238] = {n="Скаллок", d="Могутній ґронн Скаллок — один з найбільших успіхів Залізної Орди в підкоренні велетнів Ґорґронду. Височіючи над військами Ґром'кар і споряджений парою гармат, що почувалися б як удома на будь-якому броненосному військовому кораблі, Скаллок готовий сіяти руйнування за наказом своїх нових господарів."},
    [1262] = {n="Рухмар", d="Рухмар час від часу з'являється як палаючий вогнеяструб, що ширяє в небесах високо над Шпилями Арака. Походження великого птаха невідоме, та аракоа шанують Рухмара як божество, вбачаючи в ньому втілення самого сонця."},
    [1291] = {n="Дров Руйнівник", d="Дрова прозвали Руйнівником клани Чорноскелі давніх часів, які швидко навчилися обходити грізного маґнарона десятою дорогою. Дров лишає по собі смугу спустошення, куди б не ступив, — наче сама земля відчуває його прихід і розступається, прокладаючи йому шлях."},
    [1372] = {n="Ґорфінд", d="Упавши в саме серце мавзолею Аучіндун, лейтенант Тіньової Ради Терон'ґор пожер сотні душ дренеїв і обернувся на роздуту мерзоту. Тепер уже не просто орк, Терон'ґор зрікся свого старого імені й узяв нове: Ґорфінд."},
    [1391] = {n="Лорд Скверни Закуун", d="Дехто з учених Легіону припускає, що лорди Скверни — це вдосконалена версія звичайного вартового Скверни. Вони служать карателями на прямій службі в Архімонда. Їхня жорстокість поступається хіба що їхній грубій силі. Закуунові доручили завдання, яке потребувало обох цих рис однаковою мірою: зламати залізну волю впертого й непокірного орка-вождя клану Бойової Пісні..."},
    [1392] = {n="Кормрок", d="Древній, як сам Дренор, Кормрок колись правив Ґорґрондом, і створіння цих земель тікали від руйнівної люті велетенського маґнарона. Та потім прийшла Залізна Орда, упіймала чудовисько в пастку й спробувала зламати його волю. Усі спроби були марні... аж доки не постав Ґул'дан, і Кормрок не зміг опертися силі Скверни."},
    [1394] = {n="Тиранка Велгарі", d="Коли Ґул'дан приніс свій дар Сарґереям, Велгарі вже ясно виявила свої амбіції й піднялася в лавах з нещадною лютістю. Відома ворогам як Тиранка, Велгарі однією з перших прийняла дотик Скверни, ще більше посиливши свою бойову вправність. Тепер Велгарі носить наругу над священним символом наару, що засвідчує її відданість новому ладу."},
    [1395] = {n="Маннорот", d="Кровожерливий і нещадний, Маннорот був найстрашнішим виконавцем волі Архімонда, доки його не звалив могутній удар сокири Ґроммаша. Та навіть по смерті його кров послугувала Ґул'данові, щоб скріпити темну угоду із Залізною Ордою та її союзниками. Тепер Ґул'дан і його прислужники прагнуть оживити розтрощені рештки Маннорота, щоб той і далі служив Легіону."},
    [1396] = {n="Кілроґґ Дедай", d="Кілроґґ Дедай, воєначальник Кровоточивої Ущелини, перебрав владу над своїм кланом після того, як здійснив ритуал, аби дізнатися про власну смерть. Озброєний цим знанням, він безстрашно вів свій клан незліченними походами, прямуючи до жаданого славного кінця. Тепер, коли його жилами тече демонічна кров, Кілроґґ чекає на тебе в Цитаделі Пекельного Вогню, чекає миті своєї смерті — або твоєї."},
    [1425] = {n="Залізний Спустошувач", d="Креслення Залізного Спустошувача знайшли в майстерні самого Чорнодима після падіння Оґриммара. Натхненний могутніми конструктами Легіону, він мав стати шедевром мерзенного ґобліна. Проєкт завершили вже після його смерті, і він являє собою вершину військової могутності Залізної Орди."},
    [1426] = {n="Пекельний Штурм", d="За допомогою найманців компанії Чорнодима Залізна Орда збудувала спустошливі облогові машини в тіні Цитаделі Пекельного Вогню, щоб згодом обрушити їх на столиці Азероту. Тепер, коли танки переобладнали під енергію Скверни, облоговий майстер Мар'так чекає наказу Ґул'дана, щоб розпочати штурм."},
    [1427] = {n="Сокретар Вічний", d="Душі найвеличніших воїнів дренеїв вкладають у блискучі конструкти, що служать вічними Вартовими на захист свого народу. Колись член Ради екзархів, Сокретар занепав у пітьму й опоганив цей найсвятіший з усіх ритуалів, скориставшись спотвореним конструктом Скверни, щоб зберегти свою душу після поразки в Таладорі."},
    [1432] = {n="Верховна Рада Пекельного Вогню", d="Тисячі орків Залізної Орди прийняли кров Маннорота, та мало хто став таким могутнім, як ці троє поборників. Дія Темнопошепт, володарка магії Порожнечі та вигнанниця клану Тіньового Місяця, швидко піднялася до посади лівої руки Ґул'дана. Ґуртоґґ з його невгамовною жагою крові виходив переможцем із сотень двобоїв. Лише раз він зустрів рівного собі, звівши бій із майстром клинка Джубей'тосом унічию. Уражені хворобою Скверни, вони служать Ґул'данові як Верховна варта і Рада війни."},
    [1433] = {n="Тіньовий лорд Іскар", d="Коли спроби Іскара воскресити Терокка й повернути собі владу завершилися провалом, до нього звернувся Ґул'дан з пропозицією та обіцянкою зняти давнє прокляття Сете. Знову здатний літати, піднесений з тіней, але й досі майстер ілюзій та оману, Іскар нарешті може здійснити свою помсту."},
    [1438] = {n="Архімонд", d="Один із первісних ередарів, що зрадили дренеїв Аргуса, аби посісти місце лиховісної правиці темного титана Саргераса, Архімонд Осквернитель командує військовою могутністю Палаючого Легіону. Він прибуває на Дренор, долаючи простір і час, щоб упевнитися, що вторгнення в Азерот іде за планом, а Ґул'дан не підведе своїх володарів із Легіону."},
    [1447] = {n="Ксул'горак", d="Викликаний Ґул'даном із глибин Викривленої Порожнечі, Ксул'горак — один із найпотужніших примар Порожнечі, раси паразитичних істот Порожнечі, що прориває діри крізь площини реальності, поглинаючи й вбираючи всю енергію та всіх істот усередині. Ґул'дан спотворив Ксул'горака, годуючи його непомірною енергією Скверни й використовуючи його сили, щоб розривати портали, крізь які планує зібрати війська Палаючого Легіону."},
    [1452] = {n="Верховний лорд Каззак", d="Верховний лорд Каззак знову повстав із Викривленої Порожнечі, наглядаючи за діяннями Ґул'дана на благо Палаючого Легіону. Він стоїть біля Трону Кіл'джедена, у самому серці зіпсуття, що спіткало джунглі Танаану."},
    [1467] = {n="Тіратон Салтеріл", d="Колишній союзник Володаря, Тіратон уклав угоду з Легіоном в обмін на більшу могутність. Озлоблений роками ув'язнення, Тіратон прагне завдавати болю й страждань кожному, хто стане йому на шляху. А якщо це виявиться хтось із тих, хто колись тримав його в полоні, то тим краще."},
    [1468] = {n="Аш'ґолм", d="Аш'ґолм був одним із лейтенантів Раґнароса, який лишив жорстокий випалений шрам на лісах Калімдору, перш ніж Вартові нарешті змогли його скувати. Не маючи змоги повністю знищити Аш'ґолма, Вартові ув'язнили його в крижаній темниці. На жаль, недавнє вторгнення Легіону послабило пута, що тримали Аш'ґолма замороженим усі ці роки..."},
    [1469] = {n="Зорій", d="Як і багато демонів цього роду, Зорій здатен зосередити свій погляд у грізну зброю проти ворогів. Вартові виявили, що магічні випромінювання цього створіння можна відбити назад до джерела з нищівним ефектом. Цим знанням вони скористалися, щоб упіймати демона, і змайстрували особливу темницю з дзеркал, аби стримати його силу. Донині."},
    [1470] = {n="Кордана Скверноспів", d="Зрадниця. Перевертень. Вигнанка. Кордана була серед передового загону, що переслідував Ґарроша крізь Темний портал, б'ючись пліч-о-пліч із Хадґаром і протидіючи впливові Ради тіней. Та темне чаклунство Ґул'дана прокралося в її серце, перетворивши її на найвірнішу пішачку чорнокнижника. Колись взірець обов'язку, віднині вона навіки відома як знаряддя погибелі Вартових."},
    [1479] = {n="Серпентрікс", d="Наги, що отаборилися біля Ока Азшари, тримаються на чималій відстані від його північних околиць. У тамтешніх мілинах оселилася прадавня луската звірюка, що раз по раз вистрілює однією зі своїх численних зміїних ший, аби пожерти необачну здобич неподалік."},
    [1480] = {n="Воєначальник Парджеш", d="Цей лютий командир керує військовою міццю наг, що заполонили Азсуну в пошуках Каменя Припливу Ґолґаннета. Серед Зміїв Ненависті він поступається лише Атіссі й здобуває покору рівною мірою страхом і повагою."},
    [1485] = {n="Гімдалл", d="Закутий у сяйливу золоту броню, з могутньою постаттю, наче витесаною з граніту, Гімдалл незмінно пильнує біля брами Залів Доблесті. Один за дорученням Одіна не пускати негідних до Залів, і смертоносні штормові дрейки кружляють поблизу, готові відгукнутися на поклик його рога, він ніколи не схибить у своєму обов'язку."},
    [1486] = {n="Гір'я", d="За життя Гір'я була воїтелькою без рівних, що захищала валькір від усіх загроз. Її звитяга й мужність привернули увагу Еїр, титанічної наглядачки. По її смерті й піднесенні до Залів Доблесті Еїр відзначила Гір'ю найвищою честю — перетворенням на вал'кір."},
    [1487] = {n="Фенрір", d="На Полях Вічного Полювання найвидатніші чемпіони врайкулів гартують свою майстерність, змагаючись, хто здолає найбільшого звіра. Та і люди, і звірі обходять стороною грізного ворга Фенріра, справжнього володаря Полів, що скрадається до здобичі й кидається на неї з лячною прудкістю."},
    [1488] = {n="Бог-Король Сковальд", d="Ґул'дан звернувся до короля врайкулів Сковальда з простою пропозицією: він може приєднатися до Легіону й отримати найвищу могутність, або ж побачить свій народ знищеним. Мріючи про завоювання й славу, Сковальд прийняв пропозицію Легіону, і йому доручили одне-єдине вирішальне завдання. Він мусить здобути Еґіду Аґрамара в Одіна в Залах Доблесті й доставити її Ґул'дану. Лише тоді почнеться його нескінченне завоювання."},
    [1489] = {n="Одін", d="Одін, хранитель-титан, отримав від Пантеону титанів силу вести викувані титанами армії проти Прадавніх Богів. По завершенні цієї боротьби він підняв у небеса Зали Доблесті й зібрав воїнство з найвеличніших чемпіонів-вріколів, щоб боронити Азерот. Та коли Ульдуар потрапив у пазурі Йоґґ-Сарона, Локен зрадив Одіна, а Гелья прокляла його, і тепер він навіки ув'язнений у цих залах."},
    [1490] = {n="Леді Гейткойл", d="Ця морська відьма наґа походить з давнього роду знаті Гейткойлів, що в особливій ласці в самої королеви Азшари. Хвилі й небеса коряться її поклику, адже вона підкорює їхню силу, щоб трощити кожного, хто наважиться стати проти Гейткойлів."},
    [1491] = {n="Король Діпбірд", d="Моряки розповідають про бегемота, що крокує морським дном і вихоплюється з глибин, аби розривати судна голіруч. Кажуть, він носить на плечі цілий ніс корабля, мов наплічник, як трофей. Та більшість слухачів відмахуються від цих оповідей як від дурних побрехеньок, породжених надмірним питвом."},
    [1492] = {n="Гнів Азшари", d="Одна з найвідданіших фрейлін Азшари добровільно віддала себе своїй королеві, щоб стати знаряддям її помсти. Викликаний відчаєними канал-чарівниками Гейткойлів як остання надія після поразки Парджеша, жахливий Гнів Азшари існує лише для того, щоб змести всіх суходільців, які наважаться стати проти неї."},
    [1497] = {n="Іванир", d="Відрізаний від сили Нічного Колодязя й закинутий у темні простори Арквею, Іванир блукав без мети, поволі марніючи, аж доки не натрапив на сховище в підмурках під великою бібліотекою Сурамару. Тепер він день у день гарячково працює над розшифруванням тамтешніх фоліантів, живлячись силою реліквій з архівів, щоб підтримувати своє існування. Та хоч ця магія й живить його тіло, розум його тріщить і слабшає."},
    [1498] = {n="Корстилакс", d="Цей велетенський конструкт патрулює тунелі під Сурамаром, вишукуючи аномалії та виправляючи їх. Він виявив одну таку аномалію - пролом в одному з каналів, що несуть силу Нічного Колодязя, - і працює над її усуненням. Але живі чужинці, що блукають тунелями, теж аномалія, яку Корстилакс уповноважений усунути."},
    [1499] = {n="Генерал Ксакал", d="Коли Ґул'дан погрожував знищити Сурамар, якщо Елісанда не скориться його вимогам, це не були порожні слова. Загарбницьке воїнство Легіону прорилося до тунелів під містом, і Ксакал очолює ці сили. Він чекає дальших наказів, готовий будь-якої миті ринути вперед і принести смерть і руїну на вулиці Сурамару."},
    [1500] = {n="Нал'тіра", d="Ця величезна павучиха звила гніздо в порожнині під великим манадеревом. З роками вільні магічні енергії та їхні витоки спотворили створіння, наповнивши Нал'тіру арканною енергією, що робить її чи не найсмертоноснішою хижачкою в Арквеї."},
    [1501] = {n="Радник Вандрос", d="Вандрос - один з найближчих радників Елісанди й майстер у володінні арканною магією Нічного Колодязя, поступаючись хіба що самій Елісанді. Зазвичай він не наважився б сам спускатися в Арквей, та, поспостерігавши за станом спротиву нічнепалих та їхніх союзників, тепер відчуває потребу взяти справу у власні руки."},
    [1502] = {n="Імірон, Полеглий Король", d="Імірон, колишній король вріколів Нортренду, був могутнім воїном, якого з трепетом шанував його народ. У потойбіччі на нього чекали відчинені брами Залів Доблесті. Та, спраглий більшої влади, він уклав темну угоду з Король-Лічем. А коли мандрівники здолали його, вічні Зали виявилися для нього зачиненими. І відтоді проклятий король чекає в чистилищі на берегах Пащі Душ."},
    [1512] = {n="Гарбарон", d="Загадковий перевізник душ стоїть біля стерна Наґльфара, збираючи проклятих і доправляючи їх у володіння Гельї. Його справжній зв'язок із полеглою королевою валькір залишається нез'ясованим, але коли вітерець підхоплює плащ Гарбарона, під ним відкривається обшир мерехтливих зір. Дуже дивно."},
    [1518] = {n="Амальгама душ", d="Величезна сила душ вивільнилася, коли Ґул'дан провів ритуал, аби відділити душу Іллідана від його тіла у Цитаделі Воронячого Гнізда. Ця енергія повернула душі клану Воронячого Гнізда до їхньої прадавньої домівки, а залишкова сила душ злила їх в одну величезну потвору."},
