    [1637] = {n="Полум'яний Левіафан", d="Цей величезний броньований танк охороняє вхід до двору в Ульдуарі. Вартовий Мімірон збудував Полум'яного Левіафана як частину своєї зброярської платформи В-07-ТР-0Н."},
    [1638] = {n="Іґніс Майстер Горнила", d="Як і інші витворені титанами створіння Ульдуару, Іґніс тепер служить спотвореній волі Прадавнього Бога Йоґґ-Сарона. Цей грізний вогняний велетень трудиться біля Колосальної Кузні, куючи залізні армії, що завоюють Азерот в ім'я Йоґґ-Сарона."},
    [1639] = {n="Лезолуска", d="Веранус, праматір виводку протодраконів Грозових Вершин, служила хранителю Торіму, доки Локен не полонив її та не перетворив на люте знаряддя. За наказом свого володаря Іґніс Майстер Горнила вкрив шкуру Лезолуски залізними пластинами, щоб посилити її смертоносні удари."},
    [1640] = {n="Деконструктор XT-002", d="Створений патрулювати звалище Ульдуару, XT-002 отримав від Мімірона примітивний розум, достатній для його обов'язків. Згодом XT-002 почав вважати себе сином хранителя й часто влаштовує істерики, наче вередлива дитина."},
    [1641] = {n="Зібрання Заліза", d="Залізними легіонами Локена командують троє грізних воєначальників, кожен з яких уособлює інший витворений титанами народ. Грозовісник Брундір, Рунний майстер Молґейм і велетень Сталелам б'ються в ім'я істинного володаря хранителя — лиховісного Йоґґ-Сарона."},
    [1642] = {n="Колоґарн", d="Локен наказав Іґнісу Майстру Горнила створити цього величезного велетня, щоб охороняти Розтрощений Прохід. Своїми могутніми руками Колоґарн стирає на порох будь-якого зайду, що намагається дістатися внутрішнього святилища."},
    [1643] = {n="Авріая", d="Архіваріуска Ульдуару патрулює Кільце Спостереження в супроводі лютих котів. Роки самотності тяжко позначилися на Авріаї, а зростаюча міць Прадавнього Бога, схоже, знищила останні крихти її глузду."},
    [1644] = {n="Годір", d="Велетень Годір колись очолював Храм Зими, наставляючи крижаних велетнів Грозових Вершин. Тепер хранитель мешкає в крижаній печері в Залах Зими, змушений коритися волі Йоґґ-Сарона."},
    [1645] = {n="Торім", d="Багато років Торім вірив, що крижані велетні вбили його кохану дружину Сіф. Торім обрушив свій гнів на власних союзників і впав у відчай. Коли він дізнався, що за цей злочин відповідальний його брат Локен, той полонив Торіма й привів до Ульдуару, де Прадавній Бог затьмарив розум хранителя."},
    [1646] = {n="Фрея", d="Хранителька Фрея була захисницею всього живого, і допомагали їй троє незворушних старійшин. Хоч її оранжерея й досі пишна та квітуча, вона теж піддалася божевільному шепоту Прадавнього Бога."},
    [1647] = {n="Мімірон", d="Геніальний винахідник Мімірон упродовж історії Азероту створив безліч механізмів, що викликали захват і подив. Та відколи він підпав під збочений вплив Локена, цей хранитель Ульдуару будує лише машини війни та руйнування."},
    [1648] = {n="Генерал Везакс", d="Дивні створіння, відомі як безликі, чаяться в глибинах Ульдуару. Один із їхніх наймогутніших командирів, генерал Везакс, охороняє покручені проходи, що ведуть до В'язниці Йоґґ-Сарона."},
    [1649] = {n="Йоґґ-Сарон", d="Ясний сон. Чудовисько з твоїх кошмарів. Лиходій тисячі облич.\n\nУсі мусять скоритися волі володаря. Ваші дріб'язкові чвари лише роблять його сильнішим."},
    [1650] = {n="Алґалон Спостерігач", d="Смерть Локена надіслала пантеону титанів попередження про те, що Азерот втратив свого Головного Призначеного. Алґалона Спостерігача відрядили оцінити, чи присутнє системне зіпсуття. За потреби констеляр запустить переродження цілого світу, стерши всіх його нинішніх мешканців."},
    [1651] = {n="Оніксія"},
    [1652] = {n="Геліон"},
    [1653] = {n="Іллісанна Рейвенкрест", d="Донька лорда Рейвенкреста, ув'язнена на тисячоліття у Сховищі Вартових невдовзі після Війни Прадавніх, здобула волю після того, як Майєв звільнила мисливців на демонів з їхньої в'язниці. Повернувшись до рідної домівки предків, вона пожертвувала всім — навіть власною душею, — аби захистити те, що не змогла вберегти під час Війни Прадавніх."},
    [1654] = {n="Архідруїд Ґлайдаліс", d="Колись Ґлайдаліс уславився як один із найталановитіших перевертнів у всьому Азероті, і старійшини Місячної галявини регулярно відсилали до нього найперспективніших учнів на навчання. Та, як надто часто й бувало, ті, хто найближчий до природи, нерідко першими потрапляють у пазурі Жахіття."},
    [1655] = {n="Дубосерд", d="Прадавень, що постав із паростка самого Шаладрассіла, Дубосерд пережив Розкол, Катаклізм і незліченні моровиці. Прадавень зміг устояти перед цими бурями, черпаючи силу з есенції самого Сну. Та нині це джерело стало його погибеллю."},
    [1656] = {n="Дресарон", d="Колись юний зелений дракон, що піклувався про драконенят у затінку великого Світового Дерева, Дресарон нині поглинутий жахіттям, загублений у тумані ненависті й страху. Він б'є могутніми крилами та згубним подихом, виливаючи свою лють на кожного, хто втрапить йому в пазурі."},
    [1657] = {n="Тінь Ксавія", d="Колись могутній маг і радник королеви Азшари, Ксавій уклав угоду із Саргерасом, аби уможливити перше вторгнення Легіону в Азерот. Проклятий і змучений після тієї поразки, Ксавій тепер проєктує свою справжню силу з Жахіття в наш світ, спрямовуючи свою темну міць на те, щоб зламати дух свого давнього суперника Малфуріона."},
    [1662] = {n="Рокмора", d="Незавершений шедевр Уларогга Каменетворця — Рокмора, велетенська кристалічна лють, створена, щоб знищити всіх, хто повстане проти Підземного короля. Дика магія, використана для створення цього бегемота, ще не вгамувалася, тож кожен уламок Рокмори, приєднаний чи ні, просякнутий лиховісною волею Уларогга трощити своїх ворогів."},
    [1663] = {n="Гелья", d="Гелья, занепала королева вал'кір, колись була правицею Одіна: вона підносила духи вікульських звитяжців до Залів Доблесті, щоб готувати їх до останньої битви за долю Азероту. Та після зради Локена її переконали приєднатися до нього й обернутися проти свого володаря. Тепер вона ховається в тінистому царстві під світом і плете свою помсту."},
    [1664] = {n="Смешспайт Ненависний", d="Жорстокий і грізний лейтенант мо'аргів, Смешспайт Ненависний очолив вторгнення Легіону до Твердині Чорного Граку й керував обороною фортеці з повітря завдяки своїй колонії сквернокажанів."},
    [1665] = {n="Уларогг Каменетворець", d="Уларогг Каменетворець — стародавній дроґбар, що присвятив своє життя гонитві за владою. Насильством і підступом Уларогг піднісся до довіреного радника Підземного короля. Він зневажає Навароґґа за те, що той привів «зайд» до їхньої домівки, і з насолодою прирече їх на криваву загибель."},
    [1667] = {n="Урсок", d="Урсок — один з Диких Богів. Покровитель фурболгів, тісно пов'язаний з друїдською силою перевтілення, стародавній великий ведмідь віддавна був захисником Азероту. Та поки Урсок дрімав у своєму святилищі в Ґризлійських пагорбах, світ навколо нього занурився у скверну, і прокинувся він уже в муках і кошмарі, що пожирав і спотворював його єство."},
    [1672] = {n="Лорд Кур'талос Рейвенкрест", d="Кур'талос Рейвенкрест, лорд Твердині Чорного Граку, був командувачем Опору Кальдорай під час Війни Стародавніх, доки його не вбив Варо'тен за наказом королеви Азшари. Тисячоліття по тому мерзенна магія душ Ґул'дана пробудила душу Рейвенкреста та душі його предків від вічного спокою. Легіон, прагнучи помсти, з радістю втиснув його душу назад у тіло й зачарував його, змусивши вічно переживати жахіття Війни Стародавніх."},
    [1673] = {n="Нараксас", d="Нараксас, мати чудовиськ, якій дроґбари поклоняються ще з Епохи Нелтаріона. Цій істоті безперестанку приносять жертви, щоб вона вигодовувала покоління жахіть, які дроґбари кидають проти своїх ворогів. Так чи інакше, ти мусиш пройти повз цю звірюку й завдати удару Підземному королю, доки цей жах не вирвався на Високогір'я."},
    [1686] = {n="Розумоїд Каар'дж", d="Цю моторошну істоту схопили в глибинах Улдуару, коли вона після поразки Йоґґ-Сарона впала в заціпеніння. Та відколи Даларан прибув до Зламаних островів, потвора загадково пробудилася, і лише потужні обереги Багряної Темниці стримують її сили."},
    [1687] = {n="Дарґрул Підземний король", d="Дарґрул — наймогутніший Підземний король з часів Епохи Нелтаріона. Переконаний, що лише він має право володіти силою Каз'ґорота, Дарґрул убив верховного вождя Улана й відібрав артефакт у тавренів Високогір'я. Тепер він використовує силу Молота, щоб спустошувати край і всіх, хто йому опирається."},
    [1688] = {n="Мілліфісент Манашторм", d="Інженерний геній з безперечним хистом, Мілліфісент Манашторм — повна протилежність свого чоловіка Мілгауса. Розумна й кмітлива, вона — сила, з якою варто рахуватися."},
    [1693] = {n="Фестерфейс", d="Коли впала цитадель Крижаної Корони, безліч дослідів професора Путрицида було вилучено. Найімовірніше, Фестерфейс — це невдалий прототип, що з'явився ще до того, як професор створив два свої найвідоміші витвори: Ротфейса й Фестерґута."},
    [1694] = {n="Шивермо", d="Подейкують, що цей грізний крижаний вирм — один із поріддя самої Синдрагоси. Його захопили в Залах Крижаного Крила цитаделі Крижаної Корони, де війська Короля-Ліча трудилися над створенням цих крилатих почвар."},
    [1695] = {n="Інквізитор Торменторум", d="З-поміж усіх мерзенних створінь на службі Легіону каптурні інквізитори, мабуть, найзагадковіші й найзловісніші. Торменторум прибув після першого нападу на сховище. Коли він блукає залами Сховища, а його погляд протинає тіні в пошуках якоїсь важливої таємниці, навіть інші демони обходять його стороною."},
    [1696] = {n="Ануб'ессет", d="Ануб'ессет, один із небагатьох уцілілих стародавніх нерубських володарів склепів, був схоплений Кірін-Тором під час вторгнення в цитадель Крижаної Корони й ув'язнений у Фіолетовій Фортеці. Звільнений під час навали Легіону, він думає лише про помсту живим."},
    [1697] = {n="Сель'орн", d="Походження цих павукоподібних демонів до кінця не з'ясоване — учені, що вивчали Легіон, припускають, що це рештки забутого народу зі світу, давним-давно завойованого арміями Саргераса. Сель'орн — особливо лютий представник цього народу, якому доручили очолити проникнення в Даларан."},
    [1702] = {n="Кривава принцеса Тал'ена", d="Кривава принцеса Тал'ена — донька могутньої королеви сан'лейн Лана'тель. Вона була ув'язнена у Фіолетовій Фортеці ще від часів кампанії в Нортренді й потерпала від гнітючого болю свого вічного голоду. Тепер, коли двері її камери відчинилися, вона має намір живитися всім світом."},
    [1703] = {n="Нітендра", d="Колись Нітендра належала до зеленої зграї драконів, яким доручили охороняти світове дерево Шаладрассіл. Коли скверна Кошмару, насланого Ксавієм, поглинула Шаладрассіл, вона поглинула й сплячу вартову. Тепер Нітендра — це лише кістяк колишньої себе, оповитий пошестю, готовий пожерти кожного, хто буде досить нерозсудливим, щоб увійти до її лігва."},
    [1704] = {n="Дракони Кошмару", d="Смарагдовий Сон було довірено Ісері, а наймогутніших драконів її зеленого поріддя поставили вартувати чотири портали, що вели прямо до Азероту. Та ще до Катаклізму ці дракони почали виявляти ознаки скверни. Тепер шлях до осердя Кошмару пролягає через лігво драконів."},
    [1706] = {n="Скорпірон", d="Глибоко в підмурках Нічної Фортеці, попід морем, лежать давно забуті склепіння, що дають доступ до самого Нічного Колодязя. У одному з цих склепінь оселився цей жахливий броньований скорпід. Сповнений сили Нічного Колодязя й оточений численним поріддям, Скорпірон стає серйозною завадою на шляху через інакше зручний таємний вхід до Нічної Фортеці."},
    [1711] = {n="Лорд Скверни Бетруґ", d="Цей безжальний командир Легіону готовий очолити вторгнення в Даларан зсередини його стін."},
    [1713] = {n="Кросус", d="Цей колосальний володар погибелі, одне з найбільших і наймогутніших створінь у військах Легіону, був повалений на Зламаному березі завдяки об'єднаній силі найвеличніших героїв Орди та Альянсу. Оговтавшись від ран, Кросус виринає із затоки між Нічною твердинею та Гробницею Сарґераса, щоб розчавити кожного, хто посміє стати на шляху Легіону."},
    [1718] = {n="Капітан патруля Ґердо", d="Капітан Сутінкової варти Ґердо присвятив своє життя збереженню миру в мурах Сурамару. Хоча від часу появи Легіону його дедалі більше непокоїть тривога, він лишається вірним і відданим правителям Сурамару. Елісанда оберігала їх упродовж поколінь, і вона знає, що найкраще для мешканців міста. Цієї ночі завдання Ґердо - подбати, щоб лише громадяни з належними дозволами могли потрапити на надзвичайно важливе зібрання в маєтку."},
    [1719] = {n="Таліксе Полуменевінок", d="Садистична чаклунка-ередар, Таліксе чудово розуміє вагу нічнонароджених для планів свого володаря, та все ж її обурює приниження - стояти на варті біля будівлі, повної ельфів. Попри це вона та її лейтенанти лишаються пильними, і доки вони живі, жоден чужинець не порушить зібрання."},
    [1720] = {n="Радник Меландрус", d="Перший Клинок Великої магістрикс, Меландрус рідко відходить від Елісанди. Він зрікся магічних мистецтв, натомість використавши силу Нічного джерела, щоб загострити свої рефлекси та рухи до нелюдського рівня."},
    [1725] = {n="Хрономатична аномалія", d="Печера біля підніжжя Нічного джерела - це вир чистої енергії, адже з-під землі струменить сила, здатна живити цілу цивілізацію. Народжена з цього хаотичного потоку, Хрономатична аномалія є втіленням могутності Ока Аман'тула. Коли вона завдає ударів енергетичними атаками, спалахи енергії викривлюють самий плин часу."},
    [1726] = {n="Ксавій", d="Колись могутній маг і радник королеви Азшари, Ксавій уклав угоду із Сарґерасом, щоб уможливити перше вторгнення Легіону в Азерот. Проклятий і змучений після тієї поразки, Ксавій плекає помсту світові з глибин Розлому Альну. Ті, хто наважиться ступити в Жахіття, зіткнуться з усією повнотою його сили та його справжньою подобою - гротескною і роздутою потворою."},
    [1731] = {n="Трилліакс", d="Трилліакс, колись гордий слуга аристократії нічнонароджених, був викинутий і покинутий повільно занепадати серед інших зайвих конструктів. Хоча незламна воля виконувати свої завдання лишилася, плин часу розколов матрицю особистості цього конструкта. Тепер він непередбачувано перемикається з одного режиму на інший - від дбайливого опікуна до кровожерливого стерилізатора, прагнучи визнання та схвалення від володаря, якого більше не існує."},
    [1732] = {n="Зоряний провісник Етрей", d="Астромант нічнонароджених Етрей присвятив довгі роки досліджень вивченню небес Азерота, шукаючи відповіді на великі таємниці всесвіту. Його віщування показали йому світи поза нашим розумінням, а сила Нічного джерела дозволяє йому черпати з есенції тих світів, аби примножувати власну могутність."},
    [1737] = {n="Ґул'дан", d="Низка подій, запущена втечею Ґарроша на Дренор, тривала, не уриваючись попри всі повороти й вигини, і привела до цієї самої миті. Зазнавши поразки на Дренорі, Ґул'дан тепер стоїть на порозі остаточної перемоги в ім'я своїх володарів із Легіону. Стоячи на вершині Нічної твердині, під вихором енергії Скверни, що кружляє в небі вгорі, вигнаний орк-чорнокнижник чекає на свою долю."},
    [1738] = {n="Іл'ґінот, Серце Зіпсуття", d="Угніздившись у порожнинах нині спорохнявілого світового дерева, Іл'ґінот є проявом жахіть, що криються в серці Жахіття. Це маса зіпсуття - те, чого не повинно існувати. Його щупальця просочуються крізь землю, виринаючи незліченними моторошними очними стеблами та кінцівками."},
    [1743] = {n="Велика Магістрикс Елісанда", d="Колись Елісанда уславилася тим, що чинила опір Легіону. Вона та її високорідні послідовники відкололися від королеви Азшари й темного шляху, яким та йшла, і скористалися силою Ока Аман'тула, щоб створити Нічний Колодязь і вберегти Сурамар від Розколу. Та понад десять тисяч років по тому прихід Легіону не лишив їй такого порятунку. Вона стала на бік демонів, сподіваючись знову застосувати силу Нічного Колодязя - хай і цього разу зовсім інакше - аби врятувати свій народ."},
    [1744] = {n="Елерете Ренферал", d="Елерете, колись могутня друїдка й майстерна перевертниця, стала на темний шлях через переконання, що її зрадили найближчі союзники. Тепер її свідомість перебуває в Жахітті, прирікаючи її на існування, сповнене страху, сум'яття й ненависті."},
    [1749] = {n="Нітоґґ", d="Великий дракон Нітоґґ колись належав до торіґнірів, але покинув виводок невдовзі після того, як той присягнув на вірність титанічним хранителям. Нітоґґ вірив, що одного дня стане могутнішим навіть за хранителів, і відмовився бути їхнім підданим. Натомість він оселився на горі Настрондір, де вирощує свій виводок і тероризує сусідні землі, щойно йому заманеться."},
    [1750] = {n="Кенарій", d="Напівбог Кенарій - батько друїзму на Азероті й один із найдавніших і наймогутніших захисників світу. Його тривожний сон у гаях Вал'шари став першою ознакою глибини зростаючої загрози з боку Жахіття. Тепер та темна сила повністю заволоділа ним, і він, можливо, лежить поза межами надії на спасіння."},
    [1751] = {n="Чароклинок Аларіель", d="Аларіель завжди мала хист до магії. Вона легко піднялася в лавах Нічної варти, маючи природний талант до меча. Та хай якою сильною ставала, вона прагнула більшого. Вона навчалася в магів Університету Сурамара, проводячи дні в бойових тренуваннях, а вечори - в майстерні. Вона викувала свою зброю та обладунки в Нічному Колодязі, вплітаючи магічні чари в коштовні метали. Вона перша Чароклинок, обізнана в школах Вогню, Льоду й Аркани."},
    [1756] = {n="Викрадачі Душ", d="Послане Гельєю грабувати крипти шляхетних королів вриколів, це тріо нальотчиків зі своєю командою пробралося до Гробниці Прадавніх Королів і прагне заволодіти душами, що там спочивають."},
    [1761] = {n="Великий Ботанік Тел'арн", d="Змалечку нічнороджений Тел'арн був зачарований світом рослин: витривалістю й пристосовністю бур'янів, здатністю простої трави вбирати силу сонця, тим, як дерево можна розділити надвоє, а дві гілки зростити в одну. За допомогою енергій Нічного Колодязя він перетворив себе настільки, що його заледве можна впізнати як нічнородженого ельфа. Тепер він вважає себе чимось значно, значно вищим."},
    [1762] = {n="Тихондрій", d="Жахолорд Тихондрій, колись очільник натрезімів, був свого часу вбитий новопробудженою силою не кого іншого, як Іллідана Стормрейджа. Відтворений у Викривленому Нижньому світі, Тихондрій повертається, щоб наглядати за Ґул'даном від імені Легіону й пильнувати, аби орк-чорнокнижник знову не підвів своїх володарів."},
    [1763] = {n="Шар'тос", d="Цього вартового галявин охопила скверна Жахіття. Там, де колись він вдихав життя в ліси, тепер він лишає по собі слід тліну й руйнування."},
    [1764] = {n="Шаховий двобій"},
    [1769] = {n="Левантус", d="Її безодній сон було потривожено, і Левантус піднялася на поверхню, де виявила острови, що кишать дивними демонами. Магія Скверни, яка просочується в навколишні води, лишила її вкрай лютою та дратівливою."},
    [1770] = {n="Гумонгріс", d="Гумонгріс завжди мріяв володіти магією. Виявивши, що не має хисту до арканних мистецтв, Гумонгріс натомість удовольнився тим, що володіє чарівником. Він вистежив і захопив мага Падавсена, а тепер тримає його, наче чарівну паличку, погрозами та дедалі міцнішою хваткою змушуючи розсипати магію по полю бою."},
    [1774] = {n="Каламір", d="Істота незмірної магічної сили, Каламір був призваний прадавніми взірцями в їхній несамовитій люті. Наділений могутністю Вогню, Льоду й Аркани, Каламір знищує всіх, хто наважиться стати йому на шляху."},
    [1783] = {n="На'зак Нелюд", d="Альфа фал'дореїв, ця жахлива потвора чаїться глибоко в тунелях Фаланаару. Перериваючи каміння, він відкопує насичене лей-енергією каміння та живиться його арканною силою, аби підтримувати себе, вичікуючи на гіднішу здобич."},
    [1789] = {n="Друґон Морозокровний", d="Друґон Морозокровний з височіні своїх крижаних вершин уже багато віків тероризує племена Високогір'я. Тепер, побачивши нагоду в хаосі, цей могутній еттін спускається зі свого сідала, щоб заявити права на цей край."},
    [1790] = {n="Ана-Мауз", d="Ця мерзенна мати бісенят спочиває глибоко в Бастіоні Скверни душ, занурена в озеро чистої енергії Скверни. Її діти роями кружляють довкола, а вона вдихає смердюче повітря й опоганює все, що потрапляє їй до рук."},
    [1795] = {n="Уламки", d="Уламки виринули з океанських глибин, аби втамувати свій голод. Першими на їхньому шляху трапилися болотні мурлоки бухти Корабельної Аварії, яких Уламки пожерли десятками. Хоча більшу частину свого племені вони втратили, ці створіння шанували велетня як бога й далі годували його родичами та друзями, доки звір не знесилився й не заснув. Коли він прокинеться, Уламки розширять своє меню до кожного мешканця цього краю."},
    [1796] = {n="Зів'ялий Джім", d="Вигнаний зі святилища Сурамару, цей нічвалий блукав узбережжям, а його тіло занепадало, а разом із ним і розум. Саме тоді, коли він був готовий утратити останні рештки своєї особистості, він відчув, як із сусідньої печери струмує енергія. Усередині він знайшов уламок сили, що походив із самого Колодязя Ночі. Той живить і підсилює його, але водночас викривлює плин часу й простору поблизу. Він остаточно зламав його розум. Тепер ніхто не заходить до печери Зів'ялого Джима. Навіть дурні знають, чим це загрожує."},
    [1817] = {n="Тінь Медіва", d="Така велика була сила Останнього Вартового, Медіва, що його магія досі відлунює в залах Каражану. Деякі з цих відлунь набувають вигляду видінь, відкриваючи гостям вежі минулі події. Інші ж прибирають лиховісніших форм, нагадуючи про час, коли воля Вартового належала не йому."},
    [1818] = {n="Пожирач мани", d="Рідко коли вигляд манавирма викликає тривогу в досвідченого шукача пригод. Ці дрібні, прості створіння ширяють довкола, поглинаючи розкидані згустки арканної енергії. Та в Каражані все часто навпаки, і те, що на перший погляд здається безневинним, може виявитися величезною загрозою."},
    [1819] = {n="Одін", d="У давні віки Одін вів титанороджені армії на битву проти Чорної Імперії Прадавніх Богів. Та вже тисячоліттями він прикутий до Залів Доблесті прокляттям своєї запеклої супротивниці Гелья. Одін шукає смертних поборників, які знищать правительку Гельгейму й здобудуть йому свободу."},
    [1820] = {n="Оперна зала: Віккет", d="Лиходії народжуються злими чи скочуються в злодійство під чужим впливом? Можливо, погляд на цю загадку очима гозенів подарує просвітлення..."},
    [1825] = {n="Діва Чесноти", d="Прибувши в Каразан, щоб очистити вежу від пороку й розпусти, наглядачка-титан розлютилася через сумнозвісні бенкети й гульбища Медіва. У своєму хрестовому поході за чесноту вона шукає прихильників, а сама Діва незмінно віддана викоріненню розпусти всіма доступними їй силами."},
    [1826] = {n="Оперна зала: Вествольська історія", d="Серед різанини ворожих банд, що б'ються за владу над Вествольдом, двоє закоханих із зовсім різних світів борються за щастя. Кажуть, кохання сліпе... та чи не потрібен йому ще й перекладач?"},
    [1827] = {n="Оперна зала: Прекрасна Бестія", d="Проклятий жити в подобі звіроподібного чудовиська, Брут мусить знайти справжнє кохання, перш ніж темна магія, що його перетворила, забере йому життя. Чи опанує він гарні манери за столом вчасно, щоб завоювати серце прекрасної Белли?"},
    [1829] = {n="Гелья", d="Хоч колись вона служила Одіну правою рукою, мстива Гелья не спиниться ні перед чим, аби її прадавнє прокляття навіки тримало хранителя-титана в Залах Доблесті. Уже не вдовольняючись владою над своїм тіньовим царством, Гелья тепер посилає свою величезну армію квалдірів, щоб тероризувати землі живих."},
    [1830] = {n="Ґуарм", d="Лютий триголовий пес Гелья стереже брами Гельгейму. Вирощений так, що не потребує ні спокою, ні сну, Ґуарм завжди пильнує загарбників, які приходять кинути виклик владі його жорстокої володарки."},
    [1835] = {n="Аттумен Мисливець", d="Колись на нього поклали полювання на дичину для бенкетів його господаря, та нині Аттумен націлився на зовсім іншу здобич. Завжди насторожі проти тих, хто хоче викрасти його славного скакуна Опівніч, Аттумен пускає в хід відточену бойову вправність проти всіх зайд."},
    [1836] = {n="Куратор", d="Куратор охороняє Звіринець від непроханих гостей, знищуючи порушників, що прагнуть розграбувати таємниці Каразану. Хоч його зібрав сам Медів, конструкт-вартовий із часом занепав і став схильним до перевантажень енергією та непередбачуваної поведінки."},
    [1837] = {n="Мороес", d="Мороес, управитель Каразану, дбає про званих гостей свого господаря у величній Бенкетній залі. Навіки відданий турботі про вежу, він із жорстокою спритністю спроваджує нечемних непроханих гостей."},
    [1838] = {n="Віз'адуум Спостерігач", d="Всевидющому Віз'адууму Кіл'джеден наказав захопити Каражан і черпати енергію з ниток лей-ліній, що пронизують вежу. Якщо йому вдасться прив'язати споруду до незліченних світів, підвладних Легіону, армія Темного Титана накриє Азерот і лишить від нього хіба що тліючу пустку."},
    [1856] = {n="Гарджатан", d="Гарджатана від народження вчили нищити ворогів. У походах дикунської жорстокості він зібрав довкола себе юрми печерних мурлоків, які бачать у ньому бога. Тепер наґа-здоровань мусить лише гарикнути наказ — і полчища відданих послідовників беруться до справи."},
    [1861] = {n="Володарка Сассз'іне", d="Володарка Сассз'іне все життя підкоряла мешканців океану своїй темній волі. Цією силою вона прикликає жахіття із солоних глибин, щоб змити кожного, хто наважиться кинути їй виклик."},
    [1862] = {n="Ґорот", d="Як кару за минулі поразки, плоть Ґорота посічена пекучими ранами. З кожним рухом цього велета тіло його тріщить і шипить від нескінченних мук — страждання, яке він радо завдає тим, хто стає йому на шляху."},
    [1867] = {n="Демонічна інквізиція", d="Передбачаючи прихід смертних сил, що вдираються до Гробниці Саргераса, Кіл'джеден прикликав двох найкращих своїх тюремників, Атрігана й Белака, щоб ті скували непроханих гостей і не дали їм скористатися Стовпами для проникнення глибше в підземелля."},
    [1873] = {n="Полеглий Аватар", d="Коли Еґвінн здолала Аватара Саргераса, вона не змогла знищити його повністю. Щоб запечатати його, обладунок поховали під Храмом Елуни, де він дрімав упродовж сотень років. Тепер, коли Легіон руйнує бар'єри гробниці, Кіл'джеден здатен оживити обладунок і вивільнити його міць на Азерот."},
    [1878] = {n="Мефістрот", d="Мефістрот керує вторгненням Легіону з Розбитого узбережжя. Коли сили Азерота тиснуть на його передову, Мефістрот відступив до Собору Вічної Ночі, де пустить у хід усю свою хитрість, аби герої не змогли заволодіти Егідою Аґрамара."},
    [1883] = {n="Бруталлус", d="Володар безодні Бруталлус — ветеран багатьох битв, зокрема й нещодавнього бою біля Сонячного Колодязя. Його тактика рідко буває витонченою: він покладається на саму лише грубу силу, щоб трощити ворожі армії."},
    [1884] = {n="Маліфікус", d="Маліфікус — створіння чистої злоби, що вселяє жах у серця всіх, хто стає йому на шляху. Передвістям його приходу слугують масові паніки серед мешканців і культи смерті, що святкують кінець світу."},
    [1885] = {n="Сі'ваш", d="Сі'ваш повеліває люттю моря, обрушуючи його міць на тих, хто підходить надто близько до берега. Її завзята почесна варта сі'ваші мандрує разом з нею океанами Азерота, прагнучи знайти беззахисні гавані для руйнування."},
    [1896] = {n="Спустошений Хазяїн", d="Колись це місце було священним похованням нічних ельфів, але Легіон спотворив ці землі Машиною Душ. Ця мерзенна споруда живиться енергією мертвих, перетворюючи їх на потвор. Через цю скверну змучені духи стали чудовиськами, що прагнуть пожерти кожного, хто спуститься в глибини гробниці."},
    [1897] = {n="Діва Пильності", d="Покликана Еґвінн боронити Гробницю Саргераса, Діва Пильності стояла на чатах сотні років. Та охоронниця не передбачила, який вплив матиме скверна, що сочиться з аватара, на цей титанічний витвір. Поступово зіпсована цією злобою, Діва тепер прагне знищити всіх на своєму шляху."},
    [1898] = {n="Кіл'джеден", d="Відколи уклав угоду, що погнала дренеїв до зірок, Кіл'джеден вірив, що Легіон не спинити. Та жодна з його підступностей не завадила тобі дійти до цієї вирішальної миті. Розлючений тим, що обіцяна Саргерасом перемога так і не настала, повелитель демонів готується сам стати проти тебе в останній битві, яка навіки визначить долю Азероту."},
    [1903] = {n="Сестри Місяця", d="Сестри Місяця слугували вартовими храму задовго до того, як аватара Саргераса поховали під ним. Навіть у смерті сестри несли свою варту, але за тисячоліття щось спотворило їхню здатність відрізняти друга від ворога. Безум поволі поглинув їх, і тепер кожного, хто входить до їхніх священних покоїв, спіткає смерть."},
    [1904] = {n="Доматракс", d="Тепер, коли Еґіда Аґрамара знову встановлена у своє ложе, Доматракс веде навалу демонів, щоб знищити реліквію."},
    [1905] = {n="Агронокс", d="Цей прадавень слугував жрицям нічних ельфів храму Елуни, доглядаючи прекрасні Висячі Сади. Та коли злоба Легіону заразила собор, охоронець увібрав скверну крізь своє коріння. Тепер спотворений Агронокс ширить скверну по святилищу, яке колись захищав, гадаючи, що нарешті досягнув свого ідеального стану."},
    [1906] = {n="Молотозуб Зневажливий", d="Молотозуб, огидний брат Трощешипа, був посланий винищити смертних, що входять до величної бібліотеки собору. Тупоголовий мо'арґ не має жодної поваги до знань чи науки й тішиться дріб'язковим задоволенням, трощачи прадавні артефакти й топчучи безцінні фоліанти."},
    [1956] = {n="Апокрон", d="Збудований Легіоном тисячі років тому, Апокрон віщував кінець незліченним цивілізаціям. З кожним підкореним світом міць цього губителя зростає, прирікаючи наступне царство на спалення."},
    [1979] = {n="Зураал Піднесений", d="Зураал — перший успіх Тіньової варти у створенні насиченого Порожнечею Зламаного, чий розум не впав у безум. Уславлений боєць у минулому житті, Зураал використовує свою нову темну силу, щоб підсилити свої атаки й нищити ворогів."},
    [1980] = {n="Сапріш", d="Завжди тактичний Сапріш розгортає сили Тіньової варти з вивіреною точністю. Хоч він і вмілий командир та стратег, Сапріш насолоджується тим, що сам бере участь у бою. Він обертає слабкості ворогів проти них самих, лишаючи беззахисних супротивників на поталу своїм ненажерливим улюбленцям."},
    [1981] = {n="Віцекороль Нежар", d="Як і інші його роду, Віцекороль Нежар одержимий жадобою опанувати силу Порожнечі задля власних амбіцій. Приваблений до Престолу Тріумвірату незмірною темрявою, що струмує з його глибин, Нежар не зупиниться ні перед чим, аби заволодіти нею.\n\nЗважаючи на досліди віцекороля, що наповнював своїх жертв силою тіні, наслідки того, чого він міг би досягти на Аргусі, воістину жахливі."},
    [1982] = {n="Л'ура", d="Коли Велен зі своїми послідовниками тікали з Аргуса на борту \"Генедара\", наару Л'ура лишилася позаду, щоб виграти дренеям час на втечу. Кіл'джеден, розлючений цією зрадою, наказав запечатати поранену наару в Престолі Тріумвірату.\n\nЗа довгі тисячоліття, що минули, Л'ура впала зі Світла в Порожнечу. Її витончена пісня відваги й надії стала тіньовим плачем розпачу, що вабить тих, хто прагне заволодіти її силою."},
    [1983] = {n="Варіматрас", d="Як один із жахливих лордів, що керували військами Легіону під час Третьої війни, Варіматрас не зміг спинити бунтівного Короля-Ліча. Він пристав на лиховісний союз із Сильваною Віндраннер, а потім зробив останню спробу здобути владу, перш ніж зазнати принизливої поразки.\n\nЗа свої прорахунки Варіматрас зазнав тортур від Сабату шиварр. Мстиві сестри здерли з нього і плоть, і розум, лишивши єдине бажання — завдавати страждань смертним, які коштували йому всього."},
    [1984] = {n="Аґрамар", d="Колись шляхетний Месник Пантеону, Аґрамар був повалений Саргерасом і відроджений як титан руйнування. Тепер він стоїть у ядрі Аргуса, оберігаючи силу, що здатна знищити всесвіт.\n\nНавіть демонам не дозволено ступати в зали титана, а будь-якого смертного, зухвалого настільки, щоб порушити цю заборону, спопелить палаючий клинок Аґрамара — Тейшалах."},
    [1985] = {n="Берегиня Порталів Гасабель", d="Берегиня Порталів Гасабель підтримує нексус, через який Легіон вивергав свої підступні армії на незліченні світи. Маючи портали, що відкриваються до безлічі стратегічних місць у Великій Темній Безодні, Гасабель здатна обрушити всю міць арсеналу Легіону на кожного, хто стане їй на заваді."},
    [1986] = {n="Сабат шиварр", d="Довівши, що вони — найрозбещеніші й найфанатичніші з усіх його послідовниць, Саргерас довірив Сабату нечестиве завдання: спотворити розум полеглих титанів у нездоланний Темний Пантеон.\n\nКожна сестра застосовує власний неповторний різновид тортур, видобуваючи крики, що відлунюють залами Анторуса. Кажуть, ні смертний, ні демон не здатні встояти перед їхнім шепотом, тож воля титанів буде зламана — то лише питання часу."},
    [1987] = {n="Гончаки Скверни Саргераса", d="Просякнуті вогнем і тінню, Ф'харг і Шатуг — улюблені пестунці Саргераса. Виплекані для різанини, ці гончаки тішаться, потрошачи ворогів свого володаря.\n\nКоли Армія Світла та її союзники наступають на Анторус, Легіон готується спустити цих лютих створінь на поле бою, щоб покласти край вторгненню смертних."},
    [1992] = {n="Світоруйнівник Ґароті", d="Збудована глибоко в ядрі Аргуса й оснащена арсеналом, здатним винищувати світи, ця бойова машина створена з єдиною метою — поставити вторгнення смертних на коліна."},
    [1997] = {n="Анторійське Верховне Командування", d="Колись давно, у золоту добу цивілізації ередарів, було створено раду, щоб наглядати за обороною Аргуса й підтримувати мир. Та після укладення темної угоди із Саргерасом ці майстри-тактики використали свій військовий хист, аби допомогти влаштувати Палаючий хрестовий похід, що спустошив незліченні світи.\n\nТепер уся міць армії Легіону в їхній владі, і вони використовують цю жахливу силу, щоб знищити всіх, хто противиться волі Темного Титана."},
    [2004] = {n="Кін'ґарот", d="Задум кожної бойової машини Легіону постає з розбещеного розуму Кін'ґарота. Одержимий створенням знарядь смерті, Кін'ґарот вплавив власне тіло у виробничу машинерію, щоб іще дієвіше виробляти нескінченний потік руйнування.\n\nЗа наказом темного володаря Легіону гарячкова геніальність Кін'ґарота витворила нову супер-зброю, яку він планує спустити на Армію Світла."},
    [2009] = {n="Імонар Душолов", d="Сумнозвісний Імонар служить Легіонові за гончака, здатного вистежити здобич по всьому космосі. Маючи під рукою величезне розмаїття пристроїв і пасток, Імонар досі не втратив жодної винагороди... і він аж ніяк не збирається заплямувати свій бездоганний послужний список, не виконавши свого останнього контракту."},
    [2010] = {n="Матрона Фолнуна", d="Матрона Фолнуна нищить світи, заражаючи їх своїм поріддям. Ці мерзенні створіння розповзаються краєвидом, наче пошесть, споганюючи й пожираючи все на своєму шляху."},
    [2011] = {n="Володарка Аллюрадель", d="Усі, хто погляне на Володарку Аллюрадель, потрапляють під її лиховісну владу. Своїм підкореним жертвам вона наказує завдавати собі жахливих мук. Єдина надія невільника на порятунок — це смерть, але Аллюрадель не дарує цього звільнення, доки їхні зойки агонії не перестануть її тішити."},
    [2012] = {n="Інквізитор Мето", d="Майстерністю Інквізитора Мето в магії Скверни можуть зрівнятися лише одиниці в Легіоні. Мето використовує цю силу, щоб сіяти хаос і руйнування по всьому космосі, лишаючи за собою незліченні палаючі світи."},
    [2013] = {n="Оккуларус", d="Оккуларус живиться розумом своїх ворогів, смакуючи їхній відчай, поки випалює їхню плоть. Це лиховісне створіння пожерло цілі світи, та його голод залишається невгамовним."},
    [2014] = {n="Сотанатор", d="Легендарну силу Сотанатора було викувано в незліченних вогняних походах по всьому космосі. Цей жорстокий демон-генерал командує величезними легіонами, які ще не зазнали поразки."},
    [2015] = {n="Володар Ями Вайлмус", d="Жорстокість Володаря Ями Вайлмуса славиться навіть серед Легіону. Він тішиться, коли підпалює своїх ворогів вогнем Скверни, а потім сміється з їхнього відчаю, поки вони благають про милість смерті."},
    [2025] = {n="Еонар Життєв'язка", d="Хоч її й здолав клинок Саргераса, есенція Життєв'язки втекла від хватки Темного Титана. Після тисячоліть, проведених у самотньому сховку, притулок Еонар було знайдено Легіоном.\n\nЯкщо її душа потрапить до рук ворога, сили природи й росту Еонар спотворять, щоб зробити Палаючий Легіон нездоланним."},
    [2030] = {n="Язма", d="Поглинувши міць Шадри, павучої лоа, Язма тепер має завдання втримати священний храм Атал'Дазар для свого володаря, пророка Зула."},
    [2031] = {n="Аргус Руйнівник", d="Скутий. Зламаний.\nЕони існування, в яких відомий лише біль.\nРозтрощена душа, що живить нескінченне зло.\nВолодар кличе. Повстань... Повстань!\nПоклади початок кінцю всіх речей."},
    [2036] = {n="Вол'каал", d="За життя Вол'каал був надійним охоронцем Язми. Після його дочасної смерті вона скористалася своєю новонабутою силою, щоб оживити тіло колишнього лейтенанта, який тепер може служити їй вічно."},
    [2082] = {n="Жриця Алун'за", d="Як фанатична захисниця золотого святилища Атал'Дазара, жриця Алун'за прийшла очистити храм від усякої скверни за будь-яку ціну."},
    [2083] = {n="Резан", d="Резан, колись лоа королів Зулдазара, втратив душу, вирвану з тіла під час ритуалу. Тепер лишилася сама спотворена оболонка, що прагне пожерти кожного, хто ступить на його мисливські угіддя."},
    [2093] = {n="Рада капітанів", d="Капітани Рауль, Еудора та Джоллі сходяться у Фрігольді, щоб випити й порадитися. Вони очолюють команди Чорнозубих Забіяк, Трюмних Щурів і Корсарів Розтинавод, які нині зібрав під прапором Залізноплинних Гарлан Світ."},
    [2094] = {n="Арена Здобичі", d="У Фрігольді відбувається бійцівський турнір, де найлютіші розбійники з усіх морів випробовують свою силу. Цей збір негідників складається з дивної суміші суперників, та жоден не такий грізний, як теперішній чемпіон, Акулобій. Безліч сміливців намагалися повалити могутнього кулачного бійця, але всі вони стали наживкою для риб."},
    [2095] = {n="Гарлан Світ", d="Гарлан Світ — очільник Залізноплинних Нальотчиків, і його незмірне багатство перевершує хіба що його ницість. Нині, на утриманні леді Ешвейн, Світ дістав завдання об'єднати різні піратські команди будь-якими засобами."},
    [2096] = {n="Наглядач Корґус", d="Наглядач Корґус, страж Тол Даґора, керує могутньою острівною в'язницею. Його любов до азериту широко відома: він навіть просочує ним свої кулі та випробовує наслідки на своїх в'язнях."},
    [2097] = {n="Піщана королева", d="Про потвору, що живе в пісках навколо в'язниці, відомо вкрай мало. Жоден в'язень ще не пережив спроби втечі — варта знаходила лише покинутий одяг і кістки."},
    [2098] = {n="Джес Гавліс", d="Лютий пірат сумнівної вірності, Джес Гавліс був схоплений разом зі своїм братом і кинутий за ґрати. Звільнившись під час в'язничного бунту, Джес відтоді став фактичним ватажком зграї, що контролює нижні рівні в'язниці."},
    [2099] = {n="Лицар-капітан Валірі", d="Лицар-капітан Валірі наглядає за вибуховими боєприпасами в арсеналі Ешвейн. На лихо її підлеглим, її одержимість вогнем часто створює небезпечні умови праці."},
    [2102] = {n="Небокап'тан Краґґ", d="Небокап'тан Краґґ і його вірна їздова тварина Шаркбейт — охоронці Фрігольда, що невпинно патрулюють небо в пошуках непроханих гостей. Принаймні робити вони мають саме це. Натомість цих двох частіше можна застати, як вони куняють у своєму вороньому гнізді або скидають згори ґуано на нічого не підозрюваних жертв."},
    [2109] = {n="Монетний Натовповгамселювач", d="Коли ґобліни б'ються, у суперечці перемагає той, у кого найтовстіший гаманець. Чому? Бо він може дозволити собі заплатити Натовповгамселювачу."},
    [2114] = {n="Азерокк", d="Ґобліни, що бурили землю в пошуках азериту, потривожили могутнього духа землі — Азерокка, який прибрав тілесної подоби, щоб помститися!"},
    [2115] = {n="Рікса Флаксфлейм", d="Рікса наглядає за виробництвом азеритового каталізатора для Venture Co. Це уславлена хімікиня та запекла піроманка."},
    [2116] = {n="Магнат Раздунк", d="Так і не зумівши піднятися до торгового принца, Магнат Раздунк певен, що, ставши найвидатнішим азеритовим бароном у світі, нарешті здобуде славу й багатство, гідні куди вищого становища."},
    [2125] = {n="Тріада Серцезгуби", d="Однією з перших віддавшись Серцезгубі, ці сестри опанували кожна свою власну особливу форму магії. Тепер вони прагнуть здобути ще більшу силу, орудуючи своєю фокусувальною ірисою."},
    [2126] = {n="Душезв'язаний Голіаф", d="Душезв'язаний Голіаф — це злиття змучених душ култірасців, яких він пожер. Їхні стражденні зойки лунають із нутра цього страховиська: жалобна пісня для тих, хто був достатньо нерозумний, щоб стати йому на шляху."},
    [2127] = {n="Раал Ненажерливий", d="Раал Ненажерливий колись був головним кухарем родини Вейкрестів. Тепер його кухня — палата жахіть, де він подає шматки самого себе проклятим гостям, що никають цими залами."},
    [2128] = {n="Лорд і леді Вейкрест", d="Зломлена горем через невиліковну недугу чоловіка, леді Вейкрест волала до будь-якої сили, що могла б його врятувати. Ґорак Тул відповів на її поклик і пообіцяв, що смерть ніколи не розлучить це подружжя, — та за свою ціну."},
    [2129] = {n="Ґорак Тул", d="Ґорака Тула та його кровожерливих друстів уперше було переможено стародавнім орденом култіраських воїнів дві тисячі років тому. Ув'язнений у Заражених землях, Ґорак Тул вичікував своєї нагоди помститися. Тепер Ґорак Тул осквернив осердя влади Друствара, а його нові послідовники гарячково змовляються, щоб визволити його з ув'язнення."},
    [2130] = {n="Споклик Занча", d="Спотворений псуванням Ґ'гууна, Занча прагне лиш одного — поширити чуму, що гниє в його оживленому трупі."},
    [2131] = {n="Скелепаща Заражений", d="Заражений паразитами, що несуть чуму, цей звір прагне лиш одного — вирватися з печер, де він зможе розповсюдити зараження Ґ'гууна по всьому світу."},
    [2132] = {n="Чоппер Редгук", d="Жорстокість Чоппера Редгука наводить жах на весь Кул-Тірас. За підтримки сил Залізного Припливу Чоппер безкарно лютує по Боралусу, насолоджуючись хаосом, що шаленіє на вулицях."},
    [2133] = {n="Сержант Бейнбрідж", d="Сержант Бейнбрідж — невблаганний офіцер, що залізною рукою насаджує свій порядок. Переконаний, що слабкість слід карати смертю, Бейнбрідж не вагаючись відправляє на шибеницю тих, хто його прогнівив."},
    [2134] = {n="Гадал Деркфатом", d="Гадал Деркфатом — прадавній морський велетень, покликаний з глибин, щоб обрушити свій гнів на Боралус. Своєю величезною силою він трощить будівлі, статуї та містян однаково."},
    [2139] = {n="Т'зейн", d="Оживлений могутнім вуду з найближчого Некрополя, Т'зейн блукає болотами Назміру в пошуках нових душ, щоб поглинути їх."},
    [2140] = {n="Вік'Гот", d="Покликаний з глибин леді Ешвейн, Вік'Гот спустошив гавань. Здатний затягувати цілі галеони в нищівні безодні, цей левіафан мусить бути переможений, доки не знищено кул-тіранський флот."},
    [2141] = {n="Джі'арак", d="Цей могутній птеродакс має гніздо високо в горах Зулдазару, де повітря заріділе для більшості легень, а життя ледь утримується. Час від часу вона спускається на болота внизу в пошуках поживнішої здобичі, щоб принести її своєму виводку."},
    [2142] = {n="Аддеріс і Аспікс", d="Пара могутніх сетраків, яким доручено охороняти вхід до храму, щоб ніхто не завадив задуму їхнього володаря."},
    [2143] = {n="Меректа", d="Меректа — плід мерзенних дослідів, метою яких було створити армію нездоланних звірів. Її кладка яєць починає вилуплюватися, тож ця мати полює на жертв, щоб нагодувати своїх ненажерливих дітей."},
    [2144] = {n="Ґалваззт", d="Через осквернення її храму влада Сетраліс над блискавками породила спотворених елементалів, що блукають затопленими палатами. Найпотужніша з цих істот зветься Ґалваззт, і вона здатна винищити все, що перетне її шлях."},
    [2145] = {n="Аватар Сетраліс", d="Серце Сетраліс опинилося в лещатах жахливої сили, що прагне його осквернити. Її аватар треба відновити, перш ніж це зло вкорениться і вона переродиться темним лоа, здатним знищити весь Вол'дун."},
    [2146] = {n="Смердючий пожирач", d="В Ульдірі ставили досліди над незліченними формами життя, зокрема над кількома лоа, що жили в лісах довкола Зандалару. Коли експерименти виявилися смертельними, останки лоа поховали недбало — на превелику втіху темної свідомості, ув'язненої в Ульдірі."},
    [2147] = {n="Ґ'гуун", d="В Ульдірі титани сподівалися знайти спосіб подолати Прадавніх Богів. Та коли вони почали досліджувати безкінечну, ненаситну жагу Прадавніх Богів осквернювати, то несподівано створили досконале втілення цього бажання. Ґ'гуун — це сама гнилизна, пошесть і тлін, найдосконаліший паразит, який не здатен спинитися, доки не пожере свого носія дощенту."},
    [2153] = {n="Аку'сірр", d="Глибини ховають чимало могутніх таємниць, загублених у часі. Лорд Штормосонг, володар цих вод, прикликає одну з цих міфічних істот, щоб захистити священну святиню."},
    [2154] = {n="Рада мудреців припливів", d="Брат Айронгал і закличниця штормів Фей використовують свою силу, щоб благословляти кул-тірасські кораблі та забезпечувати незрівнянність їхнього флоту на морях."},
    [2155] = {n="Лорд Штормосонг", d="Володар дому Штормосонгів, лорд Штормосонг веде мудреців припливів у їхніх океанічних благословеннях і звичаях. Та не все таке, яким здається..."},
    [2156] = {n="Вол'зіт Шептун", d="Послана королевою Азшарою, щоб збаламутити мудреців припливів, Вол'зіт нашіптує обіцянки могутності тим, хто готовий слухати."},
    [2157] = {n="Старійшина Ліакса", d="Віддана прихильниця Ґ'гууна, старійшина Ліакса прагне далі ширити гнилизну через ритуальні криваві жертвопринесення."},
    [2158] = {n="Розкута потвора", d="Гнилизна Ґ'гууна в найчистішому вигляді — розкута потвора має єдине призначення: заражати все живе."},
    [2165] = {n="Золотий змій", d="Спочинок Королів уже зазнавав нападів. Багато тисячоліть тому, коли нерозважливий троль спробував прикликати на цей острів Гаккара Душолупа, жерці Зандалару створили могутній конструкт на захист цієї гробниці. Відтоді Золотий змій стоїть проти зловмисників, вирішуючи, хто гідний увійти до цих священних залів."},
    [2166] = {n="Вектіс", d="Чума зіпсованої крові забрала незліченних тролів і поклала початок одному з найжахливіших періодів в історії Зандалару. Конструкти всередині Улдіру вивчали хворобу в пошуках ліків, але виявили, що дієвими є лише ізоляція та знищення. На жаль, коли захисні системи комплексу почали руйнуватися, чуму випадково поєднали зі зразком крові Ґ'гууна, породивши нову істоту, що жадала свіжих жертв."},
    [2167] = {n="МАТИ", d="Титанічну Наглядачку Улдіру наділили завзятістю та невгамовним прагненням віднайти «розв'язання» проблеми Прадавніх Богів. Її протоколи лишилися цілковито недоторканими, навіть попри те, що багато інших систем у її комплексі занепали. ПОПЕРЕДЖЕННЯ: М.А.Т.И. не прийме допомоги від заражених піддослідних."},
    [2168] = {n="Талок", d="Хранителі-титани створили незліченні системи, щоб виявляти та стримувати будь-який прорив у комплексі. Їхній найпотужніший конструкт, Талок, пильнував за будь-якими ознаками скверни в краї та безжально викорінював усе, що знаходив. Та коли минули тисячі років, його внутрішній захист почав занепадати, і він став уразливим до скверни."},
    [2169] = {n="Зек'воз, Вісник Н'Зота", d="Невдовзі після Розколу на молоді береги Зандалару прибув темний посланець, маючи намір віддати недавно ізольоване плем'я на службу Н'Зоту. Зек'воз був готовий вабити, підкуповувати, улещувати, спокушати чи просто винищити їх, але не був готовий зіткнутися з обороною Улдіру. Його схопили, вивчили, розібрали на частини й помістили до Архівів Титанів, де він чекав нагоди втекти."},
    [2170] = {n="Рада Племен", d="Колись настав час, коли жоден імператор не міг правити Зандаларом одноосібно. Після періоду громадянської війни голови трьох родин уклали хитку коаліцію й спробували правити імперією разом. Хоча вони нечасто доходили згоди, у Зандаларі панував мир. Недовго."},
    [2171] = {n="Мчимба Бальзамувальник", d="Колись у Зандаларі існувала каста, чиїм призначенням було берегти й захищати останки колишніх правителів. Та коли імперією прокотилася страшна чума зіпсованої крові, для смертних стало надто небезпечно поратися біля мертвих. Для похмурої роботи зі збереження та поховання прикликали големів; відтоді їх і використовують."},
    [2172] = {n="Дазар, Перший Король", d="Дазар. Засновник і перший Король Зандалару, що вивів свій народ із багна й твані й збудував місто із золота. Перший приборкувач рапторів. Непереможний воїн. Батько королівства.\n\nЙого вічний спочинок обірвала темна магія Зула, і тепер тобі належить знову заспокоїти його навіки."},
    [2173] = {n="Грізна Капітанка Локвуд", d="Грізна Капітанка Локвуд командує цілим арсеналом азеритової артилерії. Наразі її гармати націлені на палац, погрожуючи обернути осердя влади Праудмурів на руїни, якщо ті не здадуться."},
    [2194] = {n="Мітракс Розплітач", d="Мітракс Розплітач, Носій Забуття, Убивця Сетраліс: виконавши свою місію, він повертається до боку свого володаря, щоб чекати подальших наказів."},
    [2195] = {n="Зул Відроджений", d="Колись Зул, гордий очільник Ради Занчулі — найвищих радників при королях Зандалару, — славився як найвеличніший із пророків. Тепер темний пророк повстав проти короля Растахана й прагне, щоб справжня тролська імперія знову запанувала над світом, навіть якщо для цього доведеться скоритися кривавому богові Ґ'гууну."},
    [2197] = {n="Градова конструкція", d="Градову конструкцію створили перші мешканці Друствару, щоб боронити ці землі від будь-яких загарбників. Та довгі роки бездіяльності затьмарили її розум, і тепер вона вбачає загрозу в усіх місцевих жителях, прирікаючи їх на знищення."},
    [2198] = {n="Призвідник війни Єнайз", d="Темний шепіт огортає Долину Штормової Пісні: краєм ширяться чутки про моторошних потвор, і родини позначають свої двері рунами місцевих писарів. Часто такі історії відмахують як перебільшення, але часом байки господинь і близько не передають справжніх жахіть, що чигають у царстві поза межами нашого зору."},
    [2199] = {n="Азуретос, Крилатий Тайфун", d="Азуретос, жах морів Кул Тірасу, скеровує силу вітру, щоб гнати ворогів зі свого гнізда, здіймати водяні смерчі й перекидати кораблі. Він заслужено здобув славу однієї з найсмертоносніших тварюк Кул Тірасу."},
    [2210] = {n="Дюнопожирач Краулок", d="Кістки велетенських плазунів Зандалару, розкидані по всьому краю, шанують усі тролі, а надто зандаларі. Та коли під пісками ворушаться темні енергії, часом те, що мало б лишитися мертвим, оживає знову. Краулок знову бреде пісками, осліплений люттю й нескінченними муками своїх передсмертних хвилин. Лихо тим, хто опиниться на шляху цього звіра."},
    [2212] = {n="Рев Лева", d="Рев Лева — вершина інженерної думки Альянсу. Створена панувати на полі бою, ця машина здатна перевозити легіони військ і трощити ворожі укріплення. Коли її розгортають у бою, ніщо не спинить рух цього велета до перемоги."},
    [2213] = {n="Виття Загибелі", d="Виття Загибелі створили за вкраденими інженерними кресленнями Альянсу. Цей велетенський механізм возить орди військ у найжахливіших бойових умовах, а ще здатен перетворюватися на потужну облогову платформу, що трощить ворожі укріплення."},
    [2323] = {n="Майстри Нефритового Вогню", d="Недосвідченому оку Ма'ра Похмурозуб і Анатос Вогнезаклинач можуть здатися геть невдалою парою. Та насправді їхня злагодженість не має собі рівних. Спільний натиск двох майстрів досить потужний, щоб подолати найгрізніших ворогів."},
    [2325] = {n="Ґронґ, Володар Джунглів", d="Зголосившись стати живою наддзброєю, колись розумний Ґронґ перетворився на велетенського скаженого бегемота. Та хоч його розум і згаснув, сила Ґронґа нині більша, ніж будь-коли."},
    [2328] = {n="Неспокійна Кабала", d="Покликана з глибин, щоб здобути три реліквії прадавньої сили, Неспокійна Кабала приречена служити Н'Зоту й коритися його волі. Заксадж веде мову про обіцянки й могутність, а Фа'туул нищить усіх супротивників грубою силою."},
    [2329] = {n="Івус, Лісовий лорд", d="Нічні ельфи прикликають Івуса, Лісового лорда, у часи відчаю, і не раз Орда відчула на собі його нездоланну силу. Тепер він повернувся з Альтеракської долини, щоб стати на захист рідної землі й розчавити кожного, хто їй загрожує."},
    [2330] = {n="Конклав Обраних", d="У глибинах Дазар'алора прихована зала, зведена на честь шести найвеличніших лоа Зандалару й оберігана їхніми найвідданішими послідовниками. Кожного, хто насмілиться вдертися до цього священного чертога, незабаром спіткає первісна лють, якої він ще ніколи не бачив."},
    [2331] = {n="Король Мехаґон", d="Настільки ж божевільний, наскільки й геніальний, король Мехаґон зневажає все органічне життя. Тепер, коли його мехотворець готовий до дії, ніщо не стане на заваді його задуму очистити Азерот від прокляття плоті й механізувати цілий світ."},
    [2332] = {n="Уу'нат, Вісник Порожнечі", d="Коли десять тисяч років тому королева Азшара уклала угоду з Н'Зотом, вона віддала на службу Прадавньому богові одного зі своїх найвідданіших послідовників. Тепер Уу'нат і повзучі полчища під його керівництвом провіщають пришестя свого володаря, як було передбачено зорями."},
    [2333] = {n="Поборниця Світла", d="Як вістря наступу Альянсу на Дазар'алор, Фріда Айронбелловз веде свої війська з запалом і переконанням. Бойова майстерність і непохитна віра у Світло роблять її силою, з якою не можна не рахуватися."},
    [2334] = {n="Великий тінкер Меккаторк", d="Незрівнянні у своїй винахідливості, творіння Ґелбіна Меккаторка стали запорукою наступу Альянсу на Дазар'алор. Його найсучасніша броня споряджена найновішим — і найсмертоноснішим — озброєнням, яке лише може запропонувати ґномська інженерія."},
    [2335] = {n="Король Растахан", d="Понад двісті років король Растахан править імперією зандаларі. Після падіння Резана він звернувся до нового покровителя — Бвонсамді, лоа смерті. Темна угода, яку він уклав, дарує йому силу нищити ворогів... але якою ціною?"},
    [2336] = {n="Бойові танки", d="Найкращі мехінженери Мехаґона випробовують свою звитягу (і метал), будуючи власноруч зібраних бойових роботів. Зазвичай ці танки б'ються між собою заради слави, та об'єднують зусилля, щоб відкинути нерозважливих органічних чужинців, які насмілюються потикатися до Мехаґона."},
    [2337] = {n="Штормова блокада", d="Брат Джозеф і сестра Кетрін — щирі шанувальники хвиль. Ці горді кул-тірасці радо ризикнули б життям, щоб убезпечити своїх земляків. Їхня влада над морем і штормом вражає так само, як прадавні й могутні ритуали, які вони відправляють."},
    [2339] = {n="К.У.-Дж.0.", d="Слугуючи звалищем для міського мотлоху, Підхлам є першочерговою ціллю для ґномів із банди Бондо, що прагнуть викрасти цінні механічні деталі. Поки Володарка Брухту Венді Коґсворт невпинно перебирає міське сміття, її вірний сторожовий пес К.У.-Дж.0. не пускає всередину непроханих гостей — як мехаґномів, так і шукачів пригод."},
    [2340] = {n="Ґронґ Воскреслий", d="Колись могутній Ґронґ ладен був пожертвувати всім, щоб служити Альянсу, та нині його підняли з мертвих і нацькували на колишніх соратників. Битися за Орду — мерзота для цієї шляхетної душі, єдина надія якої на звільнення — чиста смерть."},
    [2341] = {n="Майстри Нефритового Вогню", d="Хоч навчатися разом вони почали лише нещодавно, Мансерой і Местра відточили свою злагоджену гру і тепер стоять єдиним фронтом. Вогнем і кулаками вони готові вразити кожного, хто кине виклик Альянсу."},
    [2342] = {n="Опуленс", d="Давним-давно король Дазар наклав чари на свою золоту скарбницю, щоб вона повставала проти будь-кого, крім її законного власника. Чимало необачних злодіїв загинуло від тих самих багатств, які вони жадали, — важливий урок для всіх, хто схотів би обікрасти трон."},
    [2343] = {n="Леді Джайна Праудмур", d="Коли флот Альянсу відступає від Дазар'алору, леді Джайна Праудмур лишається з жменькою кул-тіраських кораблів, щоб сповільнити погоню Орди. Грозові хмари збираються вгорі, а Джайна веде переслідувачів усе глибше у Велике море, де спробує обернути долю на свою користь."},
    [2344] = {n="Поборниця Світла", d="Ра'вані та її загін — перша лінія оборони проти Альянсу, що заприсяглася віддати життя за своє місто. Стоячи разом, вони підсилюють і зцілюють одне одного, відбиваючи навалу нападників."},
    [2345] = {n="Івус Зотлілий", d="Колись надійний союзник у Альтеракській долині, Івус Володар Лісу піддався порчі Орди, повернувшись на захист Темного узбережжя. Та навіть у тлінні, з розумом, скрученим темною магією, він радше впаде, ніж віддасть ворогам бодай п'ядь лісу."},
    [2347] = {n="Бегемот Чорноводдя", d="Викликаний з невідомих глибин, Бегемот Чорноводдя зачаївся в безодні, такій темній, що навіть наги не наважуються в неї поткнутися. Лише Азшара здатна приборкати цього звіра, і вона вишколила його віддано стерегти свої скарби."},
    [2348] = {n="Сад Машиніста", d="Прекрасні й небезпечні, металеві сади головного машиніста Спарфлакса створені і для відпочинку, і для відплати. Один порух важеля — і ідилічний краєвид обертається на смертельну пастку, з якої не втекти жодному чужинцеві."},
    [2349] = {n="За'кул, Вісник Ні'алоти", d="Вісник кінця світу, За'кул зриває останні рештки розуму зі світу, що поринув у хаос, закладаючи підвалини для нового володаря Азероту."},
    [2351] = {n="Орґозоа", d="Орґозоа дбає про виводок Азшари, готуючись до дня, коли її жахіття, що зріють у яйцях, будуть випущені на Азерот."},
    [2352] = {n="Безодняна командирка Сівара", d="Майстриня як бойових, так і магічних мистецтв, безодняна командирка Сівара безжально вела авангард Азшари до незліченних перемог."},
    [2353] = {n="Сяйво Азшари", d="Принісши власну прислужницю як добровільну жертву, Азшара виплавила елементаля бурі та магії. Живлена душею відданої васалки, ця потвора є втіленням сяйва Азшари."},
    [2354] = {n="Леді Ешвейн", d="Невпинна гонитва Прісцилли Ешвейн за владою врешті привела її до Вічного Палацу й до темної угоди з королевою Азшарою. Та винагорода, яку Ешвейн отримує за свою відданість, може виявитися більшою, ніж вона сподівалася."},
    [2355] = {n="Повітряний блок гноблення HK-8", d="Хижак небес, повітряний блок гноблення HK-8 ширяє над двором, виконуючи свою головну директиву — знищувати всіх порушників. Завдяки непробивній броні та смертоносному арсеналу зброї він винищує всіх, на кого впала його тінь."},
    [2357] = {n="Король Ґоббамак", d="Одержимий накопиченням небезпечних технологій, знайдених серед брухту, король Ґоббамак сидить на купі зброї судного дня, якою йому бракує тями керувати чи яку він просто не здатен зрозуміти."},
    [2358] = {n="Замазура", d="За роки зливання докупи в концентровану вигрібну яму токсичні відходи Мекаґона набули злостивої свідомості. Тепер, коли каналізаційні системи вимкнено, Замазура вільно розтікається по всьому Азероту."},
    [2359] = {n="Двір Королеви", d="Десять тисяч років Двір Королеви незмінно втілював волю Азшари. Тепер найвпливовіші слуги королеви готові виконати її останній наказ."},
    [2360] = {n="Триксі та Наено", d="Триксі та Наено, двоє найкращих лейтенантів Бондо, мають буремні стосунки. Тоді як Триксі пишається безжальною спритністю, Наено за кермом — справжнє втілення хаосу. Єдине, що їх єднає, — це схильність до безглуздого насильства, яке вони залюбки чинять над усіма, хто має нерозум забрести на їхню територію."},
    [2361] = {n="Королева Азшара", d="Королева наг, імператриця Назджатару й одна з найпотужніших істот, яких будь-коли знав Азерот, Азшара тисячоліттями плела інтриги, готуючись до цієї доленосної миті. Тепер, коли всі фігури на своїх місцях, нарешті настав час відкрити її кінцевий задум."},
    [2362] = {n="Улмат, В'язальник Душ", d="Улмат, В'язальник Душ, прагне поневолити неспокійних духів Назджатару. Якщо його не спинити, він збере нездоланне військо нежиті, скуте його лиховісною волею."},
    [2363] = {n="Вакемара", d="Викликана з глибин стародавнім ритуалом наг, Вакемара знову постає, щоб сіяти хаос на поверхні."},
    [2364] = {n="Ра-ден Осквернений", d="Доблесно борючись за порятунок Серцевої Палати, Ра-ден був затягнутий до Ні'алоти, де став жертвою шепоту Н'Зота. Розпач, який він плекав так довго, переборов останній проблиск його надії, і його зіпсуття стало довершеним. Тепер колишній Високий Хранитель не спиниться ні перед чим, щоб виконати волю Прадавнього Бога."},
    [2365] = {n="Маут", d="Коли стародавні акіри постали з пустельних пісків, їхні пророки взялися створити обсидіанового руйнівника, наповненого есенцією Прадавніх Богів. Гнаний невгамовною жагою магії, Маут, щойно пробудившись, поглинув ману своїх творців і лишив їхні тіла гнити під палючим сонцем Ульдуму."},
    [2366] = {n="Панцир Н'Зота", d="У центрі Ні'алоти височіє моторошна гора плоті, що кишить очима й щупальцями нестримного зіпсуття. Саме божевілля сочиться зі звивистої маси, роз'їдаючи розум усіх, хто наближається до неї. Це серце Чорної Імперії, осердя могутності Н'Зота, тіло бога."},
    [2367] = {n="Шад'гар Ненаситний", d="Шад'гар Ненаситний, одне з найжахливіших творінь Н'Зота, годується зіпсутими тушами, які слуги Прадавнього Бога скидають до його володінь. Мучений безперервним голодом, тіло Шад'гара спотворюється й мутує з кожним поглинутим трупом."},
    [2368] = {n="Вратіон, Чорний Імператор", d="Попри всі застороги, Вратіон не зміг уникнути безумства, що забрало його батька. Із розумом, спотвореним Н'Зотом, він вірить, що єдиний спосіб справді захистити Азерот — це правити ним в ім'я Прадавнього Бога. Уже не принц, Вратіон тепер посідає належне йому місце Чорного Імператора."},
    [2369] = {n="Пророк Скітра", d="Майстер ілюзій, Скітра тішиться, тероризуючи своїх жертв і руйнуючи їхнє сприйняття реальності. Ті, хто не здатен прозріти крізь його омани, навіки губляться в Ні'алоті."},
    [2370] = {n="Вексіона", d="Одержимо володіючи силою, яку дарував їй Н'Зот, Вексіона зібрала навколо себе культ шанувальників, що прагнуть дарів Порожнечі. З вершини свого храму в Чорній Імперії вона перетворює найвідданіших послідовників на нестримні жахіття."},
    [2372] = {n="Колективний Розум", d="Замкнені в боротьбі воль, генерали Ка'зір і Тек'ріс безперестанку змагаються за владу над своїми побратимами-акірами. Поки вони виривають контроль один в одного, рій змінює тактику й виконує кожен їхній наказ із палкою відданістю."},
    [2373] = {n="Дрест'аґат", d="Гротескне поєднання плоті, відоме як Дрест'аґат, дрімало під Ні'алотою тисячоліттями, доки повернення Н'Зота не пробудило його. Тепер вона здіймається, мов огидний нарив, готовий лопнути й рознести свою мерзенну пошесть по всьому Азероту."},
    [2374] = {n="Іл'ґінот, Відроджена Скверна", d="Після поразки в Смарагдовому Жахітті Іл'ґінот відступив у глибини Ні'алоти, щоб відновити сили. Тепер він зрісся із спорудами міста й поширюється Чорною Імперією, наче повзуча зараза. Що більше росте оскверняюча плоть Іл'ґінота, то більшає і його могутність."},
    [2375] = {n="Н'Зот Розбещувач", d="Зі своєї викуваної титанами в'язниці глибоко під хвилями Н'Зот цілі еони непомітно ширив свій вплив усім Азеротом. Нині, звільнившись із полону, Розбещувач являє свою справжню подобу й здійснює остаточний задум: зробити своє бачення Чорної Імперії нашою новою дійсністю. Якщо його не спинити, усе, що ми колись знали, буде перероблено за образом його вічного безумства."},
    [2377] = {n="Темна інквізиторка Ксанеш", d="Мало хто здатен опиратися шепоту Прадавніх Богів, та ті, кому це вдається, опиняються на «милості» Темної інквізиторки Ксанеш. Жорстока й садистична катарка, Ксанеш пишається тим, що поволі вирізає здоровий глузд зі своїх підопічних, аж доки не лишиться нічого, крім непохитної відданості Н'Зоту."},
    [2378] = {n="Велика імператриця Шек'зара", d="З пробудженням Н'Зота Шек'зара, імператриця мантидів, віддала свій рій під волю Прадавнього Бога. Служачи своєму темному володареві, вона спустила свої сили на Долину Вічного Цвітіння, щоб захопити Пандарію в ім'я Н'Зота."},
    [2381] = {n="Вук'лаз Землелам", d="Занурившись у забуті глибини Азероту, пророк Скітра відкопав нищівного акіра, відомого як Вук'лаз Землелам. Звільнений зі свого підземного сну, Вук'лаз обертає свою руйнівну міць проти тих, хто протистоїть Н'Зоту."},
    [2387] = {n="Ешелон", d="Могутній каменероджений на ім'я Ешелон завжди зневажав чужинців, особливо смертних. Він стереже Зали Спокути з небес і впаде на кожного, хто спробує переступити поріг."},
    [2388] = {n="Криксіс Ненажерливий", d="Криксіс Ненажерливий відчув запаси аніми глибоко в Кривавих Глибинах, і жага поглинути цю енергію довела його до безумства. Завдяки розлому, що нещодавно утворився в Ревендреті, Криксіс знайшов шлях до цих катакомб і прагне висмоктати кожну краплину аніми з підземного сховища."},
    [2389] = {n="Кул'тарок", d="Кул'тарок — майстер некромантичних мистецтв, який доводить, що груба сила — не єдиний шлях до вершини. Дорога до перемоги веде крізь його лабіринт магічних порталів, а потім — повз його некротичний натиск."},
    [2390] = {n="Ксав Непереможний", d="Ксав здолав і переміг стількох ворогів, що ціла черга претендентів б'ється за право кинути йому виклик. Якщо комусь вдасться пробитися повз них, Ксав із насолодою прийме гідний поєдинок."},
    [2391] = {n="Амарт Женець", d="Амарт наглядає за збиранням трупів, ширяючи над битвою на нежиттєвому страховиську Кісткоклику. Садистичний командир знищив Руку Відваги й тепер іде по їхнього Взірця."},
    [2392] = {n="Хірург Стічфлеш", d="Хірург Стічфлеш — натхненник моторошних потвор, яких випускають у бій з летючої фортеці Золрамус. Він віддається своїй справі з шаленою запопадливістю, перетворюючи плоть полеглих ворогів на неживі конструкти для воєн Малдраксуса."},
    [2393] = {n="Скрикокрил", d="Сліпа потвора Скрикокрил, якій доручено стерегти вхідну залу замку Натрія, вистежує жертв жахливими криками, що відлунюють від стін палати. Останній звук, який чують зайди у Великому Проході, — це крик чудовиська, що падає на свою здобич."},
    [2394] = {n="Багнокулак", d="Багнокулак народився у багнистому ґрунті під замком Натрія і тепер блукає залами, чекаючи наказів від графа Денатрія. Його велетенська хода відлунює замком, звіщаючи про його наближення ще за кілька кімнат."},
    [2395] = {n="Пошесткіст", d="Гладку купу гнилої плоті, відому як Пошесткіст, з любов'ю змайстрував Хірург Стічфлеш. Тепер ця потвора прагне, щоб її випустили на Храм Відваги."},
    [2396] = {n="Налтор Льодов'яз", d="З вершини летючого зикурату Золрамус Налтор Льодов'яз керує військами, що нападають на Бастіон. Підступний ліч задумав пролити крижану магію і смерть на незаймані землі Бастіону."},
    [2397] = {n="Збіговисько Суперників", d="Чемпіони б'ються не з ким завгодно. Спершу претенденти змагаються між собою, щоб з'ясувати, хто гідний. Дессія Стинальниця, Пасеран Згубний і Сатель Проклятий поєднали свої несхожі стилі бою, щоб вибити інших претендентів. Вони розчавлять кожного, хто стане між ними і двобоєм за титул."},
    [2398] = {n="Торговка Кс'екса", d="Торговка Кс'екса — хитра здобувачка, яка володіє безліччю магічних пристроїв, зібраних за тисячоліття. Вона покладається на маніпуляцію простором, щоб завжди бути на крок попереду незліченних ворогів, яких нажила у своїх оборудках."},
    [2399] = {n="Кін-Тара", d="Поки кіріанські претенденти мусили терпляче чекати на свій давно прострочений вознесіння під час засухи аніми, Зреченці не вагалися дарувати своїм вірним крила. Кін-Тара довела свою вартість темним кіріанам і опанувала небеса одразу після вознесіння. Доки вона стоїть, Шпилі Вознесіння належатимуть Девос."},
    [2400] = {n="Інґра Малох", d="Прокляті існувати поза круговертю Життя і Смерті, друсти тепер прагнуть обійти свою долю, використавши механізми Відродження Арденвельду. Їхній намір завоювання привів їх до Тірна Сайт, де Інґра Малох і його послідовники гидкою магією підкоряють місцевих мешканців."},
    [2401] = {n="Кишколом", d="Спраглий перемоги не менше, ніж нових частин тіла, Кишколом готовий довести, що Дім Конструктів здатен збудувати кращого воїна. Відколи прибув до Малдраксуса, він заслужив кожну частину свого тіла, проте не цурається відшукати щось новеньке на котромусь із суперників."},
    [2402] = {n="Туманозвачка", d="Тірна Сайт боронять не лише силою зброї, а й хитрістю. Грайлива Туманозвачка напускає тумани, щоб збити з пантелику й заплутати непроханих гостей. Через напад друстів Туманозвачка вже не може легко відрізнити друга від ворога, тож лише здолавши її загадки та ігри, ти зможеш безпечно дістатися серця Тірна Сайт."},
    [2403] = {n="Доктор Іккус", d="Знищення Дому Чуми та слизові виверження, що лишилися по ньому, не спинять гаданого генія доктора Іккуса з його божевільними дослідами."},
    [2404] = {n="Маркграфиня Страдама", d="Вважалося, що маркграфиня Страдама загинула у вибуху, який зруйнував її дім. Насправді ж вибух перетворив її на потворну нову подобу, занурив у безумство й лишив у серці занепалого Дому Чуми."},
    [2405] = {n="Тред'ова", d="Ґорми обгризали краї Арденвельду, пожираючи висохлі оболонки мертвих. Та звірюка на ім'я Тред'ова насолодилася чимось набагато ціннішим — диким зерном Лакалі, лоа знання. Тепер, скуштувавши могутності й мудрості лоа, Тред'ова прагне більшого, ніж просте виживання."},
    [2406] = {n="Халкіас, Заплямований Гріхом Голіаф", d="камені гріхів мали б бути бездіяльними записами минулих провин. Та підступи розбещених вентирів дозволили Халкіасу, велетенському голему, набратися сили від занедбаних камені гріхівв. Війська Великого Камергера ледве стримують його, розділивши його аніму між кількома уламками голема з гріхокаменю."},
    [2407] = {n="Генерал Каал", d="Генерал Каал — одна з головних генералів сіра Денатріуса, що наглядають за його справами в Ревендреті. Сильна, спритна й сповнена підступу, генерал Каал використовує свою спритність і просочену анімою натуру, щоб знищити всіх, хто посміє стати проти її володаря."},
    [2408] = {n="Хаккар Душолуп", d="Сама лише присутність Хаккара Душолупа спричинила сум'яття в Азероті. Насильство й чума — знак його крові та незмірної могутності. Його вірні билися за нього до смерті й навіть по той бік. Поступитися владою ніколи не було в його звичаї, навіть якщо ця влада належала не йому."},
    [2409] = {n="Манасторми", d="Цілковита чесність і довіра — ось що робить Міллісент і Мілгауса Манасторм такою могутньою парою. Ну, чесність, довіра, приголомшлива магія та експериментальна техніка. Поєднання цих чотирьох стихій у досконалій гармонії робить Манасторми найсмертоноснішою, найнебезпечнішою та найгубнішою парою з усіх."},
    [2410] = {n="Муех'зала", d="Батько Сну, Син Часу, Друг Ночі — Муех'зала проводжав мертвих Азероту задовго до того, як Бвонсамді уклав свою першу угоду. Він знає, що бог має правити, а не випрошувати слуг і шанувальників. Задуми, що їх він снував у прадавні часи, аби повернути собі цю владу, ось-ось дадуть плоди — щойно він розбереться зі своїм бунтівним заступником."},
    [2411] = {n="Верховна Суддиня Аліз", d="У Залах Спокути, за дворищем і ґаргульями, стоїть храм, не схожий на жоден інший в Азероті. Саме тут Верховна Суддиня Аліз очолює паству духів, несучи темне слово сіра Денатріуса негідним."},
    [2412] = {n="Девос, взірець Сумніву", d="Девос була самим символом відданості, аж доки в Бастіон не прибула душа з тривожним минулим. Сумнів охопив її настільки, що вона повстала відкрито, спираючись на найтемніші сили Тіньових земель. Захоплення Шпилів Вознесіння було лише першим кроком, і тепер знищення Архонта вже в неї на досяжності."},
    [2413] = {n="Верховний камергер", d="Верховний камергер невпинно й безжально підіймався в рядах венфірського товариства й став Жнецем, посприявши захопленню непокірної Викривачки. Тепер він панує в залах Викривачки, накопичує аніму й перетворює священний обряд спокути на знаряддя своїх збочених намірів."},
    [2414] = {n="Оріфріон", d="Оріфріон — ударна сила в авангарді взірця Відданості. Темний Колос панував над вторгненням до міста завдяки своїй артилерії на аніма, а тепер люто боронить джерело могутності перед престолом Архонта."},
    [2415] = {n="Кат Тарвольд", d="Багато венфірів вважають катування своїх підопічних та видобування гріхів і аніми своїм священним обов'язком. Те, що істоту, відому як кат Тарвольд, поставили наглядачем і дозволили їй із хворобливою насолодою мучити тутешніх в'язнів, показує, до якої ницості скотився Ревендрет."},
    [2416] = {n="Вентунакс", d="Вентунакс — один із найсмертоносніших конструктів Зреченців, спершу створений, щоб випробовувати мужність кіріанських аспірантів. Рухи Преторіанки такі стрімкі, що вона немовби зникає на очах у своїх ворогів."},
    [2417] = {n="Мордрета, Безкінечна Імператриця", d="Безкінечні битви й безкінечні перемоги — Мордрета здолала кожного супротивника, що кидав їй виклик. За життя вона була майстринею темної магії, а час, проведений у Малдраксусі, лише примножив ці знання. Невже це той титульний поєдинок, на який так довго чекав Театр Болю?"},
    [2418] = {n="Конструктор Ксай'мокс", d="Не всі в замку Натрія віддані сіру Денатрію. Дехто просто побачив нагоду й скористався нею задля власної мети. Конструктор Ксай'мокс працював із Денатрієм, але дбає здебільшого про те, щоб самому виграти від угоди, а для цього, можливо, доведеться покінчити з нападниками на Натрію."},
    [2419] = {n="Ґлобґроґ", d="Достеменну природу пошестей і слизу, що вивергнулися з падінням Дому Чуми, певно, ніколи не вдасться збагнути, та скупчення слизу й плоті, що стало Ґлобґроґом, фанатично боронитиме цей скарб."},
    [2420] = {n="Леді Інерва Темножила", d="Аніма живить Тіньові землі, і леді Інерва Темножила прагне розкрити її таємниці. Під опікою Денатрія вона осягнула підступні секрети, щоб обернути їх проти його ворогів. Вона вижене аніму з нападників на Натрію й використає її, щоб виліпити темне нове майбутнє."},
    [2421] = {n="Велика Наглядачка Берилія", d="Лише небагато хто достатньо старий, аби знати, чи опанувала Велика Наглядачка Берилія свій безжальний підхід до досліджень у Ревендреті, чи ніколи насправді не зреклася цього особливого гріха. Жорстокість, з якою вона опановувала магію аніми, тепер обернена проти вельми незвичайної нової бранки — наару З'ралі. Вона підкорить собі Світло цієї істоти, чого б це не коштувало її в'язню."},
    [2422] = {n="Порятунок Сонячного Короля", d="У зловісних мурах замку Натрія душі катують не задля спокути гріхів, а щоб посилити їх. Гордовитого принца Кель'таса обтяжили чужими гріхами, а його біль і ненависть скеровують, щоб зробити з нього могутню зброю. Це наразило його душу на небезпеку, як жодну іншу, і її треба врятувати - хоча б для того, щоб її не випустили на Тіньокрай."},
    [2423] = {n="Доміна Отрутоклинок", d="Доміна Отрутоклинок певна, що знаряддя її помсти за падіння Дому Очей криється в Чумопаді. Ніхто, навіть її колишні союзники, не завадить їй здобути зброю, заховану серед цих руїн."},
    [2424] = {n="Сір Денатріус", d="Незліченні віки Сір Денатріус стояв серед Вічних, які правлять володіннями Смерті. Та в найтемнішу годину Тіньокраю він зрадив свій священний обов'язок. Зі своїм кровожерним живим клинком Реморнією при боці та під захистом найулесливіших прибічників Денатріус прорубає шлях крізь усіх, хто стане проти нього, і скине їхні рештки в невідворотний жах Пащі."},
    [2425] = {n="Генерали Кам'яного Легіону", d="Прадавні каменероджені генерали Каал і Ґрашаал переслідували повстання принца Ренатала на кожному кроці. Колись вони були учнем і наставником генерала Дрейвена; нині ж їхню силу, стратегію й воїнів обернули проти нього та всіх, хто посміє кинути виклик волі Сіра."},
    [2426] = {n="Рада Крові", d="Рада Крові головує над двірськими справами Ревендрету. Кастелян Ніклаус - суворий військовий командир із незламною волею та непробивною бронею. Лорд Ставрос, чепурний дженджик, веде придворні танці, та й клинками своїми смертоносний. Баронеса Фріда володіє могутньою магією аніми й керує прислугою-копачами, а також тішиться повагою всього двору."},
    [2428] = {n="Голодний Руйнівник", d="Пожирачі споживають аніму всюди, де її знайдуть. Коли Тіньокрай вражений посухою, не дивно, що найголодніший і найнебезпечніший із пожирачів тягнеться до рясних запасів аніми тут, у глибинах замку Натрія."},
    [2429] = {n="Ловчий Альтимор", d="Сір Денатріус рідко полює сам, але Альтимор дбає, щоб у пана завжди були найкращі звірі, якщо той колись забажає розважитися. Маргора, Барґаста й Гекутіса приборкували довше, ніж існує більшість звірів, і кожен із них готовий обрушити гнів Ловчого на будь-кого в його володіннях."},
    [2430] = {n="Валінор, Світло Еонів", d="Збудований киріанами як засіб випробування їхніх найзагартованіших воїнів, Валінор - центуріон величезної могутності. Захоплений зреченими й заражений насінням сумніву, Валінор тепер бачить у всіх ворогах суперників."},
    [2431] = {n="Мортаніс", d="Один із найученіших некромантів Дому Ритуалів, Мортаніс невтомно працював над способом перетворити себе на могутнішу подобу. Тепер до успіху йому лишилися лічені миті."},
    [2432] = {n="Ораномонос Вічногілляста", d="Колись найстарша вартова Тірна-Сайт, Ораномонос зів'яла разом із великим деревом. Аніми в ній лишилося так мало, що вона вже не відрізняє друга від ворога, поки ґорми обжираються її тлінною плоттю."},
    [2433] = {n="Нурґаш Багноформ", d="Зліплений зі слизистої маси багатьох спливаючих копачів і підсилений темною магією найвправнішими чаклунами Денатріуса, Нурґаш не вирізняється кмітливістю, та його кулаки здатні трощити цілі замки."},
    [2435] = {n="Тарраґру", d="Невблаганний звір Тюремника, Тарраґру, никає залами Торгаста відтоді, як звівся перший його шпиль. Безліч жертв відчули, як їхні душі стерто на попіл цим чудовиськом, що нині очікує смертних поборників, які наважилися переступити поріг вежі."},
    [2436] = {n="Поштовий хаос", d="Щось пішло шкереберть у Головній Установі Сортування Транспорту (Г.У.С.Т.). Вимірні портали безладно розкидають посилки, а автоматон, що керує установою, дав збій. Якщо хаос не вгамувати найближчим часом, ціле місто може піти рознос."},
    [2437] = {n="Зо'фекс Вартовий", d="Щоб потрапити за позолочені брами Тазавеша, кожен мусить проминути вартового Зо'фекса. Одержимий безпекою, Зо'фекс пильнує, щоб будь-яку контрабанду негайно спалювали разом з усяким, у кого знайшли заборонені речі."},
    [2439] = {n="Дев'ятеро", d="Темна угода, яку Сильвана уклала з валькірами, скувала її зв'язок із Тюремником. Упродовж років ці крилаті сестри віддано служили Темній Володарці, навіть коли це означало пожертвувати собою заради неї. Тепер Сильвана прикликає своїх дев'ять валькір востаннє стати до бою за неї."},
    [2440] = {n="Кел'Тузад", d="Підступний Кел'Тузад очікує на вершині душевної ріки, що дає личу черпати з безмежного джерела сили. Усі його незліченні підступи й махінації привели до цього останнього протистояння, у якому він уготував смертним поборникам остаточну загибель, служачи своєму справжньому володареві."},
    [2441] = {n="Сильвана Віндраннер", d="Коли Орибос опинився в небезпеці, на вершині Святилища спалахнула відчайдушна битва. Між Тюремником і смертними, що прагнуть його спинити, стоїть Сильвана Віндраннер. Не лишивши жодної маски, Королева-банші вивільняє всю свою міць, щоб захистити Вигнанця, поки його остаточний задум втілюється в життя."},
    [2442] = {n="Око Тюремника", d="Коли Азерот був юним, Одін віддав своє око Мует'залі, щоб зазирнути в Темні Землі. Та марнославного Одіна ошукали, бо Тюремник скривив Око, обернувши його на власну користь. Незмигний погляд Ока дає Тюремникові бачити все, що діється в його володіннях, а можливо, і в інших."},
    [2443] = {n="Болековач Разнал", d="Болековач Разнал — садистичний геній, що віки відточував смертоносні пастки Торгаста. Він тішиться криками своїх жертв як свідченням своєї майстерності, з лиховісною насолодою дослухаючись, як вони лунають порожніми залами вежі."},
    [2444] = {n="Рештки Нер'зула", d="Перший Король-Ліч Нер'зул мав звістувати панування Тюремника на Азероті, та в очах свого володаря виявився негідним. Останні рештки скривленої душі полеглого орка ув'язнили в утиканій шипами тіньосталі, прирікши на вічні муки за поразку. Кожен, хто перетне його шлях, розділить його страждання."},
    [2445] = {n="Душороздирач Дормазейн", d="Душороздирач Дормазейн видобуває аніму з украй жорстоких бранців Торгаста, щоб живити війська Тюремника. Дормазейн ще не зустрічав душі, якої не зміг би зламати, проте його остання жертва опирається звичним методам. Живлячись нескінченною люттю цього бранця, Дормазейн залюбки витратить тисячоліття, шукаючи його слабкі місця."},
    [2446] = {n="Вартовий Перших", d="Вирваний ланцюгами Тюремника з далекого, незвіданого світу, цей несправний вартовий прагне захистити незбагненні знання, відомі як «шифри». Він використовує рештки своєї сили, щоб знищити кожного, хто спробує викрасти таємниці його загадкових творців."},
    [2447] = {n="Літописець долі Рох-Кало", d="Колись літописець долі, якому довірили незліченні таємниці Кортії, Рох-Кало був схоплений Пащеплідними й підкорений волі Тюремника. Маючи у своєму розпорядженні силу Торгаста, Рох-Кало прагне написати нову долю для Тіньових Земель."},
    [2448] = {n="Гілбранд", d="Викрадення стародавнього артефакта Титанів пробудило його охоронця: Гілбранда, Меч Хранителів. Знешкодьте незліченні протоколи безпеки, підвладні Гілбранду, або станьте довічними мешканцями цієї гробниці."},
    [2449] = {n="Часокапітан Гуктейл", d="Місяці планування пішли намарне, коли посеред пограбування Часокапітана Гуктейл з'явилася Со'лея і викрала її здобич. Охоплена люттю, королева піратів вивільняє свою справжню подобу й трощить усіх, хто трапиться їй на шляху."},
    [2451] = {n="Со'азмі", d="Серед посередників, що живуть за законом клинка, ніхто не зрівняється з умінням Со'азмі, смертоносного вбивці картелю Со. Со'азмі без упину вдосконалює свою техніку, тож йому неабияк приємно навчати ворогів мистецтва бою — навіть розтинаючи їх на шматки."},
    [2452] = {n="Оаза Майзи", d="Напої тут ефірні, атмосфера п'янка, а вартовий дверей Зо'ґрон нетерплячий. У цій Оазі живі виконавці підуть звідси інакшими, якщо не догодять натовпу."},
    [2454] = {n="Велика Звіринка", d="Картель Ксай «здобуває» рідкісні й цінні речі, щоб продавати їх у своїй звіринці. Для них немає заборон: екзотичні звірі, заборонені технології, навіть прокляті артефакти — усе виставлено напоказ. Чого б не забажало ваше серце, картель Ксай добуде це для вас — якщо ви здатні заплатити їхню ціну."},
    [2455] = {n="Со'лея", d="Жага влади Со'леї сягає вершини в цьому останньому бою. Вивільнивши силу, якої не до кінця розуміє, очільниця картелю перетворюється на створіння нестримної люті. Поки шалена енергія струмує з артефакта, Со'лею необхідно зупинити, перш ніж її вчинки зруйнують самі підвалини Тіньових Земель."},
    [2456] = {n="Мор'ґет, Мучитель Проклятих", d="Серед незліченних поплічників Тюремника мало хто впивається своєю мерзенною працею так само завзято, як підлий Мор'ґет. Одержимий бажанням зламати волю кожної душі, якій не пощастило потрапити йому до рук, Мор'ґет тримає поле бою в залізному кулаці, дбаючи про те, щоб будь-яка похибка стала для його супротивника останньою."},
    [2457] = {n="Лорди Жаху", d="Хитрістю та підступом натрезими цілі еони працювали, щоб втілити задум Тюремника. Тепер, на порозі перемоги свого володаря, їм лишилося виконати одне-єдине завдання, щоб ніхто не зміг чинити опір новому ладу всесвіту."},
    [2458] = {n="Пильний Вартовий", d="Цей вічний вартовий чатує в очікуванні, несучи позачасову варту біля входу до Гробниці Первісних."},
    [2459] = {n="Дозеґне, Полеглий Оракул", d="Підкорена Тюремником, Дозеґне веде Пащеслухняних у битві за владу над Кузнею Загробіть. Тюремник прагне використати її силу, щоб обрушити вічність мук на всю реальність."},
    [2460] = {n="Прототипний Пантеон", d="Позбавлені космічних духів Вічних, ці незавершені тіла-носії здатні лише виконувати свої найпростіші накази без милосердя й співчуття. Та коли ворог стоїть біля воріт, Лігувіму не лишається вибору, окрім як активувати ці небезпечні прототипи."},
    [2461] = {n="Лігувім, Головний Архітектор", d="З прискіпливою турботою Лігувім вплітає ефемери в буття, дотримуючись священної волі Первісних. Тепер цей процес опинився під загрозою, адже сили Пащеслухняних прагнуть заволодіти цією силою."},
    [2463] = {n="Галондрус Відновлювач", d="Цілі еони Галондрус мандрував кручами Гробниці Первісних, виконуючи своє священне призначення: повертати ефемери до великого циклу. Тепер, коли зайди занурюють цей лад у хаос, прадавній охоронець зробить усе, щоб зберегти порядок."},
    [2464] = {n="Тюремник", d="Незліченні тисячоліття Тюремник терпляче плекав свій задум дістатися серця Гробниці. Тепер, на порозі остаточної перемоги, герої Азероту мусять згуртуватися, щоб не дати Тюремнику підкорити всю реальність."},
    [2465] = {n="Сколекс, Невситимий Пожирач", d="Коли Гробниця Первісних стала вразливою, пожирачі ринули досередини, щоб тамувати свій голод. Серед цих аберацій — ненаситний Сколекс. Коли велетенський черв поглинає величезні обсяги ефемер, рівновага Гробниці порушується, і їй загрожує занепад."},
    [2467] = {n="Райґелон", d="Приваблений спогляданням доленосних подій, що розгорталися в Гробниці Первісних, Райґелон піддався владі Тюремника. Тепер цей констеляр обертає свою космічну силу проти кожного, хто посміє стати проти Вигнанця."},
    [2468] = {n="Антрос", d="Антрос слугує вартовим скарбів острова Передвічних. Сили Тюремника прагнуть використати його, у новій підкореній подобі, щоб видобути таємниці острова й продовжити осквернення Зерет-Мортіса."},
    [2469] = {n="Андуїн Рінн", d="Підкорений магією Панування, Андуїн змушений допомагати Тюремнику в його задумі перебудувати реальність. Час зупинити його спливає, і захисники Азероту мусять зробити важкий вибір: здолати молодого короля, щоб урятувати космос, або ризикнути всім заради порятунку його душі."},
    [2470] = {n="Конструктор Ксай'мокс", d="Після поразки в замку Натрія Конструктор Ксай'мокс знову розчинився в тінях, аби спланувати своє наступне пограбування. Тепер, коли Гробниця Перших стала вразливою, Ксай'мокс скликав усю міць картелю Ксай, щоб розграбувати поховані там прадавні знання та могутні реліквії."},
    [2471] = {n="Бойова ватага Гекклока", d="Ріра Гекклок та її поплічники Ґаштут і Трикстотем постали як смертоносна бойова ватага серед Папоротешкурих. Через їхню тактику тускари ніколи не подорожують самотою, а через їхню силу Гнівоока довірила їм охороняти браму до Лощини."},
    [2472] = {n="Черевостріл", d="Ця ґнолка-снайперка опанувала мистецтво полювання, ставлення пасток і вбивства своєї здобичі. Вражена її вправністю та хитрістю, Декатріарха доручила Черевострілу наглядати за іншими мисливцями й навчати їх... а також знищувати будь-яких чужинців, що насміляться зайти надто далеко в землі Папоротешкурих."},
    [2473] = {n="Деревопаща", d="Виснажений тлінню, цей колись гордий прадавень дістав від ґнолів прізвисько Деревопаща. Щойно гниль оселилася в його гілках, вона оселилася й у розумі бідолашної істоти, лишивши по собі створіння, що прагне єдиного — пожирати й сіяти тлінь."},
    [2474] = {n="Декатріарха Гнівоока", d="У жадобі влади Гнівоока відкрила магію тліну й, опанувавши її, проголосила себе Декатріархою. Тепер вона нарощує силу Папоротешкурих, поширюючи свою темну магію серед племені, щоб тускари й уся Лазуровий Простір зогнили слідом за нею."},
    [2475] = {n="Загублені дворфи", d="Жага прадавніх знань, незліченних багатств і всесвітньої слави знову заманила братів Еріка, Олафа та Бейлоґа в глибини Ульдамана. Та схоже, що ці зухвалі дослідники просиділи під землею задовго: їхні скаламучені чуття вже не дають їм розрізнити, хто перед ними — друг... чи ворог."},
    [2476] = {n="Емберон", d="Сховища титанів зажили лихої слави своїм хитромудрим захистом, і зали Ульдамана — не виняток. Викуваний колись вправними руками Хранителя Архедаса, Емберон дістав здатність насилати пекучі язики полум'я на кожного, хто прагне розграбувати таємниці титанів."},
    [2477] = {n="Хан Балакар", d="Хан Балакар — безжальний ватажок клану Нокуд. Його буревісники полонили великого орлиного духа Он'агру, бо він прагне привласнити силу Матері Вітрів. Ненависть єднає його клан проти всіх «чужинців». Поки триває нещадний наступ, хтось мусить стати на шляху цього тирана."},
    [2478] = {n="Тіра і Маруук", d="Некроманти Укелів воскрешають легендарних кентаврів. Духи першої матріархині Тіри та найвеличнішого воїна кентаврів Маруука повстали зі своїх могил. Коли їхня лють ущухне, можливо, вони знову знайдуть спокій... і вічний мир."},
    [2479] = {n="Хроно-Лорд Дейос", d="Поки Королева Драконів прагне відновити сили Аспектів, серед драконячої зграї є й інші, хто не бажає, щоб задум Алекстраси здійснився. Хроно-Лорд Дейос має намір віддати своєму рою владу над часовими шляхами і привести пришестя єдиного істинного Аспекта, чиє панування буде... Нескінченним."},
    [2480] = {n="Ераног", d="Ераног, командувач сил примордіалістів, невпинно жадає влади. Оскільки звільнення Втілень уже близько, Ераног скликає все своє військо і не вагатиметься пожертвувати своїми відданими послідовниками заради перемоги."},
    [2482] = {n="Сеннарт, Холодний Подих", d="Сеннарт, найлютіше творіння Куроґа Ґрімтотема, — велетенська павучиха, сповнена нещадного холоду. Її єдина мета — стерегти свій виводок із тисяч яєць, чекаючи на день, коли вони вилупляться й оповиють Азерот зимовою павутиною."},
    [2483] = {n="Телаш Сірокрил", d="Розлючений на синя зграя драконів, Телаш Сірокрил сповнений рішучості розкрити таємниці, які Синдрагоса приховала в Лазуровому Сховищі. Разом із Розколотим Полум'ям він певен, що дізнається більше про походження драктирів... і знайде викривальні докази проти синьої зграї драконів."},
    [2484] = {n="Вартова Талондрас", d="Талондрас належить до рефті — раси, викуваної титанами, яку Хранитель Тір створив, щоб працювати в злагоді з драконячою зграєю. Безмежно віддані своєму творцеві, рефті часом вирушали до далеких берегів виконувати важливі завдання. Вартовій Талондрас було доручено боронити шлях до диска, що зберігає спогади Тіра, і вона сповнена рішучості не дати негідним посягнути на спадок свого творця."},
    [2485] = {n="Кокія Полум'якопит", d="Поки сили примордіалістів штурмують Рубінові Озера Життя з усіх боків, Кокії та її лейтенантам, скутим полум'ям, випадає захопити дорогоцінні яйця у переможених захисників, сіючи на своєму шляху вогонь і хаос."},
    [2486] = {n="Первісна Рада", d="Ці володарі стихій нещадні у своєму прагненні влади. Ембар Вогнестежка така ж безжальна, як і вогонь, яким вона керує. Опалозуба володіє міццю землі, щоб трощити своїх ворогів. Кадрос Льодогнів холодний і жорстокий, а його сестра Датея Штормобич дика й непередбачувана, мов розбурханий шторм."},
    [2487] = {n="Бромах", d="Кремезний Бромах — вождь троґів Кам'яного Склепу, брутальної зграї, що вважає скарби Ульдамана своїми. Бромах має особливу зневагу до набридливих дворфів і сповнений рішучості не пропустити повз себе жодного чужинця."},
    [2488] = {n="Мелідрусса Холодоткана", d="Мелідрусса Холодоткана очолює зусилля примордіалістів із насичення в Рубінових Озерах Життя. Вона палко вірить, що захищає молоді драконячі яйця від впливу титанів і очищає їх від плями магії Порядку. Вона не спиниться ні перед чим, аби сповнити своє покликання й повернути яйцям те, що вважає їхнім природним станом."},
    [2489] = {n="Майстер-Коваль Ґорек", d="Як один із найвидатніших ремісників джарадинів, Майстер-Коваль Ґорек тепер мешкає у своїй задушливій палаті в казармах чорних драконів. Там він приборкує вогняну міць велетенського горна, щоб кувати смертоносну зброю."},
    [2490] = {n="Чарґат, Згуба Луски", d="Титул цього ветерана-драконобоя був наданий ще в незапам'ятні часи як знак легендарної слави. Поки мисливці-каляші під його керівництвом тренуються, він планує їхній наступний напад і з нетерпінням чекає нагоди показати свою майстерність."},
    [2491] = {n="Курог Ґрімтотем", d="Колишній улюблений учень Маґати Ґрімтотем, цей володар первісних стихій готується випустити на волю свої найнищівніші творіння. Якщо Курога не спинити, його сутності бурі, вогню, криги й землі сіятимуть хаос по всьому Азероту."},
    [2492] = {n="Леймор", d="Леймор виріс зі скромного паростка, який Малігос знайшов у водоймі лей-енергії. Колись лише маленьке стебельце в саду Синдрагоси, за тисячоліття Леймор вистрелив угору, наче бур'ян. Якщо лишити його на самоті, цей навислий велетень неодмінно заполонить увесь Лазуровий Склеп."},
    [2493] = {n="Доглядачка виводку Діурна", d="Доглядачка виводку Діурна — люта захисниця Кладки приматистів. Вона віддає всю свою чималу силу на охорону тих, хто ще не вилупився, і прагне помсти за втрачене дитя."},
    [2494] = {n="Магматуск", d="Джарадини розкрили чимало таємниць Нелтаріона, грабуючи Нелтарус. Невдалий експериментальний відвар створив Магматуска — велетенського мамонта-бегемота, одержимого нищенням."},
    [2495] = {n="Кравт", d="Арена Ліш Лрат, або Кидок Кігтя, нині буквально стала пташиним кублом. Кравт оселилася просто в центрі арени й найближчим часом покидати її не збирається. Погляньмо, чи вдасться нам умовити її пограти в м'яч... і забратися геть."},
    [2497] = {n="Лютий буревій", d="Шалені штормові вітри спустошують рівнини Он'агри. Буревісники Балакара згустили лють бурі в подобу шторму. Лютий буревій усе більше набирає сили, щоб спустошити не лише поле бою, а й увесь Драконячий архіпелаг. Якщо його не спинити, на рівнинах запанує хаос приматистів."},
    [2498] = {n="Ґраніт", d="Ґраніт кидає свою тінь на рівнини Он'агри, з'являючись як провісник смерті й руйнації. Поки на рівнинах вирують битви між кланами кентаврів, він знає: настав час раз і назавжди знищити своїх прадавніх ворогів. Незабаром він приземлиться на полі бою. Балісти клану Шикаар будуть напоготові."},
    [2499] = {n="Расзаґет Пожирачка Бур", d="Расзаґет щиро вірить, що драконяча зграя мав бути таким же диким і вільним, як сама буря. Якщо їй вдасться визволити своїх побратимів-Втілень з прадавньої в'язниці, Расзаґет і її рідня скинуть Аспектів і вичистять світ від кожного сліду впливу титанів."},
    [2500] = {n="Террос", d="Приматисти намагалися витягти Терроса, незламну силу руйнації, з елементальної площини. Та їхній ритуал перервали. Затиснутий між двома світами, цей велетенський жах прагне звільнитися й стерти все на своєму шляху."},
    [2501] = {n="Воєначальниця Саргха", d="Очільниця джарадинів Каляш, воєначальниця Саргха шукала будь-що, що збільшило б могутність її клану та допомогло б здолати їхніх драконячих ворогів. У скарбниці в самому серці Нелтаруса вона, можливо, знайшла саме те, чого джарадинам бракувало."},
    [2502] = {n="Датея, Вознесена", d="Збожеволівши від поразки, Датея укладає угоду з Расзаґет, щоб здобути ще більшу могутність. Просякнута часткою сили Втілення, Датея опановує сам вітер і випускає його лють, щоб роздерти своїх ворогів."},
    [2503] = {n="Кіракка та Еркгарт Стормвейн", d="Кіракка та Еркгарт ширяють у небі над Рубіновими Озерами Життя, скеровуючи напади на святилище внизу й водночас знищуючи будь-яких драконів, що стають на заваді. Якщо їх не спинити, вони спалять Озера Життя дотла, а попіл, що лишиться, розвіють очисною стихійною бурею."},
    [2504] = {n="Вартовий Іридей", d="Хранитель Тір доручив Вартовому Іридею захищати й підтримувати Зали Вливання, і той бездоганно виконував свій обов'язок... до цієї миті. Заскочений зненацька вторгненням Первородців, він не встояв перед стихійними силами, що вони їх розв'язали. Цієї помилки він не має наміру припуститися вдруге."},
    [2505] = {n="Лазурний Клинок", d="Як охоронниця Скарбниці, Лазурний Клинок відмовилася піти, коли її запечатали, обравши обов'язок замість безпеки. Коли сині дракони так і не повернулися, гірке розчарування зрештою довело її до божевілля. Продовживши власне життя магією, яку присяглася берегти, Лазурний Клинок тепер привласнила собі все, що лишила по собі зграя синіх драконів."},
    [2506] = {n="Басрікрон, Сланцеве Крило", d="Басрікрон значно важчий за своїх родичів, а тому віддає перевагу життю на землі, а не ширянню в небі. Усе довкола належить Басрікрону для підкорення й дозволяє йому вдосконалювати свою майстерність. Він мовить — і земля кориться, тож він може обрушити всю міць землі на тих, хто був достатньо нерозумним, щоб стати з ним до бою."},
    [2507] = {n="Ковтливий Голіаф", d="Глибоко в печерах Залів Вливання чигає Ковтливий Голіаф. Прабатько незліченних поколінь горнсвоґів, Голіаф із його виводком розкошує на необробленій воді першоджерела. Гнаний невситимим голодом, він радо пожере будь-яку істоту, що забреде надто близько до його лігва."},
    [2508] = {n="Умбрелскул", d="Тисячоліття тому Умбрелскул несамохіть зв'язався з сирою арканною силою. Укритий кристалічними наростами, він був перенесений до Лазурової Скарбниці, доки не знайдуть ліки. На жаль, Скарбницю запечатали раніше, ніж дослідження завершили, і Умбрелскул лишився спати в застої... до цієї миті."},
    [2509] = {n="Вексамус", d="Як один із найдосвідченіших професорів академії, Максдорму використовує свої сили бронзового дракона, щоб оживити уроки історії.\n\nХоча це й виходить досить повчально та весело, часом усе може піти не так. Вексамус — один з улюблених уроків професора Максдорму, але якщо хоч одна історична деталь неточна, він не забариться насварити будь-яких неслухняних учнів."},
    [2510] = {n="Каджин Незламна", d="Каджин Незламна кипить ненавистю до Хранителя Тіра за те, що той посягнув на стародавнє першоджерело під Тайргольдом. Води, що колись струменіли вічною есенцією Азероту, осквернені магією Порядку. Каджин прагне звільнити світ від лиховісного спадку титанів... за будь-яку ціну."},
    [2511] = {n="Первісне Цунамі", d="Вливальниця Сарія одержима бажанням повернути світ до того, чим він колись був: первісного краю стихій з нестримною могутністю. Вона зібрала всю свою волю та хитрість, щоб призвати Первісне Цунамі — стихійну істоту, достатньо сильну, аби повалити споруду Хранителя Тіра й повернути води джерела до їхнього природного стану."},
    [2512] = {n="Здичавілий Прадавень", d="Професори Містакрія та Ічістрасз застосували трохи забагато магії, намагаючись розчистити ботанічні лабораторії. Тепер у них на руках велика листяна проблема у вигляді Здичавілого Прадавня, що загрожує знищити всю їхню тяжку працю."},
    [2514] = {n="Відлуння Дораґоси", d="Директорка Дораґоса передбачила все, що стосувалося Академії Алґет'ар. Зокрема й складний симулякр самої себе, аби той дбав про щоденні справи та порядок, поки острови дрімали. Тепер, коли Академія знову відчинена, можливо, вона зможе скористатися ним, щоб наглядати за всіма новими учнями. Симулякр чудово впорався у міжчассі й, безперечно, є єдиним закляттям, яке не занепало за всі ці роки. Цілком стабільний і корисний. Хіба ні?"},
    [2515] = {n="Струнраан, Лихо Небес", d="Подейкують, що сама лиш присутність Струнраана змушує небеса плакати. Його буря електризує повітря й сіє руйнацію по землі. Притягнутий силою шквалу, Струнраан тепер загрожує землям і народу Рівнин Он'агри."},
    [2517] = {n="Базуал, Грізне Полум'я", d="Особливий зв'язок Базуала з Площиною Вогню дозволяє йому напряму висмоктувати силу з Вогняних Просторів. За допомогою сил Первісників Базуал відкриває дедалі більше порталів до Вогняних Просторів у Лазуровому Пругу."},
    [2518] = {n="Лісканот, Згуба Майбутнього", d="Наповнена незмірною крижаною силою, Лісканот наглядає за землею, завойованою Первісниками. Сама її присутність проймає холодом до самих кісток усіх, хто стрічає її. Якщо її завоювання не спинити, Лісканот знищить кожного, хто наважиться вступити до Талдразуса."},
    [2519] = {n="Фіракк Палаючий", d="Переповнений силою тіньового полум'я й тримаючи легендарну сокиру Фір'алат, Розривач Снів, Фіракк тепер готується поглинути енергії самого Амірдрассілу."},
    [2520] = {n="Лускокомандир Саркарет", d="Як очільник Розколотого Полум'я, Лускокомандир Саркарет відколовся від решти дракторів, щоб викувати нове майбутнє. Відтоді він повів свої сили до Аберрусу, сповнений рішучості заявити права на спадок, який, на його думку, по праву належить його роду, і ладен на все, аби заволодіти ним."},
    [2521] = {n="Хронікар", d="Хронікар присвятила все своє життя служінню нескінченному рою драконів, підіймаючись у званнях, доки не здобула титул командирки. Навіть серед радикальних Нескінченних її фанатизм не має рівних. Як шанована тилова варта, вона ні перед чим не спиниться, аби покласти край будь-кому, хто наважиться протистояти її ордену."},
    [2522] = {n="Каззара, Пекловикувана", d="Хоча Нелтаріон сам почав використовувати їх значно пізніше, він експериментував з елементієвими пластинами ще в ранні дні Аберрусу. Кінцевим результатом поєднання елементію й тіньового полум'я стала Каззара, яку визнали надто нестабільною для звільнення. Доведена до божевілля нестерпним болем своїх елементієвих пластин, вона тепер слугує вартовою Затіненого Горнила."},
    [2523] = {n="Відлуння Нелтаріона", d="Захований у глибинах Горнила Тіней, санктум Нелтаріона був місцем притулку й досліджень для Земного Вартового. Дехто каже, що відлуння його могутньої присутності досі затримуються тут, розмірковуючи про майбутнє чорної зграї драконів і про те, як здобути силу, що забезпечить його успіх."},
    [2524] = {n="Напад заратті Закалі", d="Очолена воєначальником Каґні, бойова ватага Закалі розпочала всеосяжний штурм Горнила Тіней у пошуках свого зниклого Старійшини, Рашока. Жорстокий і безжальний, Каґні готовий вдатися до будь-якої тактики, аби досягти мети."},
    [2525] = {n="Рашок, Старійшина", d="Ув'язнений в Аберрусі тисячоліттями, старійшина Закалі Рашок невпинно віддавав лютий вогонь усередині себе, щоб живити збочену лабораторію Нелтаріона. Стільки часу на межі смерті звело старійшину з розуму. Якщо він вирветься на волю, його помста спустошить зали Горнила Тіней."},
    [2526] = {n="Тір, Вічний Хранитель", d="Тепер, коли справжню часову лінію змінило піднесення Мурозонда, герої Азероту стикаються з безліччю дивовиж. Найбільша з них — те, що Титан-Хранитель Тір об'єднався з нескінченною зграєю драконів. Його легендарна відданість обернулася проти них, і героям Азероту не лишається нічого, окрім як битися. І перемогти."},
    [2527] = {n="Магморакс", d="Вирощений Нелтаріоном змалечку, Магморакс має лиш одне сильніше за свою відданість — апетит. Лавова гідра охороняє прохід до найглибших палат Горнила Тіней, надійно ховаючи таємниці свого володаря від цікавих очей."},
    [2528] = {n="Втілені Часові Шляхи", d="Втілення самих пісків часу. Ця прадавня істота завжди спостерігає, завжди чекає миті, коли Часовим Шляхам загрожує небезпека. Вона не змогла зупинити нескінченна зграя драконів, коли той прорвався в минуле. Тепер, постаючи перед новими зайдами, вона відмовляється зазнати поразки вдруге."},
    [2529] = {n="Палата Злиття", d="Вічне Полум'я палає жаром тисячі сонць, а Есенція Тіні розквітає втіленою темрявою. Хоча кожна з них надзвичайно могутня сама по собі, поєднавшись, вони вибухають нестримною силою тіньовогню, породжуючи вихор остаточного руйнування."},
    [2530] = {n="Забуті Експерименти", d="Створення драктирів дало чимало варіацій, одні вдаліші за інших. Ранні версії експерименту виявилися надто нестійкими, щоб їх знищити. Заціпенілі впродовж тисяч років, ці витвори нині пробудилися й прагнуть випробувати свою міць проти захисників Азероту."},
    [2531] = {n="Старійшини Закалі", d="Вакан і Голна, могутні старійшини джарадинів, кожен володіє своєю стихією. Голна — лавою, а Вакан — тіньовогнем, і вони перебувають у безперервній суперечці про те, хто з них сильніший. Через спустошення й хаос кожен старійшина намагається перевершити іншого, доки одного з них не увінчають переможцем."},
    [2532] = {n="Пильний Наглядач, Зскарн", d="Давним-давно Зскарну було доручено випробовувати стійкість експериментів Нелтаріона. Лише найсильніші проходили перевірку й зберігали життя. Найновіші гості Горнила Тіней привернули його непохитну увагу, та здобути його схвалення буде значно важче."},
    [2533] = {n="Загублене в часі бойовище", d="Одна з численних битв між Альянсом і Ордою просочилася в Часоплини, і саме героям Азероту належить покласти край цій часовій аномалії, щоб продовжити свою подорож. Та спершу їм доведеться стати на герць із Ґроммашем Хеллскрімом, одним із наймогутніших вождів Орди. За Альянс!"},
    [2534] = {n="Загублене в часі бойовище", d="Одна з численних битв між Альянсом і Ордою просочилася в Часоплини, і саме героям Азероту належить покласти край цій часовій аномалії, щоб продовжити свою подорож. Та спершу їм доведеться стати на герць із Андуїном Лотаром, одним із найвидатніших полководців Альянсу. За Орду!"},
    [2535] = {n="Зараза Ґалакронда", d="Цих первородних драконів повернули до життя некротичні енергії, що сочаться з трупа Ґалакронда. Анзон — це тріскотливий голод бурі. Дажак — всепоглинальна ненажерливість полум'я. Лоскелет — проникливе виснаження холоду. А герої Азероту видаються їм ласою поживою..."},
    [2536] = {n="Морчі", d="Морчі — це альтернативна форма Хромі, породжена часовою лінією, де піднявся Мурозонд, а нескінченні запанували над усім. І так склалося, що їй цілком до вподоби бути частиною справжньої часової лінії, і вона хотіла б, аби так і лишалося. На жаль, герої Азероту знову й знову стають на заваді її планам."},
    [2537] = {n="Іридикрон Камінношкірий", d="Іридикрон — могутнє Втілення, що володіє і силою, і терпінням самої землі. Він прагне повалити Аспектів і звільнити світ від впливу титанів. Однак достеменно його задуми поки що невідомі. Чому він об'єднався з нескінченними? Хай якою буде відповідь, його слід зупинити."},
    [2538] = {n="Хроно-Лорд Дейос", d="Нарешті нескінченна зграя драконів провістить новий світанок для світу Азероту. Хроно-Лорд Дейос вирушив далеко в минуле, щоб упевнитися, що Мурозонд підніметься. Герої Азероту вже бачили, як йому одного разу вдалося це здійснити. Чи зможуть вони зупинити його цього разу?"},
    [2553] = {n="Лародар, Хранитель Полум'я", d="Колись вірний захисник гаю, Лародар піддався владі полум'я. Тепер спотворений вартовий одержимий бажанням обернути на попіл Сон — і всіх, хто стане йому на шляху."},
    [2554] = {n="Іґіра Жорстока", d="Рухома жорстокістю, Іґіра здатна кувати нищівну зброю з криків своїх ворогів. У квітучому царстві Смарагдового Сну катувальниця прагне розширити свій арсенал."},
    [2555] = {n="Рада Снів", d="Рада Снів непохитна у своєму обов'язку захисників. Піп вдається до смертоносних хитрощів, щоб збити з пантелику своїх жертв, тоді як Урктос покладається на грубу силу, щоб трощити ворогів. Аервінн використовує мудрість і кмітливість, щоб панувати на полі бою та скеровувати своїх побратимів із ради."},
    [2556] = {n="Німуе, Ткаля Циклу", d="Німуе оселили в цьому квітучому царстві, коли Еонар і Фрея формували Сон. У Храмі Джерела вона впроваджує й оберігає лад Смарагдового Сну, вплітаючи його дику природу в складні візерунки."},
    [2557] = {n="Волкоросс", d="Кажуть, що Волкоросс, лавовий змій, такий велетенський, що жодна істота не прожила достатньо довго, аби побачити його цілком. Тепер ця гігантська гадюка обвиває собою Смарагдовий Сон, щоб поглинути його повністю."},
    [2559] = {n="Блейзікон", d="Живе полум'я прагне поживи. Блейзікон вічно палає в Темнополум'яній Розщелині, киплячи злобою та люттю. Віддані прислужники-кобольди вшановують його тут, бо його вогняне царство оточене жахливою пітьмою. Фанатичні кобольди радо вгамували б голод цього чудовиська, принісши в жертву... тебе."},
    [2560] = {n="Свічковий король", d="Свічковий король був тиранічним володарем кобольдського королівства. Його піддані гарували в шахтах, доки чужинець здалеку не вкрав його корону й не скинув його з трону. Тепер він утік углиб Темнополум'яної Розщелини, кипить від люті й погрожує повернутися. Згаси його полум'я раз і назавжди."},
    [2561] = {n="Пітьма", d="Які жахіття чаяться в тінях? Чому кобольди тримають свічки запаленими? Крихітні створіння туляться біля багать, переказуючи перекази про прадавнє зло. ПІТЬМУ можна здолати, та неможливо знищити. Натомість вона неминуче повертається в новій моторошній подобі. Тримайся світла. ПІТЬМА ЧЕКАЄ."},
    [2562] = {n="Ауростор, Сплячий", d="Ауростор дотримується суворого розпорядку сну. Напад Фіракка на Смарагдовий Сон порушив цей цикл, надто рано збудивши Дикого Бога фурболгів з його дрімоти. Позбавлений сну, цей розлючений Дикий Бог нападає на кожного перехожого, намагаючись виснажити сам себе."},
    [2563] = {n="Смолдерон", d="Ставши новим Володарем Вогню, Смолдерон вивільнив силу Вогняних Земель, щоб розширити свої володіння й спопелити Смарагдовий Сон."},
    [2564] = {n="Ґнарлрут", d="Колишній відданий захисник Смарагдового Сну, цей колись величний прадавень був спустошений полум'ям і тепер прагне лише руйнувати."},
    [2565] = {n="Тіндрал Сейджсвіфт, Провидець Полум'я", d="Одержимий бажанням повернути калдораям безсмертя, Тіндрал Сейджсвіфт погодився співпрацювати з Фіракком. На порозі перемоги Фіракка Провидець Полум'я стає проти захисників Азероту, готовий зробити так, щоб Амірдрассіл відродився у вогні."},
    [2566] = {n="Кіріосс", d="Штормокрук Штормового вартового Ґоррена, хоч і спотворений магією Порожнечі, досі віддано б'ється поряд з ним. І якщо хтось стане на його шляху, Кіріосс сумлінно роздере його на шматки."},
    [2567] = {n="Штормовий вартовий Ґоррен", d="Колись заступник Штормового стража Бейлґріма, Штормовий вартовий Ґоррен був спотворений магією Порожнечі, через що його ненависть до Бейлґріма роз'ятрилася. Послуговуючись новоздобутими силами Порожнечі, він прагне захопити Штормовий Сідал і повести власну армію Вершників Порожнечі, створену зі спотворених Штормових вершників."},
    [2568] = {n="Чудовисько з Каменю Порожнечі", d="Гротескне поєднання спаплюжених штормових вершників, ця височенна маса сили Порожнечі знає лише біль і те, як його завдавати. Знищити її - єдиний спосіб очистити Штормосідало та його гніздовище."},
    [2569] = {n="Старий Воскобород", d="Здоров! Присядь на хвильку. Послухай про Старого Воскоборода. Кобольди шанують цього старого за те, що приборкав Ґнота, найбуйнішого крота на всьому світі! Воскобород бачив, як одні приходять, а інші йдуть. Тепер усім заправляє Свічковий Король. Та це нічого не міняє! Тобі однаково треба триматися подалі від його володінь! Чого ти тут? Ану геть! Забирайся!"},
    [2570] = {n="Барон Браунпайк", d="Убитий горем через смерть свого брата, барон Браунпайк присягнув на вірність пріоресі Мурпрей. Могутній лицар тепер слугує її особистим виконавцем, оберігаючи таємниці пріорату як від чужинців, так і від недостатньо відданих араті."},
    [2571] = {n="Капітан Дейлкрай", d="Капітан Дейлкрай керує землями Пріорату Священного Полум'я. Він муштрує послушників у схвалених бойових дисциплінах імперії й дбає про те, щоб їхній вишкіл і відданість відповідали імперським міркам."},
    [2572] = {n="Е.Д.Н.А.", d="Протоколи захисту активовано! Земляний автомат оборони та нейтралізації працює. Неофіційна назва: Е.Д.Н.А. Цей голем має заготовки на будь-якого можливого зловмисника. Убивати скардинів - його головна директива, та будь-який непроханий гість - достатня причина для смертельної відповіді."},
    [2573] = {n="Пріореса Мурпрей", d="Пріореса Гелсі Мурпрей наказала звести Пріорат Священного Полум'я, щоб споглядати священну зорю Беледар. Збагнути видіння імператора виявилося годі. Натомість вона розкрила таємниці Священного Полум'я, які принесуть їм перемогу над ворогами в Геловфоллі та вдома, в імперії."},
    [2579] = {n="Скармарак", d="Високий Речник згаяв незліченні роки, намагаючись відновити Машину Пробудження. Одна невдала спроба породила новий жах: голема, просоченого скверною скардинів. Кристали посилюють його стихійну будову. Хоч він майже не виявляє свого чужорідного розуму, його ненависть до всього сущого незаперечна."},
    [2580] = {n="Речниця Тінокорона", d="Нова провідниця Ордену Ночі, Тінокорона уклала союз з Адж-Кагетом і задумала зухвалий план - викрасти флагман Світанковий Руйнівник. Колишня палка послідовниця Пріорату, вона занурилася в пітьму Тіні Беледара."},
    [2581] = {n="Ануб'іккай", d="Ануб'іккай - один з найблискучіших тактиків королеви Ансурек. Прискіпливий стратег, відомий винахідливим використанням місцевих ресурсів. Його воїни віддані йому до фанатизму."},
    [2582] = {n="Речник Порожнечі Ейріх", d="Ейріха скинуто, його владу відібрано! Подоланий, він утік до найпотаємнішого святилища Кам'яного Сховища. Та попри всі свої підступи, він піддався перетворенню: енергія Порожнечі з несправного артефакту паплюжить його живий камінь! Містичні одкровення тепер трощать його розум."},
    [2583] = {n="Аваноксс", d="Покинута напризволяще, коли Ара-Кара перетворилася на руїни, істота, відома як Аваноксс, починала всього лиш скромною павучихою. Роки самоти в краю, багатому на поживу, дали їй змогу безперешкодно рости, і тепер вона наглядає за своїми дітьми, своїми послідовниками й своєю територією, не маючи рівних ні розмірами, ні лютістю."},
    [2584] = {n="Ануб'зект", d="Хоча Ануб'зект ще не заслужив власного піднесення, йому випала честь наглядати за збиральницькою операцією Ара-Кари. Шалено тактичний і неймовірно сильний, Ануб'зект не вагатиметься втрутитися, якщо його війська виявляться нездатними оборонити Ара-Кару."},
    [2585] = {n="Кі'катал Жниця", d="Як одна з піднесених Ансурек, Кі'катал отримала завдання наглядати за збиранням Чорної Крові біля самого підніжжя цитаделі своєї королеви. Сувора й невблаганна, Кі'катал не спиниться ні перед чим, щоб збирання тривало, і використає кожну посилену здібність, що є в її розпорядженні."},
    [2586] = {n="Майстер-броварник Алдрір", d="Шинкар і майстер-броварник медоварні, Алдрір має в кранах не лише мед. Хто стає на шляху новому керівництву Медоварні Глутбрю, той стає на шляху Алдріру, а в нього багато друзів у темних місцях."},
    [2587] = {n="І'па", d="Породження виробничої аварії, медовий елементаль І'па лютує через своє існування так само, як і через те, що порушують спокій його медоварні. Це повнокровне втілення вогняного удару медовухи Глутбрю, і він укладе пластом кожного, хто з ним зчепиться."},
    [2588] = {n="Бенк Баззбі", d="Кваліфікація Бенка в бджільництві може бути сумнівною, та він, схоже, має хист до приборкання бджіл і налагодження видобутку меду. Проте його втручання обмежило волю бджіл і пожертвувало якістю меду, а цього стерпіти не можна."},
    [2589] = {n="Ґолді Баронботтом", d="Кмітлива ділка Ґолді Баронботтом упізнає добру нагоду з першого погляду, як-от Медоварню Глутбрю. Увірвавшись усередину й виштовхнувши Венбрандта з його справи, Ґолді здебільшого полишає роботу своїм поплічникам. Та навіть так вона не боїться засукати рукави й власноруч відлупцювати непроханих доброчинців."},
    [2590] = {n="Майстри-машиністи", d="Майстри-машиністи беруться за складну роботу на престижних будовах. Брокк і Дорліта працюють у парі стільки, скільки взагалі пам'ятають. Щоправда, продуктивність Брокка падає, та обоє вповноважені боронити свою будову прямими й дієвими проявами насильства."},
    [2593] = {n="Раша'нан", d="Крилатий жах із глибин Адж-Кахету. Раша'нан — таємна зброя королеви Ансурек, призначена знищити аратів, якщо її армії не спроможуться завоювати Мерелдар."},
    [2594] = {n="Оратор Крікс'візк", d="Оратор Крікс'візк із П'ятого Пасма не прагне нічого, окрім піднесення, і проводить свої дні, вихваляючи чесноти королеви Ансурек у надії здобути її ласку. Попри свою одержимість, він не беззахисний. Хто перейде дорогу Оратору, той дізнається, що гавкіт його куди, куди страшніший за укус."},
    [2595] = {n="Ікла Королеви", d="Близнюки Нкс і Вкс народилися разом, разом росли й разом навчалися мистецтва підступу та вбивства. Смертоносна пара, вони й піднесення своє здобули спільно. Тепер вони разом служать як Ікла Королеви, із насолодою усуваючи будь-яку загрозу владі Ансурек."},
    [2596] = {n="Ізо, Велика Зрощувачка", d="Еволюція здавна посідає центральне місце в житті неруб'ян, і ніхто не володіє цим процесом із більшою пристрастю та майстерністю, ніж Ізо. Отримавши від Ансурек методи піднесення, Ізо рішуче простує цим шляхом до досконалості, мало переймаючись тим, кому служить, заради чого і якою ціною."},
    [2599] = {n="Сікран, Капітан Сурекі", d="Сікран зажив слави зарозумілого дуелянта при дворі Королеви Ансурек. Жодного разу не зазнавши дотику ворожого клинка, Сікран усував суперників одного за одним, аж поки сама королева не проголосила його Капітаном Сурекі. Тепер цей незборимий боєць пильнує, щоб кожен, хто загрожує його королеві, поліг перед могутністю трону."},
    [2600] = {n="Коаґламат", d="Еволюційні досліди Великої Зрощувачки часто лишають по собі побічні продукти — відходи та твань. Декому ця огидна жижа здаватиметься непотребом, та для гострого розуму Ізо вона дає чудові матеріали для нових дослідів — і ховає в собі люту потвору, що тільки й чекає, аби ожити."},
    [2601] = {n="Принцеса-нексус Кай'веза", d="Принцеса-нексус Кай'веза прибула до Палацу Неруб-ар зовсім нещодавно й швидко стала довіреною особою Королеви Ансурек. Однак при внутрішньому дворі ходять чутки, що вона приховує темну й смертоносну таємницю. Якщо її викриють, принцеса готова безжально усунути всіх свідків..."},
    [2602] = {n="Королева Ансурек", d="Викривши зрадників при дворі, Королева Ансурек вирішує, що мусить сама знищити загарбників палацу. Та підозра щодо того, кому можна довіряти, гризе її душу. Коли союзників лишається дедалі менше, Королева Ансурек може звернутися до темних сил заради перемоги — навіть якщо це означає, що її найвідданіші воїни стануть її наступною поживою..."},
    [2607] = {n="Улґракс Пожирач", d="Еволюційні досліди Королеви Ансурек породили чимало жахливих стражів її трону, та немає серед них ненажерливішого за Улґракса Пожирача. Збожеволівши від нескінченного голоду, Улґракс став невситимим захисником двору Королеви Ансурек."},
    [2608] = {n="Шовковий Двір", d="Володар скарабеїв Ануб'араш і Прядильниця ниток Таказж — найдовіреніші радники Королеви Ансурек, проте ці двоє могутніх неруб'ян живлять одне до одного ненависть, ще сильнішу за відданість трону. Обрушуючи свою чималу силу на ворогів, кожен із них водночас бореться за те, щоб його товариш не вцілів."},
    [2609] = {n="Раша'нан", d="Спотворена дослідами Королеви Ансурек, Раша'нан із гордої неруб'янки перетворилася на жахливу крилату потвору. Ув'язнена у новому тілі, вона мордується розбитими спогадами про колишню себе, що ввергають Раша'нан у невгамовну лють."},
    [2611] = {n="Кровозв'язаний Жах", d="У темних ямах під Палацом Неруб-ар кров Прадавніх Богів застигає в смердючих чорних калюжах. Кровозв'язаний Жах постає з цього мерзенного слизу, затягуючи все на своєму шляху в Небачене."},
    [2612] = {n="Виводкокрут Ові'накс", d="Глибоко в нутрощах палацу королеви Виводкокрут Ові'накс проводить мерзенні досліди з чорною кров'ю, що знайдена в Аджкагеті. Цей огрядний жах важко чвалає печеристими глибинами палацу, відригуючи чорнильну багнюку на новонароджених, аби спостерігати її моторошні наслідки."},
    [2613] = {n="Рагк'Зор", d="Як головний наглядач Мертвих Копалень від Братства Дефаїв, Рагк'Зор стежить за робітниками та «спонукає» їх до праці. Його методи, хоч і незвичні, доволі дієві."},
    [2617] = {n="Генерал Умбрісс", d="Поки захисники Азерота та їхні союзники з-поміж червоних драконів штурмують ворота Ґрім Батола, лиховісний генерал Умбрісс веде до бою сектантів та сутінкову драконячу потороч, що боронять фортецю."},
    [2618] = {n="Драга Тінепал", d="Цей чорнокнижник культу Сутінкового Молота виконує доручення Бастіону Сутінків. Якщо герої здолають його вогняних поплічників, Драга відкриє їм лиховісне віщування для захисників Азерота."},
    [2619] = {n="Ерудакс, Герцог Низин", d="Дезвінг відрядив одного зі своїх наймогутніших намісників, аби той розкрив таємницю, яку кілька могутніх червоних драконів загинули, захищаючи. З печеристого царства Діпгольму цей безликий генерал явить нове покоління драконячої сили, щоб знищити тих, хто був досить нерозумний, аби кинути йому виклик."},
    [2620] = {n="«Капітан» Печивко", d="Печивко проголосив себе капітаном панцерника Братства Дефаїв після загибелі його попереднього командира. Хоч він і досі виконує свій офіційний обов'язок головного кухаря, кожен, хто бере під сумнів законність його капітанського титулу, зазвичай злягав із тяжким харчовим отруєнням."},
    [2621] = {n="Адмірал Рипснарл", d="Коли Джеймса Гаррінгтона спіткало прокляття воргена, він знищив свою любу родину та морську кар'єру за одну моторошну ніч кровожерливості. Узявши собі ім'я Рипснарл, він утік до Вестфоллу, а згодом погодився командувати грізним панцерником Братства Дефаїв."},
    [2622] = {n="Жнець ворогів 5000", d="Інженери Дефаїв провели багато довгих днів, удосконалюючи нову модель жниварки на основі агрегату «Жнець Ворогів 4000». Щойно її буде завершено, братство сподівається, що цей механічний жах різатиме броньованих солдатів Стормвінда, наче коса пшеницю."},
    [2623] = {n="Гелікс Шестерноламець", d="Колишньому ремісникові з картелю Трюмних Вод Геліксу запропонували суму, що затьмарювала все, що він міг би заробити безіменним інженером Орди, аби він займався своїм ремеслом для Братства Дефаїв. Він хутко погодився на цю роботу і зрікся колишньої відданості... як і вчинив би будь-який кмітливий ґоблін."},
    [2624] = {n="Глубток", d="У нападі люті Ґлубток вивільнив свої потужні магічні здібності й обернув свій оґрський пагорб на попіл. Прочувши про його руйнівні таланти, Дефаї найняли цього велетенського оґра-мага наглядати за робітниками як головного наглядача Мертвих Копалень."},
    [2625] = {n="Орта, Зламана Гора", d="Довго цей глибиноход крокував крізь провалля та легенди Азж-Кагету. Голос його — землетрус, воля — діамант, сила — незламна. Та нині він постає перед Азж-Кагетом, заражений темними пустулами чорної крові, прагнучи доброї смерті. Хто підведеться, щоб стати з ним на герць?"},
    [2626] = {n="Снід", d="Сніда найняли наглядачем над лісорубами за його нещадну ефективність. Мета його проста: збудувати велета якомога дешевше. Керуючи виробництвом за допомогою власноруч зібраного подрібнювача, він досягає лячно швидких результатів."},
    [2627] = {n="Ковальмайстер Тронґус", d="Цей велетенський еттин — коваль культу Сутінкового Молота, що з радістю пускає в хід викувані ним зброю та обладунки, аби нищити зайд."},
    [2628] = {n="Ґілнід", d="Ґілнід — майстерний інженер і головний плавильник у справах Братства Дефаянтів. Він пильнує, щоб велет був споряджений достатньою кількістю гармат і набоїв, і не терпить жодних перерв, доки робота не завершена."},
    [2629] = {n="Пан Кара", d="Як перший помічник капітана Зеленошкіра, Кара має тримати команду в напрузі. Він умілий зброяр, навчений усіляких способів різати, трощити, а часом і пробивати влучним пострілом."},
    [2630] = {n="Капітан Зеленошкір", d="Капітан недобудованого велета, Зеленошкір родом із Бухти Здобичі, де колись очолював флот піратських суден."},
    [2631] = {n="Едвін Венкліф", d="Колишній очільник Гільдії Каменярів, Венкліф через чвари з Палатою Шляхти покинув Стормвінд і заснував Братство Дефаянтів. Згодом Венкліф обрав Мертві Копальні за осідок, щоб збудувати велета, з якого почалася б його відплата."},
    [2632] = {n="Печивко", d="Ніхто, окрім Едвіна Венкліфа, не знає, як і чому Печивко стало корабельним кухарем. Та для піратів їжа є їжа."},
    [2633] = {n="Поштмейстер Мелоун", d="Мелоун не дарма став Поштмейстером — пошта йому небайдужа. Навіть у нинішньому своєму стані він відданий справі підтримання стабільності поштової системи. Якщо ж цій системі загрожуватиме розлад, Мелоун, либонь, муситиме взяти справу у власні руки."},
    [2635] = {n="Скупчення Жахіть", d="Потвора, народжена з осквернених Порожнечею решток скардинів, Скупчення Жахіть постає єдиною монструозною цілісністю. Ця моторошна істота готова наслати свою жахливу пошесть на Дзвінкі Глибини."},
    [2636] = {n="Шуррай, Жах Підводних Глибин", d="Морське дно ховає страхіття, що годі й уявити. Близькість Голловфолу до Підводдя наближає місто до володінь істот глибин, і кобіси прагнуть скористатися цим. Їхні закляття піднімають Шуррая, Жах Підводних Глибин, аби сіяти спустошення на їхніх мисливських угіддях. Шуррай — це поєднання найгірших жахів і гнилої плоті безодніх глибин, і араті знадобиться вся можлива допомога, щоб його спинити."},
    [2637] = {n="Кордак, Дрімотний Захисник", d="Ледь дієздатний і майже забутий, Кордак через своє занепаде становище приречений лишатися дрімотним спостерігачем. Навіть відчувши Порожнечу десь унизу, він був змушений до бездіяльності. Та це змінилося. Невпізнанні форми життя, що прибули на острів Дорн, достатньо могутні, аби стати загрозою для Азероту. І тому він повстає проти нас. І тому ми повстаємо проти нього."},
    [2639] = {n="Віксі та Шестернедробарі", d="Віксі Повний Газ прокладає шлях жаху крізь серця всіх, кого зустрічає її ватага. Відповідаючи на заклик Ґаллівікса про допомогу, вона зі своєю командою прибула, щоб віддати давній борг і додати кілька нових масних плям на вулиці Андермайну."},
    [2640] = {n="Казан Різанини", d="Упродовж історії точилося чимало епічних воєн, та жодна не була такою вибуховою, як суперництво між гальванічною горилою Торком Бурею і розплавленим мехазавром Фларендо Лютим. Сьогодні всі ставки скасовано, коли ці два чемпіони зійдуться в казані для двобою, що загрожує розірвати Андермайн навпіл! Стань свідком різанини або зганьби весь гоблінський рід."},
    [2641] = {n="Рік Реверб", d="Рік Реверб обожнює гуркіт вибуху, тріск феєрверка і, найголовніше, звук власного голосу. Зі свого летючого звукового резонатора Рік служить Ґаллівіксу за розпорядника гулянь, зачаровуючи мешканців Андермайну захопливими й смертоносними гоблінськими бітами."},
    [2642] = {n="Стікс Брухтошрот", d="Можна сказати, що немає важливішої міської служби за вивіз сміття... принаймні так хотів би тебе переконати Стікс Брухтошрот. Стікс і його бригада прибиральників вигадують винахідливі способи позбуватися всього непотрібного й невимовного в місті, відколи хто себе пам'ятає."},
    [2644] = {n="Однорукий Бандит", d="Однорукий Бандит — найкращий гральний автомат у казино Ґаллівікса. Усе, чого просить цей чарівний пристрій, — це грати чесно й не шахраювати. Правила, за якими він це визначає, лишаються загадковою таємницею, проте однорукої кари, яку він роздає, годі не помітити."},
    [2645] = {n="Муг'Зі, Очільники Охорони", d="Друзяки від самого народження, дві голови Муг'Зі вінчають велетенську тушу здорованя-оґра-наглядача, найнятого Ґаллівіксом, щоб наглядати за щоденними справами його казино. Останніми тижнями Муг'Зі дістав нове завдання — не пускати геть нікого до найпотаємніших покоїв Галаджіо."},
    [2646] = {n="Хромований Король Ґаллівікс", d="Здійснивши «стратегічний відступ», Джастор Ґаллівікс зачаївся в залах Галаджіо. Хай над чим працював Ґаллівікс, воно напевно могутнє, смертоносне й здатне розчавити будь-кого, хто стане йому на заваді."},
    [2648] = {n="Велика М.А.М.А.", d="Прототип меха під кодовою назвою Велика М.А.М.А., керований Сільвою Стратоіскрою, розгорнули на Водогінних спорудах задля операційної безпеки на службі планів Ґаллівікса. Цей мех хизується запаморочливим набором засобів зв'язку, підсиленим дослідами Темноплавів над Чорною Кров'ю."},
    [2649] = {n="Руйнівний дует", d="Кіза Квікф'юз і Бронт — це дует мозку й сили з картелю «Авантюра», найнятий Ґаллівіксом, щоб провести «вибухову реструктуризацію» греблі Водогінних споруд. Кіза розквітає від безоглядного руйнування, а Бронт «розквітає», прибираючи рештки, які вона лишає по собі."},
    [2650] = {n="Болотопикий", d="Під річковим дном біля Водогінних споруд спить приспаний звір. Серед метушні навколо греблі Болотопикий прокидається й виринає з багна в сонній люті, готовий розчавити перше, що поворухнеться."},
    [2651] = {n="Ґізл Ґіґазеп", d="У серці греблі Водогінних споруд електричний геній Ґізл Ґіґазеп викачує енергію для «ПРОЄКТУ». Коли його заганяють у кут і таємні плани Ґаллівікса майже зриваються, Ґізл перенаправляє енергію, призначену для Андермайну... на самого себе!"},
    [2653] = {n="Зубчастоторговець Локенсток", d="Як один із найкращих умів Ґаллівікса, Зубчастоторговець Локенсток не вміє казати «ні» інноваціям, тож його список винаходів тягнеться куди довше за конвеєри на його заводі. Вічно намагаючись зрізати водночас і кути, і витрати, Локенсток постійно шукає нові ринки, щоб випробувати свої пристрої."},
    [2654] = {n="Чоппер Редгук", d="Жорстокості Чоппера Редгука бояться по всьому Кул-Тірасу. За підтримки сил Залізного припливу Чоппер вільно лютує по Боралусу, насолоджуючись хаосом, що шаленіє на вулицях."},
    [2655] = {n="Ембердон", d="Ембердон оселилася в садах Шпиля Віндраннерів, шукаючи місце, де виростити своє потомство. Вкрай територіальна, вона стереже своє гніздо з пекучою люттю."},
    [2656] = {n="Занедбаний дует", d="Банші Каліс та її вірна потвора Латч ведуть гурт фанатичних послідовників Сильвани Віндраннер. Вони прибули до Шпиля в пошуках реліквій із будь-яким відлунням есенції Темної Володарки, готові на все, щоб їх роздобути."},
    [2657] = {n="Командир Кролук", d="Командир Кролук колись бився у Другій війні — конфлікті, що обірвав життя брата Аллерії Віндраннер, Лірата. У своєму горі Аллерія винищувала кожного зі Старої Орди, кого могла знайти. Мстиві духи переможених нею тепер блукають Шпилем."},
    [2658] = {n="Неспокійне серце", d="Народжений із горя та гніву родини Віндраннерів, мстивий дух колись гордої генерал-рейнджерки блукає залами покинутого родового дому. Лише зустрівши гідного супротивника, він зможе впокоїтися й нарешті віднайти спокій."},
    [2659] = {n="Арканотрон-вартовий", d="Цей вельми досконалий арканний конструкт призначено берегти мир і стежити, щоб усі Магістри дотримувалися правил та обмежень. Відхилення від цих правил не толеруватиметься."},
    [2660] = {n="Гемеллус", d="Потойбічне поріддя, що походить з Порожнечі, Гемеллус, схоже, використовує Порожнечу не лише для власного захисту, а й для розмноження та сприяння розвитку свого виду."},
    [2661] = {n="Серанель Сонцебій", d="Майстерний руйнівник чарів, Серанель Сонцебій здобув цілковиту довіру магістрів. Йому доручено охорону Осердя Сутінків, і Серанель виконає цей обов'язок навіть ціною власного життя, якщо буде потрібно."},
    [2662] = {n="Дегентрій", d="Могутнє створіння Порожнечі, Дегентрій скористався нагодою, яку ненавмисно надав магістр Умбрик, і вчинив напад на Терасу."},
    [2663] = {n="Лорд Роккор", d="Лорд Роккор зневажає інтриги та підступність інших вогняних елементалів. Щоб не служити поряд зі своїми родичами в Розплавленому Ядрі, ця могутня істота навмисне розгнівала Володаря Вогню. Ризикована гра Роккора виправдалася: його вигнали з Ядра й змусили в самоті стерегти Глибини Чорноскелі."},
    [2664] = {n="Бейл'Ґар", d="Жахливий розплавлений велетень Бейл'Ґар ступає Шляхом Чорножелізних — приголомшливим витвором гномської інженерії, висіченим у Глибинах Чорноскелі. Раґнарос видобув велетня із серця Теренів Вогню, щоб той стеріг величезні запечатані двері на одному кінці шляху. За легендою, лише Володар Вогню та найвищі чини клану Чорножелізних знають, що криється за цими таємничими ворітьми."},
    [2665] = {n="Лорд Інцендій", d="Барон Ґеддон навчив Інцендія керувати його руйнівною силою, та барон ніяк не сподівався, що його підопічний стане таким смертоносно вправним. Дедалі більше остерігаючись, що Інцендій його скине, Ґеддон вислав палахкого елементаля з Розплавленого Ядра стерегти легендарне Чорне Ковадло гномів Чорножелізних."},
    [2666] = {n="Лорд-голем Арґельмах", d="Довічна одержимість Арґельмаха безсмертям спонукала його кувати зачаровані конструкти на власну подобу. Подейкують, що він також заходився коло якоїсь чорної магії, яка дала б новим витворам лорда-голема стати вмістилищами для його духа, якби його тіло з плоті й крові було знищене."},
    [2667] = {n="Семеро", d="Багато століть тому тан-чародій Тауріссан і семеро його наймогутніших союзників серед Чорножелізних випадково прикликали Раґнароса до Азероту й прирекли весь свій клан на рабство. Хоча Семеро загинули під час ритуалу, їхні неспокійні духи досі блукають Глибинами Чорноскелі, проклятими служити своєму повелителю-елементалю та нинішньому правителю Чорножелізних."},
    [2668] = {n="Генерал Гнівокуй", d="За все життя, присвячене вивченню, генерал Гнівокуй став знавцем гномської військової історії та тактики. Нещодавно він накликав на себе лють імператора Даґрана Тауріссана, написавши нищівний трактат про поразки свого клану в минулих війнах. Та попри цей політичний прорахунок, Гнівокуй — Чорножелізний до самого осердя. Він проллє кров — а коли треба, і життя віддасть, — щоб захистити свій народ та свого імператора."},
    [2669] = {n="Посол Полум'ябій", d="За незмінну службу Раґнаросу Полум'ябій піднісся до рангу посла при клані Чорножелізних. Спершу ця ница істота зневажала своїх гномських союзників, але згодом перейнялася повагою до їхньої схильності до руйнування."},
    [2670] = {n="Імператор Даґран Тауріссан", d="Імператор Даґран Тавріссан править разом із принцесою Мойрою з ворожого клану Бронзборд. Досі точаться суперечки, чи зачарував імператор свою наречену, а чи вона приєдналася до нього з власної волі. Хай там як, присутність Тавріссана віщує лихо для майбутнього його клану. Доки він живий, дварфи Темного Заліза лишатимуться пішаками Раґнароса й страшною загрозою для королівств усього Азероту."},
    [2675] = {n="Азіккар", d="Пожирачі часто мандрують услід за Великими Червами-пожирачами, щоб дістатися нових світів і там бенкетувати. Азіккар не виняток. Він уривається в нову землю, прагнучи вгамувати свій нескінченний голод. Іноді його жертвами стають навіть інші пожирачі, та вони все одно йдуть на поклик Азіккара — пожирати або бути пожертим у вирі його безкінечного голоду."},
    [2676] = {n="Таа'бат і А'вадж", d="Як правиця Скрижальниці Доль, Таа'бат не спиниться ні перед чим, аби виконати її волю. Цей повелитель звірів зв'язав себе з диким викривлоступом А'ваджем і опанував його унікальні таланти. Тепер ця пара діє як одне ціле, входячи у фазу й виходячи з неї, щоб уразити кожного, хто загрожує помсті Скрижальниці Доль."},
    [2677] = {n="Скрижальниця Доль", d="Колись Скрижальниця Доль очолювала оракулів К'ареша, та знищення їхнього світу загнало їх у пустища, де вони почали хрестовий похід помсти. Вона дала прадавні клятви знищити ворогів Салгадаара й усе, що ті збудували. Тепер, коли вона знову віднайшла свою прадавню силу, доля цього купола виглядає похмурою."},
    [2679] = {n="Кистія Манасерце", d="Хоч Кистія Манасерце й була досвідченою магістеркою, вона надто полюбляла магію Скверни, щоб зовсім від неї відмовитися. Тож не дивно, що вона стала затятою прибічницею й спільницею підпільної контрабанди Скверни в Завулку."},
    [2680] = {n="Заен Клинкожаль", d="Кмітливий, гострий на розум і владний, Заен Клинкожаль наглядає за поставками заборонених артефактів Скверни. Ті, хто йому підлеглі, виконують його накази дослівно... або платять за це сповна."},
    [2681] = {n="Ксатуукс Нищитель", d="Ксатуукс Нищитель — одна з найпотужніших істот, яких прикликала Літіель Сіндерф'юрі. Хоч він і ненавидить служити чорнокнижниці, та виконує її накази заради чистої, нутряної насолоди від руйнування."},
    [2682] = {n="Літіель Сіндерф'юрі", d="Літіель Сіндерф'юрі бачить у Войдштормі над Сільвермуном водночас і загрозу, і нагоду. Її народ наляканий, а в неї є ідеальне рішення... сила Скверни. Вона стверджує, що її контрабанда захищає народ від небезпеки згори, та прибутки, які вона отримує, — приємний додаток."},
    [2683] = {n="Ґобфазер", d="Колись гордість картелю Брудноводдя, цей мех був грізною силою в Куполі Руйнування. Вершина гоблінської винахідливості... доки хтось не забув замінити йому мастило. Тепер Король Купола Руйнування геть знавіснів, шаленіє й погрожує накликати хаос на мешканців Андермайну."},
    [2684] = {n="Вартова Плексуса", d="Вартова Плексуса патрулює колосальну машинерію Манакузні Омега, пильнуючи, щоб енергія зруйнованого світу К'ареш проходила крізь канали споруди. Уся вхідна енергія має бути стерилізована. Усі забруднення мають бути викорінені."},
    [2685] = {n="Душезв'язувачка Наазіндрі", d="У своїх темних покоях Душезв'язувачка Наазіндрі сковує вільні душі к'арешів, обертаючи їх на покірних слуг. Сповиті в шовкові пелени, її жертви постають зі своїх в'язниць, щоб служити волі Тіньової варти."},
    [2686] = {n="Лум'ітар", d="Лум'ітара навмисне виплекала Тіньова варта заради його унікального хисту насичувати арканною енергією свій незрівнянний шовк. Прикутий до своєї долі в механізмах манакузні, Лум'ітар безкінечно пряде котушки арканного шовку для своїх господарів."},
    [2687] = {n="Ткач Кузні Араз", d="Ткач Кузні Араз керує всіма роботами в манакузні Омега, забезпечуючи безперервний потік енергії до її центральної камери. Тепер він стоїть як перший свідок відродження Дименсіуса й прагне довести свою справу до кінця — за будь-яку ціну."},
    [2688] = {n="Мисливці на душі", d="Адарус Даскблейз — мисливець на демонів, переповнений силою безодні, що прагне поглинути енергію Порожнечі довкола манакузні Омега. Разом зі своїми смертоносними союзниками, Ілліссою Дарксорроу та Веларіном Бладрасом, він знищить усіх, хто стане їм на заваді."},
    [2690] = {n="Король Нексуса Салгадаар", d="Колишній володар К'арешу й заклятий ворог Дименсіуса, Король Нексуса Салгадаар постав незламним із розтрощеної оболонки К'арешу. Верхи на своєму Королівському крилі Порожнечі Салгадаар тепер очолює найвищу волю Тіньової варти. Клятви буде виконано. Усі скоряться."},
    [2691] = {n="Дименсіус Всепожирач", d="Глибоко в надрах манакузні Омега Дименсіус — Всепожирач і руйнівник К'арешу — повільно пробуджується, поки його віддані прибічники-ефіріали живлять його за допомогою Темного Серця. Якщо їм це вдасться, вони вивільнять істоту незбагненної сили, що здатна знищити саму тканину реальності."},
    [2733] = {n="Імператор Аверзіан", d="Імператор Аверзіан веде невпинну війну, прагнучи не завоювання, а цілковитого знищення. Уся його воля підкорена єдиній меті: розірвати запону між світами й прорубати пролом у саму Порожнечу. Крізь цю рану ринуть його незліченні полчища й затоплять Азерот пітьмою."},
    [2734] = {n="Воразіус", d="Велетенський хижак, народжений у пустках Войдшторму, Воразіус виріс до неймовірних розмірів, живлений невгамовним голодом. Прикликане Світлом Порожнечі Евердоном до битви, що вирує біля підніжжя Шпиля Порожнечі, це колосальне чудовисько тепер пожирає обидві сторони."},
    [2735] = {n="Вейлґор і Еззорак", d="Народжені з однієї кладки в червоному драконячій зграї, Вейлґор і Еззорак колись були хранителями всього живого. Тепер, скривлені темною волею Ксал'атат, від їхньої колишньої сутності лишився єдиний незламний зв'язок одне з одним."},
    [2736] = {n="Полеглий Король Салгадаар", d="Повставши проти Ксал'атат, полеглий король Салгадаар став бранцем тієї самої Тіньової варти, якою колись командував. Закатований, маячливий і просякнутий Порожнечею, він чекає на свою смерть — або на нагоду здобути своєму народові свободу з лабет Ксал'атат."},
    [2737] = {n="Засліплений Світлом авангард", d="Колись взірці Світла, Сенн, Беллемі та Лайтблад піддалися власному сліпому завзяттю — їхня віра спотворилася на безжальний фанатизм, що тепер змушує їх карати всіх, хто стане їм на заваді."},
    [2738] = {n="Корона Космосу", d="Високо на Шпилі Порожнечі Ксал'атат збирає свою темну армію з усіх куточків Войдшторму. За підтримки Тураліона, Аратора й Аллерії смертні Азероту мусять стати їй на шляху, перш ніж вона обрушить міць Шпиля Порожнечі на своїх ворогів."},
    [2739] = {n="Бело'рен, Дитя Аль'ара", d="Один з останнього виводка Аль'ара, Бело'рен був вирощений, щоб захищати острів Кель'Данас. Після подій на Шпилі Порожнечі Бело'рена пронизала Порожнеча. Розгублений і щойно вилуплений, фенікс зосереджений на єдиному завданні: не дати жодному загарбникові дістатися Сонячного Колодязя."},
    [2740] = {n="Настання Півночі", d="Колись створіння Світла, Л'ура давно впала в Порожнечу на Аргусі, її есенцію висмоктала Аллерія Віндраннер у Престолі Тріумвірату. Звільнена від своїх пут, темні енергії Л'ури тепер загрожують самому Сонячному Колодязю."},
    [2747] = {n="Фрактіллус", d="Елементаль, народжений зі скель і дюн навколо манакузні, Фрактіллус боронить свої володіння, орудуючи силою колючих пісків і загартованого скла цих негостинних пустищ."},
    [2762] = {n="Решанор Відв'язаний", d="Ефіріали К'ареша вперше побачили цю руйнівну пащу Порожнечі після нападу Дименсіуса. Вони вірять, що Решанор постав як їхня вічна кара — адже він знову й знову повертається, щоб пожирати їх разом з їхньою планетою, нескінченно більшаючи рік за роком."},
    [2769] = {n="Трійця Світлоцвіту", d="Світлоцвіт зазнав страшної поразки, але, як і рутаані, яких він наповнює, він змінюється. Ці пронизані Світлоцвітом рутаані фанатично розростають свій лютий і всепоглинаючий сад."},
    [2770] = {n="Ікузз Світлоловець", d="Ікузз — грізний хижак, що колись вистежував здобич по всьому Гарандару. Тепер Світлоловець піддався нездоланній силі Світлоцвіту, і його ненаситний голод живить його ріст."},
    [2771] = {n="Світловартовий Руя", d="Колись шанований вартовий коренів Руя не зміг здолати Світлоцвіт самотужки. Зранена гордість штовхнула його черпати силу зі Світлоцвіту й використовувати її, щоб карати всіх інших, замість того щоб допомагати своїм союзникам."},
    [2772] = {n="Зіккет", d="Народжений з епіцентру Світлоцвіту, Зіккет був породжений і виплеканий ураженими Світлом рутаані, щоб стати нестримним рушієм поширення Світлоцвіту."},
    [2776] = {n="Скарбохапач", d="Гнаний ненаситною жадобою, ненажерливий Скарбохапач люто боронить схованки з їжею та припасами, які він викрав у сусідніх тролських племен. Перше випробування Налоракка — знищити його, поки племена не зголодніли."},
    [2777] = {n="Вартовий Зими", d="Пори року бувають лагідними або жорстокими. Вартовий Зими насилає найлютіші зимові бурі, щоб випробувати всіх, хто стане проти нього. Аби здолати друге випробування Налоракка, витримай пронизливий холод і переможи втілення зимової бурі."},
    [2778] = {n="Налоракк", d="Спочиваючи в неспокійному сні, повному битв, Налоракк, лоа Війни, випробовує відвагу лише гідних. Переживи його випробування й отримай благословення або загинь, намагаючись."},
    [2782] = {n="Скеледрев", d="Древній, як самі скелі, Скеледрев століттями дрімав під шатром височенних сосен. Розбуджений необачним вторгненням смертних, він повстає, щоб боронити свою галявину, підкоряючи самий ліс своїй волі."},
    [2791] = {n="Таз'Ра", d="Таз'Ра, найцінніший поборник доманаарів, змушений битися проти власної волі. Він вимагає власної смерті від кожного супротивника, сподіваючись, що кожен бій нарешті покладе край його стражданням."},
    [2792] = {n="Атроксус", d="Ув'язнений Хароном, цей зголоднілий бегемот сподівається на нову жертву, щоб втамувати свій апетит. Сама лиш велетенська величина Атроксуса майже така ж небезпечна, як отрута, яку він вивергає."},
    [2793] = {n="Харонус", d="Харонус, надміру самовпевнений і хвалькуватий власник Арени Шраму Порожнечі, вражений бойовою вправністю азеротян і вимагає їх для своєї грандіозної колекції."},
    [2795] = {n="Чимаерус, Невиснений Бог", d="Коли Альн'гару викрали з її Колиски, лишилися тільки біль і безум, що формували хаос Розлому. Чимаерус живився порожнечею, що зосталася, пожираючи інші жахітливі прояви. Тепер він постає як чудовисько в Розломі: істота муки й люті."},
    [2810] = {n="Муро'джин і Некраксс", d="Муро'джин — невблаганний слідопит, чиє завдання — захоплювати жертв для темних обрядів Лихогіллів. Некраксс, оживлений орел, вражає кожного, хто опирається полону його господаря. Не можна більше дозволяти їм постачати душі для некротичної магії Вордази."},
    [2811] = {n="Вордаза", d="Вордаза, повелителька душ Лихогіллів, чинить заборонені обряди, аби видобути есенцію душ мертвих. Вона переганяє страждання своїх жертв у чисту некротичну енергію, щоб наснажити Рак'тула, своє жахливе творіння. Її мерзенну магію та її чудовисько слід зупинити."},
    [2812] = {n="Рак'тул, Вмістилище Душ", d="Невмерлий раб, прив'язаний до Вордази, Рак'тул потворно роздутий есенціями змучених душ і некротичною силою. Сп'янілий від новоздобутої могутності й доведений до божевілля нескінченними стражданнями душ, Рак'тул готовий розтрощити Зул'Аман під нищівним тягарем своїх кулаків."},
    [2813] = {n="Головний Майстер Ядра Касрет", d="Головний Майстер Ядра Касрет і ефіріали Тіньової варти колись підтримували бездоганний потік енергії в Двигуні Іскри Ядра в Точці-Нексусі. Та осяйне сум'яття Лотраксіона зруйнувало їхню рівновагу. Тепер, сповнені недовіри й стомлені чужинцями, вони працюють, щоб відновити арканну гармонію, яка колись живила Точку-Нексус."},
    [2814] = {n="Вартова Ядра Нісарра", d="Вартова Ядра Нісарра охороняє Точку-Нексус Ксенас зі згасаючою силою. Позначена Світлом унаслідок нападу Лотраксіона, вона зачаїлася у своєму крилі, поранена й вичікує. Біля захисних споруд ядра вирує битва, і її лють обрушується на кожного, хто наважиться наблизитися."},
    [2815] = {n="Лотраксіон", d="Засліплений зрадою, Лотраксіон штурмує Точку-Нексус наодинці. Коли її захист зруйновано, він готується пробити Ядро Нексуса, ризикуючи ланцюговим вибухом, що міг би знищити Сільвермун і прокотитися хвилями по всьому Азероту."},
    [2827] = {n="Лу'ашал", d="Хоча Світлоцвіт у Лісі Вічної Пісні знищив значну частину місцевої дикої природи, кількох істот його сила, навпаки, зміцнила. Лу'ашал від навального потоку Святої енергії виріс до велетенських розмірів і тепер настільки ж небезпечний, наскільки й прекрасний."},
    [2828] = {n="Предаксас", d="Наситившись поріддям звивистого Войдшторму, Предаксас никає дикими землями в пошуках здобичі. Він не спочиває, він не мислить, він пожирає з голодом, таким же ненаситним, як і темрява."},
    [2829] = {n="Торм'белан", d="Колись лагідне створіння, що блукало південними дикими землями Гарандара, Торм'белан назавжди змінився, коли його вразив Світлоцвіт. Розлючену бестію тепер слід убити, перш ніж вона почне лютувати в навколишніх багнах."},
    [2869] = {n="Міфічні Ключі", d="У підземеллях міфічних ключів гравці б'ються з посиленими ворогами й намагаються пройти підземелля в межах відведеного часу."},
    [2870] = {n="Афікси", d="Афікси - це модифікатори, прив'язані до ключа, які змінюють хід гри в підземеллях міфічних ключів. Вони з'являються на міфічному рівні 2, з коригуваннями на міфічних рівнях 5, 7, 10 і 12."},
    [2711] = {n="Ротмайр", d="Фунґаріани Спорепаду виплекали грибного велета, що виріс далеко за межі свого природного циклу. Ротмайр — звір грубої сили, чиї спори здатні прискорювати ріст довколишніх грибів, плодячи нові небезпеки для необачних."},
}

