    ["Earth's Vengeance"] = "Помста Землі",
    ["Earthbind Totem"] = "Тотем земних пут",
    ["Earthbreaker Haromm"] = "Землелам Гаромм",
    ["Earthbreaker Missiles"] = "Снаряди землелама",
