    ["Necrotic Ichor"] = "Некротичний іхор",
    ["Necrotic Pitch"] = "Некротична смола",
    ["Necrotic Ritual"] = "Некротичний ритуал",
    ["Necrotic Smash"] = "Некротичний удар",
