    ["Venomous Blood"] = "Отруйна Кров",
    ["Venomous Discharge"] = "Отруйний Викид",
    ["Venomous Discharge Crystal"] = "Кристал Отруйного Викиду",
    ["Venomous Effusion"] = "Отруйний витік",
